const PRODUCTS=[{"id": 1000, "slug": "visions-pv-035-otw", "name": "Visions PV .035 OTW", "specialty": "vascular-periferico", "categories": [{"slug": "sonda-ivus", "name": "Sonda IVUS"}], "category": "Sonda IVUS", "brand": "Philips", "summary": "Catéter digital de ultrasonido intravascular (IVUS) diseñado específicamente para el diagnóstico en intervenciones arteriales y venosas periféricas. Proporciona imágenes transversales en tiempo real que permiten evaluar la morfología de la placa, medir con exactitud el lumen verdadero y confirmar la aposición óptima de los stents, minimizando la dependencia del medio de contraste.", "content": "<h3>Beneficios y Características:</h3>\n<ul>\n<li>\n<p><b>Adquisición digital: </b>Plug-and-play.</p>\n</li>\n<li>\n<p><b>Catéter guía mínimo 8.5F.</b></p>\n</li>\n<li>\n<p><b>Diámetro máximo de imagen 60mm.</b></p>\n</li>\n<li><strong>Marcas radiopacas cada cm de principio a fin.</strong></li>\n</ul>\n", "image": "assets/visions-pv-035.png", "pdfs": [{"url": "https://www.documents.philips.com/assets/20180620/c4f66a435f4c4fe6925fa905011e47d6.pdf", "path": "assets/documento-f7ad935cd287.pdf", "name": "Folleto Visions PV .035 · inglés", "label": "Folleto Visions PV .035 · inglés"}], "source": "https://academiayumyeong.com/alfacor/product/visions-pv-035-otw/", "quickType": "IVUS periférico digital", "quickSpecs": [["Longitud de trabajo", "90 cm"], ["Frecuencia nominal", "10 MHz"], ["Marcas radiopacas", "25 marcas separadas 1 cm en el eje distal"], ["Catéter guía", "Mínimo 8.5 Fr"], ["Campo de imagen", "60 mm"], ["Adquisición", "Digital, plug-and-play"]], "officialSource": "https://www.centralamerica.philips.com/healthcare/product/HCIGTD88901/visions-pv-035-catter-digital-de-ivus", "specificationSources": ["https://www.centralamerica.philips.com/healthcare/product/HCIGTD88901/visions-pv-035-catter-digital-de-ivus", "https://www.documents.philips.com/assets/20180620/c4f66a435f4c4fe6925fa905011e47d6.pdf"], "philipsGroup": "peripheral", "imageSource": "https://www.usa.philips.com/healthcare/product/HCIGTD88901/visionspv035digitalivuscatheter", "imageAlt": "Visions PV .035 · imagen oficial Philips"}, {"id": 999, "slug": "visions-pv-018-rx", "name": "Visions PV .018 RX", "specialty": "vascular-periferico", "categories": [{"slug": "sonda-ivus", "name": "Sonda IVUS"}], "category": "Sonda IVUS", "brand": "Philips", "summary": "Catéter digital de ultrasonido intravascular (IVUS) diseñado específicamente para el diagnóstico en intervenciones arteriales y venosas periféricas. Proporciona imágenes transversales en tiempo real que permiten evaluar la morfología de la placa, medir con exactitud el lumen verdadero y confirmar la aposición óptima de los stents, minimizando la dependencia del medio de contraste.", "content": "<h3>Beneficios y Características:</h3>\n<ul>\n<li>\n<p><b>Adquisición digital: </b>Plug-and-play.</p>\n</li>\n<li>\n<p><b>ChromaFlo: </b>Visualización a color del flujo de sangre en vivo.</p>\n</li>\n<li>\n<p><b>Catéter guía mínimo 6F.</b></p>\n</li>\n<li>\n<p><b>Diámetro máximo de imagen 24mm.</b></p>\n</li>\n</ul>\n", "image": "assets/visions-pv-018.png", "pdfs": [{"url": "https://www.documents.philips.com/assets/20240529/29b2c245ce9f46d181d6b17f00d6395f.pdf", "path": "assets/documento-7859ff9a1d65.pdf", "name": "Catálogo IVUS periférico · inglés", "label": "Catálogo IVUS periférico · inglés"}], "source": "https://academiayumyeong.com/alfacor/product/visions-pv-018-rx/", "quickType": "IVUS periférico digital", "quickSpecs": [["Longitud de trabajo", "135 cm"], ["Frecuencia nominal", "20 MHz"], ["Marcas radiopacas", "Cantidad y separación no especificadas en la IFU de Philips consultada"], ["Catéter guía", "Mínimo 6 Fr"], ["Campo de imagen", "24 mm"], ["Flujo", "ChromaFlo"], ["Adquisición", "Digital, plug-and-play"]], "officialSource": "https://www.documents.philips.com/assets/Instruction%20for%20Use/20171229/018c485873634b58bd23a8580150cb0e.pdf", "specificationSources": ["https://www.documents.philips.com/assets/Instruction%20for%20Use/20171229/018c485873634b58bd23a8580150cb0e.pdf"], "philipsGroup": "peripheral", "imageSource": "https://www.usa.philips.com/healthcare/product/HCIGTD86700/visions-pv-018-digital-ivus-catheter", "imageAlt": "Visions PV .018 · imagen oficial Philips"}, {"id": 998, "slug": "visions-pv-014-rx", "name": "Visions PV .014 RX", "specialty": "vascular-periferico", "categories": [{"slug": "sonda-ivus", "name": "Sonda IVUS"}], "category": "Sonda IVUS", "brand": "Philips", "summary": "Catéter digital de ultrasonido intravascular (IVUS) diseñado específicamente para el diagnóstico en intervenciones arteriales y venosas periféricas. Proporciona imágenes transversales en tiempo real que permiten evaluar la morfología de la placa, medir con exactitud el lumen verdadero y confirmar la aposición óptima de los stents, minimizando la dependencia del medio de contraste.", "content": "<p>Permite la revisión de lesiones mediante el uso de un cable guía .014”.</p>\n<h3>Beneficios y Características:</h3>\n<ul>\n<li>\n<p><b>Adquisición digital: </b>Plug-and-play.</p>\n</li>\n<li>\n<p><b>ChromaFlo: </b>Visualización a color del flujo de sangre en vivo.</p>\n</li>\n<li>\n<p><b>Catéter guía mínimo 5F.</b></p>\n</li>\n<li>\n<p><b>Diámetro máximo de imagen 20mm.</b></p>\n</li>\n</ul>\n", "image": "assets/visions-pv-014prx.png", "pdfs": [{"url": "https://www.documents.philips.com/assets/20211207/e1d344f61e8d423cb973adf70088aaa3.pdf", "path": "assets/documento-f161d1a50836.pdf", "name": "Ficha Visions PV .014P · inglés", "label": "Ficha Visions PV .014P · inglés"}], "source": "https://academiayumyeong.com/alfacor/product/visions-pv-014-rx/", "quickType": "IVUS periférico digital", "quickSpecs": [["Longitud de trabajo", "150 cm"], ["Frecuencia nominal", "20 MHz"], ["Marcas radiopacas", "3 marcas de 1 mm, separadas 10 mm + marcador del transductor"], ["Guía", "0.014″"], ["Catéter guía", "Mínimo 5 Fr"], ["Campo de imagen", "20 mm"], ["Flujo", "ChromaFlo"]], "officialSource": "https://www.documents.philips.com/assets/Instruction%20for%20Use/20260223/5fbb5777ae8e47c7922ab3fa014cd72e.pdf", "specificationSources": ["https://www.documents.philips.com/assets/Instruction%20for%20Use/20260223/5fbb5777ae8e47c7922ab3fa014cd72e.pdf", "https://www.documents.philips.com/assets/Instruction%20for%20Use/20221012/50625c38f8b047949b99af2c0120d42e.pdf"], "philipsGroup": "peripheral", "imageSource": "https://www.usa.philips.com/healthcare/product/014R/visionspv014prxdigitalivuscatheter", "imageAlt": "Visions PV .014P RX · imagen oficial Philips"}, {"id": 819, "slug": "allegra", "name": "ALLEGRA™", "specialty": "cardio-intervencion", "categories": [{"slug": "estructural", "name": "Estructural"}, {"slug": "protesis-valvular-aortica", "name": "Prótesis Valvular Aórtica (TAVI)"}], "category": "Prótesis Valvular Aórtica (TAVI)", "brand": "Biosensors International", "summary": "ALLEGRA ™ es una válvula aórtica transcatéter diseñada para el tratamiento de la estenosis valvular aórtica severa sintomática, orientada a ofrecer un desempeño hemodinámico consistente y una implantación precisa. Su diseño autoexpandible y su sistema de liberación han sido desarrollados para favorecer el posicionamiento controlado, optimizar el perfil hemodinámico y facilitar futuras intervenciones.", "content": "<p>ALLEGRA™ se encuentra indicada para el tratamiento de la estenosis valvular aórtica severamente calcificada en pacientes con elevado riesgo quirúrgico o con degeneración sintomática de una bioprótesis valvular aórtica. ¨; es decir eliminar la repetición de la palabra pacientes.</p>\n<p>El marco del stent de ALLEGRA™ incorpora una fuerza radial adaptada para favorecer un anclaje y sellado efectivos en el anillo; su diseño proporciona alta fuerza radial en el área de sellado y menor fuerza radial en el tracto de salida del ventrículo izquierdo.</p>\n<p>ALLEGRA™ maximiza el rendimiento hemodinámico en anillos nativos pequeños y en procedimientos de Valve-in-Valve. Con una amplia apertura de la válvula y su posición supra-anular,<br>\nel paciente puede beneficiarse de un alto AOE y bajos gradientes de presión media. El diámetro mínimo del anillo tratable es de 16,5 mm.</p>\n<p>El marco del stent ALLEGRA™ permite flexión en los puntos de fijación comisurales, lo que reduce la tensión en cada ciclo cardíaco, esto se asocia con una mayor durabilidad de la válvula.<br>\nLa ALLEGRA™ está protegida por TissGUARD™, la cual consiste en una tecnología que combina el tratamiento de anti-calcificación del tejido pericárdico bovino con los efectos de reducción de estrés y tensión en las valvas de los puntos de fijación comisural, lo que resulta en una función valvular conservada a largo plazo.</p>\n<p>ALLEGRA™ posee 6 marcadores radiopacos ubicados en la parte superior de la falda de sellado, que contribuyen a una implantación precisa y favorecen el acceso coronario en intervenciones futuras. ALLEGRA™ muestra in vitro un patrón de flujo más fisiológico que otras válvulas, lo que resulta em gradientes de presión más bajos, menor activación plaquetaria, hemólisis y fuga paravalvular mínima, lo que da a lugar a una válvula de mayor duración.</p>\n<p>El nuevo Sistema de Entrega IMPERIA™ para la implantación transfemoral de la Válvula Cardíaca Transcatéter ALLEGRA™ presenta las siguientes caracteristicas:</p>\n<p>• <strong>ALINEACIÓN COMISURAL</strong></p>\n<p>El sistema de entrega IMPERIA ™  junto con ALLEGRA ™ facilita la alineación comisural. El sistema incorpora una marca de ¨mordida¨ como referencia en el ancla de carga para la orientación inicial. ALLEGRA ™ posee 6 marcadores radiopacos y, al alinearse como 3 pares de marcadores en la vista de superposición de cúspides, se logra una alineación comisural precisa.</p>\n<p>• <strong>DESPLIEGUE PREVISIBLE</strong></p>\n<p>El sistema de entrega IMPERIA ™ permite recapturar, reposicionar o recuperar ALLEGRA ™ y realizar un despliegue de hasta el 80% de la válvula; en caso necesario, el sistema permite reposicionamiento o recuperación antes de la liberación definitiva. Esto favorece un despliegue controlado y previsible, minimizando el movimiento de la válvula durante la separación.</p>\n<p> </p>\n", "image": "assets/e687e6a1ff8ba2d4.webp", "pdfs": [{"url": "https://www.biosensors.com/intl/sites/default/files/pdfs/products_technology/Allegra/ifu_allegra_thv_system_with_imperia_rev.00127502_042025_03_ml_view_pro.pdf", "path": "assets/documento-ca5c232adb81.pdf", "name": "IFU ALLEGRA con IMPERIA · multilingüe", "label": "IFU ALLEGRA con IMPERIA · multilingüe"}], "source": "https://academiayumyeong.com/alfacor/product/allegra/", "quickType": "Válvula aórtica transcatéter (TAVI)", "quickSpecs": [["Posición", "Supraanular"], ["Tejido", "Pericardio bovino"], ["Tratamiento", "TissGUARD"], ["Marcadores", "6 radiopacos"], ["Entrega", "Sistema IMPERIA"]], "video": {"id": "HCNWS4s7hus", "title": "TAVR Using Allegra Self Expandable 27 mm Valve", "author": "MedStream360", "description": "Caso clínico de implante de una ALLEGRA de 27 mm. Video externo en inglés; no es un manual de carga ni una guía específica de IMPERIA.", "url": "https://www.youtube.com/watch?v=HCNWS4s7hus"}}, {"id": 816, "slug": "grip-tt", "name": "GRIP TT", "specialty": "cardio-intervencion", "categories": [{"slug": "balones", "name": "Balones"}, {"slug": "coronario", "name": "Coronario"}], "category": "Balones", "brand": "Acrostak", "summary": "Catéter balón de especialidad coronaria diseñado para la preparación segura de lesiones complejas y estenosis inestables. Su innovadora superficie cuenta con nódulos poliméricos integrados que proporcionan un anclaje excepcional durante el inflado (eliminando el efecto de deslizamiento o «semilla de sandía»). Ofrece una resistencia extrema a la presión (hasta 21 atm RBP) y una navegabilidad superior gracias a su diseño libre de componentes metálicos externos.", "content": "<p>El catéter balón de especialidad GRIP TT de Acrostak es una innovación endovascular diseñada para abordar lesiones coronarias donde los balones convencionales fracasan debido a la falta de estabilidad mecánica. Durante el tratamiento de estenosis severamente fibróticas, ricas en lípidos o calcificadas de forma irregular, es común que el balón se deslice hacia los segmentos sanos del vaso durante la presurización (fenómeno conocido como «watermelon seed effect»). El GRIP TT resuelve este desafío clínico crítico asegurando una retención posicional absoluta en el sitio exacto de la lesión.</p>\n<p>El núcleo de su tecnología radica en su superficie exterior, la cual está dotada de filas de nódulos poliméricos («knobs») distribuidos estratégicamente. Estos elementos actúan como puntos de fricción controlada que se anclan a la placa aterosclerótica durante la fase inicial del inflado. Esta arquitectura no solo estabiliza el dispositivo, sino que concentra la fuerza radial en puntos focales, promoviendo micro-fracturas en la placa calcificada para una dilatación altamente efectiva y controlada, preparando el lecho vascular para un implante de stent simétrico.</p>\n<p>A diferencia de los balones de corte o de incisión tradicionales (Cutting/Scoring balloons) que utilizan cuchillas metálicas, el GRIP TT es un dispositivo 100% polimérico en su segmento distal. La ausencia de metal externo reduce drásticamente el perfil de cruce (0.016″) y eleva la capacidad de seguimiento (trackability) a niveles comparables a los balones de pre-dilatación estándar. Además, su robusta matriz de polímero le permite soportar presiones extremas de estallido nominal (RBP de hasta 21 atmósferas), brindando seguridad total al especialista durante intervenciones de alta exigencia.</p>\n<h3>Beneficios y Características:</h3>\n<ul>\n<li>\n<p><b>Anclaje Polimérico (Antideslizamiento):</b> Sus nódulos superficiales fijan el balón a la lesión durante el inflado, erradicando el peligroso efecto de «semilla de sandía» y previniendo la disección de los bordes sanos del vaso.</p>\n</li>\n<li>\n<p><b>Diseño Libre de Metal (Metal-Free):</b> Al prescindir de cuchillas o alambres externos, ofrece una flexibilidad y navegabilidad (trackability) muy superiores a los balones de scoring tradicionales, facilitando el acceso a anatomías distales.</p>\n</li>\n<li>\n<p><b>Resistencia a Presiones Extremas (21 atm RBP):</b> Su historial comprobado de resistencia a la punción y su alta presión de estallido nominal garantizan una dilatación agresiva y segura en placas altamente calcificadas.</p>\n</li>\n<li>\n<p><b>Modificación Focal de Placa:</b> Los nódulos concentran la presión hidrostática en puntos de estrés específicos, fracturando de manera más eficiente y controlada el anillo de calcio en comparación con los balones lisos.</p>\n</li>\n<li>\n<p><b>Intercambio Rápido y Pushability:</b> Su plataforma Rapid Exchange y el diseño de su eje de transmisión proporcionan un excelente soporte y capacidad de empuje, reduciendo los tiempos del procedimiento e incrementando la seguridad del paciente.</p>\n</li>\n</ul>\n", "image": "assets/3f621acbf242130e.webp", "pdfs": [{"url": "https://www.acrostak.com/downloads/acrostak-iu-3-1-rev-j-ifu-grip-grip-tt.pdf", "path": "assets/documento-cb44aff12b80.pdf", "name": "IFU GRIP / GRIP TT · multilingüe", "label": "IFU GRIP / GRIP TT · multilingüe"}], "source": "https://academiayumyeong.com/alfacor/product/grip-tt/", "quickType": "Balón coronario antideslizamiento", "quickSpecs": [["Superficie", "Nódulos poliméricos"], ["Diseño", "Sin cuchillas metálicas"], ["Perfil de cruce", "0.016″"], ["RBP", "Hasta 21 atm; según medida"], ["Sistema", "Intercambio rápido (RX)"]]}, {"id": 813, "slug": "across-cto", "name": "ACROSS CTO", "specialty": "cardio-intervencion", "categories": [{"slug": "balones", "name": "Balones"}, {"slug": "coronario", "name": "Coronario"}], "category": "Balones", "brand": "Acrostak", "summary": "Catéter balón coronario de diseño ultra-perfilado, diseñado específicamente para alcanzar, cruzar y recanalizar Oclusiones Totales Crónicas (CTO). Destaca por presentar uno de los perfiles de entrada más bajos de la industria (0.016″) y una punta cónica extendida de 4 mm, combinando una capacidad de micro-penetración extrema con una resistencia a la presión de hasta 20 atmósferas para fracturar lesiones severamente calcificadas.", "content": "<p>El catéter balón ACROSS CTO de Acrostak representa una solución endovascular de alto rendimiento para el desafío clínico más exigente en la hemodinamia moderna: la Oclusión Total Crónica. En estas intervenciones, el éxito del procedimiento depende críticamente de la capacidad del dispositivo para introducirse en microcanales u oclusiones fibróticas apretadas una vez que la guía coronaria ha logrado atravesar la placa. Este dispositivo ha sido diseñado con una filosofía de «micro-penetración», priorizando un perfil de cruce infinitesimal sin sacrificar la fuerza mecánica.</p>\n<p>El secreto de su extraordinario rendimiento en lesiones oclusivas radica en su arquitectura distal. El balón incorpora una punta cónica ahusada excepcionalmente larga (4 mm) y un perfil de entrada de apenas 0.016″. Esta geometría actúa como una verdadera cuña hidrodinámica, permitiendo al cardiólogo intervencionista forzar el paso a través de cápsulas proximales resistentes y tejido fibrótico, donde los balones de pre-dilatación convencionales suelen fallar o rebotar.</p>\n<p>A pesar de su naturaleza miniaturizada para facilitar el cruce (crossing), el ACROSS CTO es un dispositivo de alta resistencia estructural. Construido con polímeros avanzados que le otorgan una excepcional resistencia a la punción por calcio, el balón es capaz de soportar inflados a altas presiones (Rated Burst Pressure de hasta 20 atmósferas en diámetros seleccionados). Esto garantiza una modificación efectiva de la placa calcificada, incluso en calcificaciones circunferenciales, restaurando el flujo sanguíneo y preparando un lumen adecuado para el implante posterior del stent.</p>\n<h3>Beneficios y Características:</h3>\n<ul>\n<li>\n<p><b>Perfil de Entrada Ultra Bajo (0.016″):</b> Se posiciona entre los balones más finos del mercado mundial, garantizando la inserción inicial en las lesiones estenóticas más apretadas e impenetrables.</p>\n</li>\n<li>\n<p><b>Punta Cónica Extendida (4 mm):</b> Su diseño cónico prolongado facilita una dilatación gradual y atraumática del microcanal de la CTO, maximizando el éxito de cruce intraplaca.</p>\n</li>\n<li>\n<p><b>Alta Resistencia a la Presión (Hasta 20 atm RBP):</b> El material del balón está optimizado para resistir punciones y laceraciones, permitiendo inflados a alta presión para fracturar placas severamente calcificadas.</p>\n</li>\n<li>\n<p><b>Marcador Radiopaco Único (Single Mid Marker):</b> Equipado con un solo marcador central de platino/iridio para minimizar la rigidez del segmento distal, mejorando la flexibilidad y reduciendo aún más el perfil de cruce global.</p>\n</li>\n<li>\n<p><b>Transmisión de Fuerza (Pushability) Superior:</b> Su sistema de intercambio rápido (Rapid Exchange) y el diseño robusto del hipotubo proximal aseguran que toda la fuerza ejercida por el operador se transmita directamente a la punta para franquear la oclusión.</p>\n</li>\n</ul>\n", "image": "assets/3e102ad362fcda38.webp", "pdfs": [{"url": "https://www.acrostak.com/downloads/acrostak-iu-10-1-rev-j-ifu-across-hp-cto-rx-st.pdf", "path": "assets/documento-80a7fbe3960c.pdf", "name": "IFU ACROSS CTO · multilingüe", "label": "IFU ACROSS CTO · multilingüe"}], "source": "https://academiayumyeong.com/alfacor/product/across-cto/", "quickType": "Balón coronario para CTO", "quickSpecs": [["Perfil de entrada", "0.016″"], ["Punta cónica", "4 mm"], ["RBP", "Hasta 20 atm; diámetros seleccionados"], ["Marcador", "Único central"], ["Sistema", "Intercambio rápido (RX)"]]}, {"id": 811, "slug": "rise-sc", "name": "RISE™ SC", "specialty": "cardio-intervencion", "categories": [{"slug": "balones", "name": "Balones"}, {"slug": "coronario", "name": "Coronario"}], "category": "Balones", "brand": "Biosensors International", "summary": "Catéter balón coronario de dilatación semi-compliante (SC) diseñado para la preparación óptima de lesiones antes del implante de stents. Destaca por ofrecer uno de los perfiles de cruce más bajos del mercado y un recubrimiento hidrofílico avanzado, lo que garantiza una navegabilidad superior a través de anatomías tortuosas y una dilatación inicial segura en un amplio rango de diámetros coronarios.", "content": "<p>El catéter balón RISE™ SC de Biosensors International es la herramienta de primera línea para la pre-dilatación en intervenciones coronarias percutáneas (ICP). Antes de desplegar un stent liberador de fármacos, la preparación de la lesión es un paso clínico innegociable. Este balón ha sido diseñado para franquear el primer contacto con estenosis complejas y oclusivas, abriendo un canal inicial (pre-dilatación) que facilita la entrega posterior de dispositivos terapéuticos más voluminosos.</p>\n<p>A nivel de ingeniería, el RISE™ SC incorpora un proceso de unión de punta (tip bonding) completamente rediseñado y un plegado de balón optimizado que reduce significativamente su perfil de entrada. Esta miniaturización estructural, combinada con un revestimiento hidrofílico de alta tecnología aplicado en el eje (shaft), minimiza drásticamente la fricción vascular. Como resultado, el cardiólogo intervencionista obtiene una capacidad de seguimiento (trackability) y empuje excepcional para alcanzar lechos distales en arterias altamente anguladas.</p>\n<p>Además de su agilidad de navegación, el dispositivo ofrece un control presurizado superior gracias a su mayor presión nominal en comparación con las generaciones anteriores. Esto permite una expansión predecible y segura que se adapta a la morfología de la placa. Para cubrir la inmensa variabilidad de la anatomía coronaria, el RISE™ SC cuenta con una de las matrices de tamaños más amplias de la industria (más de 70 referencias), garantizando que el especialista siempre disponga de la medida exacta para cada escenario clínico.</p>\n<h3>Beneficios y Características:</h3>\n<ul>\n<li>\n<p><b>Matriz de Tamaños Extraordinaria:</b> Disponible en más de 70 configuraciones distintas, abarcando desde diámetros ultradelgados de 1.00 mm (ideales para microcanales y vasos distales) hasta 5.00 mm para el tronco coronario principal.</p>\n</li>\n<li>\n<p><b>Perfil de Entrada Minimizado:</b> Su proceso avanzado de plegado y soldadura de la punta distal proporciona un perfil de cruce extremadamente bajo, facilitando el avance a través de oclusiones severas o calcificadas sin generar trauma adicional.</p>\n</li>\n<li>\n<p><b>Trackability Superior (Recubrimiento Hidrofílico):</b> La incorporación de un revestimiento hidrofílico de nueva generación en el eje del catéter anula la resistencia endotelial, permitiendo un deslizamiento fluido y rápido hasta la lesión objetivo.</p>\n</li>\n<li>\n<p><b>Presión Nominal Optimizada:</b> Diseñado para soportar presiones nominales más altas, otorgando al operador la fuerza radial necesaria para modificar eficazmente la placa aterosclerótica durante la fase de preparación.</p>\n</li>\n<li>\n<p><b>Transiciones Flexibles (Pushability):</b> El diseño transicional de su estructura metálica interna evita el acodamiento (kinking) y asegura que la fuerza aplicada desde el puerto proximal se transmita con total integridad hasta la punta del balón.</p>\n</li>\n</ul>\n", "image": "assets/43008cc79acbf48e.webp", "pdfs": [{"url": "https://www.biosensors.com/intl/sites/default/files/12685-000-en_31820_rscbro_main_210x297_r03d2_lr_0.pdf", "path": "assets/documento-4d39dc91e37f.pdf", "name": "Folleto RISE SC · inglés", "label": "Folleto RISE SC · inglés"}], "source": "https://academiayumyeong.com/alfacor/product/rise-sc/", "quickType": "Balón coronario semicomplaciente", "quickSpecs": [["Uso", "Predilatación"], ["Diámetros", "1.00–5.00 mm"], ["Recubrimiento", "Hidrofílico en el eje"], ["Diseño", "Punta de bajo perfil"]]}, {"id": 806, "slug": "rise-nc", "name": "RISE™ NC", "specialty": "cardio-intervencion", "categories": [{"slug": "balones", "name": "Balones"}, {"slug": "coronario", "name": "Coronario"}], "category": "Balones", "brand": "Biosensors International", "summary": "Catéter balón coronario de dilatación no compliante (NC) diseñado para ofrecer un rendimiento superior en las intervenciones coronarias percutáneas (ICP) más desafiantes. Su arquitectura avanzada combina un perfil de cruce ultra bajo con una extrema resistencia a la presión (estallido nominal de 20 atm), garantizando una post-dilatación precisa de stents y la preparación efectiva de lesiones altamente calcificadas sin comprometer la navegabilidad.", "content": "<p>El catéter balón RISE™ NC de Biosensors International representa una evolución técnica indispensable en el arsenal del cardiólogo intervencionista para el manejo de lesiones coronarias complejas. En escenarios clínicos donde la placa fibrótica o severamente calcificada opone máxima resistencia, este dispositivo asegura una expansión circunferencial uniforme y predecible. Su diseño mitiga el crecimiento longitudinal y el indeseado «efecto hueso de perro» (dog-boning) durante el inflado a alta presión, garantizando que la fuerza mecánica se concentre exclusivamente en la zona objetivo para fracturar el calcio sin disecar los bordes del vaso sano.</p>\n<p>La verdadera innovación biomecánica del RISE™ NC radica en su capacidad para resolver la dicotomía histórica de los balones no compliantes: la pérdida de navegabilidad a cambio de resistencia. Biosensors ha superado esta barrera técnica mediante la integración de una punta cónica de perfil ultra bajo y un pliegue de material optimizado. Esta estructura confiere al dispositivo una capacidad de seguimiento (trackability) excepcional, permitiendo al operador cruzar estenosis críticas y navegar por anatomías coronarias intrincadas con la fluidez táctil propia de un balón estándar.</p>\n<p>Adicionalmente, el dispositivo ha sido calibrado milimétricamente para procedimientos de alta demanda anatómica, como la optimización de bifurcaciones coronarias. Su eje de transmisión (shaft) ha sido diseñado para maximizar la fuerza de empuje (pushability), asegurando un posicionamiento radiopaco exacto. Al alcanzar una presión nominal de estallido (RBP) de 20 atmósferas, el RISE™ NC otorga al especialista la confianza absoluta para lograr una aposición perimetral perfecta de los stents liberadores de fármacos (DES), un paso crítico para minimizar las tasas de trombosis temprana y reestenosis intra-stent.</p>\n<h3>Beneficios y Características:</h3>\n<ul>\n<li>\n<p><b>Alta Tolerancia a la Presión (20 atm RBP):</b> Su matriz polimérica estructural soporta presiones de inflado extremas (Rated Burst Pressure de 20 atmósferas) para dilatar lesiones resistentes y asegurar la expansión óptima del stent sin riesgo de ruptura del material.</p>\n</li>\n<li>\n<p><b>Perfil de Cruce (Crossing) Optimizado:</b> La incorporación de una punta distal de volumen ultra reducido facilita la penetración inicial a través de oclusiones fibróticas y el recruce seguro a través de los struts del stent implantado.</p>\n</li>\n<li>\n<p><b>Navegación Superior en Vasos Tortuosos:</b> El perfil hidrodinámico del balón plegado minimiza la fricción endotelial, garantizando un seguimiento ininterrumpido sobre la guía coronaria, incluso en vasos distales severamente angulados.</p>\n</li>\n<li>\n<p><b>Transmisión de Empuje (Pushability) Precisa:</b> Su diseño de hipotubo transicional previene el acodamiento y transfiere la fuerza direccional del operador con precisión 1:1, vital para el posicionamiento exacto en técnicas complejas de bifurcación (como la técnica POT).</p>\n</li>\n<li>\n<p><b>Expansión Predecible (Zero Compliance):</b> Su naturaleza estrictamente no compliante asegura que el diámetro del catéter se mantenga fiel a su medida nominal, protegiendo las zonas adyacentes de la arteria coronaria contra sobreexpansiones accidentales.</p>\n</li>\n</ul>\n", "image": "assets/97e40e6f6cfdc76f.webp", "pdfs": [{"url": "https://biosensors.com/intl/sites/default/files/pdfs/products_technology/Rise/12037-000-en_31800_risbro_main_210x297_r01d8_lra4.pdf", "path": "assets/documento-ad5cf6226146.pdf", "name": "Folleto RISE NC · inglés", "label": "Folleto RISE NC · inglés"}], "source": "https://academiayumyeong.com/alfacor/product/rise-nc/", "quickType": "Balón coronario no complaciente", "quickSpecs": [["Uso", "Dilatación de lesiones resistentes / optimización del stent"], ["RBP", "20 atm, según catálogo"], ["Diseño", "Punta cónica de bajo perfil"], ["Expansión", "No complaciente"]]}, {"id": 723, "slug": "regalia-xs-1-0", "name": "Regalia XS 1.0", "specialty": "vascular-periferico", "categories": [{"slug": "btk", "name": "BTK"}, {"slug": "guias-vascular", "name": "Guías"}, {"slug": "asahi-guides", "name": "Guías Asahi"}], "category": "BTK", "brand": "Asahi Intecc", "summary": "Alambre guía periférico de perfil ultra bajo (0.014″) y extrema flexibilidad, optimizado para intervenciones infrapoplíteas (Bajo la Rodilla / BTK). Con una carga de punta sumamente suave de 1 gramo y una camisa de polímero con recubrimiento hidrofílico avanzado, proporciona una lubricidad y capacidad de seguimiento (trackability) insuperables para el cruce atraumático de la microvasculatura distal.", "content": "<p>La guía periférica ASAHI Regalia XS 1.0 es una herramienta endovascular de alta precisión, desarrollada específicamente para superar las complejidades anatómicas del sector infrapoplíteo (Below The Knee / BTK) en procedimientos de salvamento de extremidades. A diferencia de los alambres de alta fuerza de penetración, esta guía se apoya en una carga distal ultraligera de apenas 1 gramo (1 gf), priorizando una navegación puramente atraumática. Su objetivo clínico es rastrear el lumen verdadero en arterias tibiales y peroneas tortuosas sin el riesgo de generar disecciones accidentales o perforar la delicada pared del vaso.</p>\n<p>La ventaja biomecánica de la Regalia XS 1.0 radica en su arquitectura de superficie. Incorpora una camisa de polímero (Polymer Jacket) combinada con el recubrimiento hidrofílico propietario Slip-Coat, extendiéndose a lo largo de los 22 cm distales. Esta estructura híbrida anula virtualmente la fricción endotelial, permitiendo que la guía resbale de manera continua e ininterrumpida a través de anatomías de pequeño calibre severamente estenóticas.</p>\n<p>A pesar de su excepcional suavidad distal, el núcleo interno de la guía mantiene el control de torsión milimétrico característico de Asahi Intecc. Esto permite al cirujano vascular redirigir el alambre dentro de redes capilares complejas con una respuesta táctil precisa, eliminando el peligroso efecto de latigazo (whip motion). Además, su segmento en espiral de 12 cm incluye una sección radiopaca distal de 3 cm, garantizando un monitoreo fluoroscópico exacto durante toda la intervención.</p>\n<h3>Beneficios y Características:</h3>\n<ul>\n<li>\n<p><b>Carga de Punta Ultra Suave (1 Gramo):</b> Diseñada para un avance atraumático en microvasos frágiles, maximizando la seguridad del procedimiento en lechos distales críticos.</p>\n</li>\n<li>\n<p><b>Lubricidad Extrema (Polymer Jacket):</b> Los 22 cm de cobertura polimérica y recubrimiento Slip-Coat anulan la resistencia, facilitando el deslizamiento por oclusiones largas y difusas sin atascos.</p>\n</li>\n<li>\n<p><b>Capacidad de Seguimiento (Trackability) Superior:</b> Su núcleo transicional absorbe y negocia las curvas cerradas del sector infrapoplíteo, garantizando que los balones y microcatéteres puedan seguir la ruta trazada.</p>\n</li>\n<li>\n<p><b>Visibilidad Radiopaca de 3 cm:</b> Su diseño distal de alta densidad metálica proporciona una visibilidad fluoroscópica nítida, vital para confirmar que la guía ha cruzado completamente la lesión.</p>\n</li>\n<li>\n<p><b>Opciones de Abordaje:</b> Disponible en una plataforma constante de 0.014″ con punta recta, ofreciendo longitudes de trabajo de 180 cm para intervenciones estándar y 300 cm para abordajes contralaterales o retrógrados avanzados.</p>\n</li>\n</ul>\n", "image": "assets/bdfb89524c30535e.webp", "pdfs": [], "source": "https://academiayumyeong.com/alfacor/product/regalia-xs-1-0/", "quickType": "Guía periférica BTK", "quickSpecs": [["Carga de punta", "1 gf"], ["Diámetro", "0.014″"], ["Longitudes", "180 / 300 cm"], ["Recubrimiento", "Polímero + hidrofílico, 22 cm"], ["Radiopacidad", "3 cm"]], "tipLoad": 1, "useCase": "Navegación periférica BTK en vasos pequeños y tortuosos, cuando se busca una punta suave y alta lubricidad.", "officialSource": "https://medical.asahi-intecc.com/latam-es/products-peripheral/regalia-xs-10.html", "asahiGroup": "guides", "guideGroup": "peripheral"}, {"id": 722, "slug": "gladius-0-014", "name": "Gladius 0.014", "specialty": "vascular-periferico", "categories": [{"slug": "btk", "name": "BTK"}, {"slug": "guias-vascular", "name": "Guías"}, {"slug": "asahi-guides", "name": "Guías Asahi"}], "category": "BTK", "brand": "Asahi Intecc", "summary": "La guía ASAHI Gladius 0.014″ en su aplicación BTK es la herramienta endovascular definitiva para el cruce de lesiones difusas y oclusiones largas en el tratamiento del pie diabético y la isquemia crítica. A diferencia de las guías de punta rígida diseñadas para perforar el calcio, la Gladius emplea una estrategia de «deslizamiento y navegación». Su diseño está concebido para rastrear el lumen verdadero o avanzar suavemente a través del espacio subintimal en las delicadas arterias tibiales y peroneas. \n El secreto de su extrema lubricidad en la microvasculatura radica en su camisa de polímero (Polymer Jacket) combinada con un recubrimiento hidrofílico de alto rendimiento de extremo a extremo. Esta superficie anula virtualmente la fricción endotelial, permitiendo que la guía resbale a través del laberinto fibrótico de una Oclusión Total Crónica (CTO) periférica sin quedarse atascada. \n A nivel biomecánico, la innovación más importante de esta guía para el sector BTK es la tecnología de núcleo «Micro Gap». Esta modificación estructural en el extremo distal permite que, al encontrar resistencia, la punta se doble sobre sí misma formando un bucle sumamente estrecho (narrow loop). Esta técnica de avance en bucle, impulsada por la transmisión de torque 1:1 del núcleo trenzado ACT ONE, permite al especialista empujar la guía a través del tejido oclusivo de manera roma, minimizando la expansión del vaso y anulando el riesgo de perforar la pared arterial. \n Beneficios y Características: \n \n \n  Avance Atraumático (Micro Gap):  Su capacidad para formar un micro-bucle en la punta permite cruzar oclusiones largas en el sector tibial empujando de forma roma, protegiendo la integridad de la pared vascular. \n \n \n  Lubricidad Extrema (Polymer Jacket):  El encamisado de polímero y el revestimiento hidrofílico garantizan un seguimiento ininterrumpido a través de vasos severamente enfermos y de diámetro reducido. \n \n \n  Tecnología Trenzada ACT ONE:  El núcleo de acero inoxidable de múltiples hilos previene el acodamiento (kinking) y transfiere el movimiento de torsión de manera inmediata, eliminando el efecto de latigazo. \n \n \n  Perfil BTK de 0.014″:  Su diámetro ultra bajo la hace compatible con todo el arsenal terapéutico de balones y microcatéteres destinados al salvamento de extremidades. \n \n \n  Punta Premoldeada de Fábrica:  Disponible con un mini premoldeado (Mini Pre-shape) que mantiene su curva a pesar de la fricción, evitando que el médico deba manipular y arriesgar el recubrimiento de polímero antes de la inserción.", "content": "<p>Alambre guía periférico recubierto de polímero (0.014″), optimizado clínicamente para la navegación atraumática y el cruce de Oclusiones Totales Crónicas (CTO) en la microvasculatura infrapoplítea (Bajo la Rodilla / BTK). Su exclusiva tecnología «Micro Gap» permite la formación de un bucle estrecho de seguridad, asegurando un avance fluido por lesiones largas sin riesgo de perforación en vasos de pequeño calibre.</p>\n", "image": "assets/a1851017b3d46bcb.webp", "pdfs": [{"url": "https://medical.asahi-intecc.com/sites/default/files/2026-03/Peripheral%2BGuide%2BWire%2BAMK-DT724%2BVer.1.00%20%282%29.pdf", "path": "assets/documento-cbaa5470ddc4.pdf", "name": "IFU guías periféricas Asahi · multilingüe", "label": "IFU guías periféricas Asahi · multilingüe"}], "source": "https://academiayumyeong.com/alfacor/product/gladius-0-014/", "quickType": "Guía periférica BTK para cruce de CTO", "quickSpecs": [["Carga de punta", "3 gf"], ["Diámetro", "0.014″"], ["Recubrimiento", "Polimérico"], ["Núcleo", "ACT ONE"]], "tipLoad": 3, "useCase": "Cruce periférico de estenosis y lesiones ocluidas, con lubricidad y soporte para el avance de dispositivos.", "officialSource": "https://medical.asahi-intecc.com/en/products-peripheral/asahi-gladius-0014.html", "asahiGroup": "guides", "guideGroup": "peripheral"}, {"id": 721, "slug": "halberd-014", "name": "Halberd 014", "specialty": "vascular-periferico", "categories": [{"slug": "btk", "name": "BTK"}, {"slug": "guias-vascular", "name": "Guías"}, {"slug": "asahi-guides", "name": "Guías Asahi"}], "category": "BTK", "brand": "Asahi Intecc", "summary": "Alambre guía periférico de alta penetración (0.014″), optimizado clínicamente para intervenciones de salvamento de extremidades en el sector infrapoplíteo (Bajo la Rodilla / BTK). Con una carga distal de 12 gramos y una punta micro-cónica blindada, proporciona el equilibrio perfecto entre fuerza de empuje y seguridad para cruzar Oclusiones Totales Crónicas (CTO) en arterias tibiales y peroneas.", "content": "<p>La guía ASAHI Halberd 014 en su aplicación BTK es una herramienta endovascular decisiva para el tratamiento de la isquemia crítica de miembros inferiores. Cuando las arterias por debajo de la rodilla presentan oclusiones calcificadas que rechazan a las guías de trabajo estándar, pero el vaso es demasiado frágil para utilizar guías de penetración extrema (como las de 30 o 40 gramos), el Halberd ofrece la respuesta exacta con sus 12 gramos de carga distal.</p>\n<p>La arquitectura distal del Halberd ha sido miniaturizada para la microvasculatura. Incorpora una punta micro-cónica (Micro-cone tip) con una bola de impacto de diámetro reducido, diseñada para encontrar el microcanal de la placa y penetrar sin expandir el espacio subintimal. Además, su diseño de punta «blindada» (Armored tip) cuenta con soldadura continua que impide la deformación del extremo al enfrentar estenosis tibiales severamente fibróticas.</p>\n<p>Impulsada por el núcleo de acero trenzado ACT ONE de Asahi, la guía transfiere la torsión de forma milimétrica (torque 1:1), permitiendo al cirujano vascular redirigir el dispositivo dentro de la oclusión sin riesgo de latigazo (whip motion). El cuerpo cuenta con un revestimiento hidrofílico Slip-Coat para navegar por la intrincada red infrapoplítea, mientras que la micro-bola distal carece de recubrimiento (Uncoated Ball Tip) para proporcionar un anclaje táctil preciso al chocar contra la placa oclusiva.</p>\n<h3>Beneficios y Características:</h3>\n<ul>\n<li>\n<p><b>Fuerza Calibrada para BTK (12 Gramos):</b> Ofrece la rigidez distal exacta para perforar casquetes oclusivos en vasos pequeños, mitigando el riesgo de perforación transmural inherente a las guías más pesadas.</p>\n</li>\n<li>\n<p><b>Punta Micro-Cónica Blindada:</b> Su extremo soldado y afilado mantiene su integridad estructural bajo estrés mecánico, maximizando la capacidad de cruce intraplaca en el sector peroneo y tibial.</p>\n</li>\n<li>\n<p><b>Bola Distal sin Recubrimiento:</b> Asegura que la punta se adhiera al tejido calcificado al impactar, evitando deslizamientos y otorgando una retroalimentación táctil (tactile feedback) insuperable al operador.</p>\n</li>\n<li>\n<p><b>Tecnología de Núcleo ACT ONE:</b> El trenzado de múltiples hilos previene el acodamiento (kinking) y la fatiga del material durante los prolongados tiempos de procedimiento típicos del salvamento de extremidades.</p>\n</li>\n<li>\n<p><b>Perfil Ultra Bajo (0.014″):</b> Completamente compatible con balones de perfil ultra bajo (como el Oceanus 14 o Luminor 14) y microcatéteres de soporte utilizados en las intervenciones más distales del pie.</p>\n</li>\n</ul>\n", "image": "assets/5715ae1cb08bf601.webp", "pdfs": [{"url": "https://medical.asahi-intecc.com/sites/default/files/2026-03/Peripheral%2BGuide%2BWire%2BAMK-DT724%2BVer.1.00%20%282%29.pdf", "path": "assets/documento-cbaa5470ddc4.pdf", "name": "IFU guías periféricas Asahi · multilingüe", "label": "IFU guías periféricas Asahi · multilingüe"}], "source": "https://academiayumyeong.com/alfacor/product/halberd-014/", "quickType": "Guía periférica BTK de penetración", "quickSpecs": [["Carga de punta", "12 gf"], ["Diámetro", "0.014″"], ["Punta", "Microcónica; extremo sin recubrimiento"], ["Núcleo", "ACT ONE"]], "tipLoad": 12, "useCase": "Lesiones periféricas resistentes donde se requiere penetración y control direccional con una guía de 0.014″.", "officialSource": "https://medical.asahi-intecc.com/mea-en/products-peripheral/asahi-halberd-0014.html", "asahiGroup": "guides", "guideGroup": "peripheral"}, {"id": 720, "slug": "astato-40", "name": "Astato 40", "specialty": "vascular-periferico", "categories": [{"slug": "btk", "name": "BTK"}, {"slug": "guias-vascular", "name": "Guías"}, {"slug": "asahi-guides", "name": "Guías Asahi"}], "category": "BTK", "brand": "Asahi Intecc", "summary": "Alambre guía periférico de penetración extrema (0.014″) con una masiva carga de punta de 40 gramos. Diseñado específicamente para el sector infrapoplíteo (BTK), es la herramienta definitiva para perforar Oclusiones Totales Crónicas (CTO) severamente calcificadas, combinando la tecnología de núcleo ACT ONE con una punta cónica de alto poder de ruptura.", "content": "<p>La guía periférica ASAHI Astato 40 representa el máximo nivel de fuerza de penetración en el portafolio de Asahi Intecc para intervenciones de salvamento de extremidades (Limb Salvage). Diseñada sobre una plataforma de perfil ultra bajo de 0.014 pulgadas, este dispositivo está concebido para un único y desafiante propósito clínico: perforar los casquetes oclusivos más densos y calcificados del sector infrapoplíteo (Below The Knee / BTK) que las guías de intervención estándar son incapaces de cruzar.</p>\n<p>Su inigualable capacidad de cruce se deriva de una carga de punta masiva de 40 gramos, una de las más altas disponibles en el mercado para este diámetro. Para focalizar esta fuerza de manera efectiva y segura, incorpora una geometría de punta cónica (Tapered Tip). Este extremo actúa como un cincel endovascular, permitiendo a la guía encontrar microfisuras en la placa aterosclerótica para abrir una vía de acceso intraplaca real sin desviarse hacia el espacio subintimal.</p>\n<p>A nivel estructural, el Astato 40 está impulsado por el núcleo trenzado patentado ACT ONE de Asahi. Esta intrincada malla de acero inoxidable garantiza una transmisión de torsión (torque) 1:1, eliminando la acumulación de tensión y el peligroso efecto de latigazo (whip motion). Mientras que el cuerpo cuenta con el recubrimiento hidrofílico Slip-Coat para anular la fricción endotelial a lo largo del vaso, la micro-bola distal carece intencionalmente de recubrimiento (Uncoated Ball Tip), lo que evita que la punta resbale al impactar perpendicularmente contra el calcio duro y otorga al operador una retroalimentación táctil perfecta.</p>\n<h3>Beneficios y Características:</h3>\n<ul>\n<li>\n<p><b>Carga de Punta Extrema (40 Gramos):</b> Proporciona la máxima rigidez y fuerza mecánica para perforar estenosis críticas y calcificaciones severas que bloquean el flujo hacia el pie.</p>\n</li>\n<li>\n<p><b>Punta Cónica (Tapered Tip):</b> Su extremo distal afilado concentra la fuerza de empuje en un punto focal mínimo, facilitando la ruptura inicial del casquete fibroso.</p>\n</li>\n<li>\n<p><b>Bola Distal sin Recubrimiento (Uncoated Ball Tip):</b> Garantiza un anclaje firme al chocar contra el tejido duro, asegurando una penetración direccional y una transferencia táctil precisa a las manos del cirujano.</p>\n</li>\n<li>\n<p><b>Tecnología Trenzada ACT ONE:</b> Su núcleo reforzado de acero inoxidable ofrece una respuesta de torque excepcional, previniendo el acodamiento y la fatiga del material bajo presión extrema.</p>\n</li>\n<li>\n<p><b>Perfil BTK de 0.014″:</b> A pesar de su masiva rigidez distal, mantiene un diámetro ultra bajo que la hace perfectamente compatible con los microcatéteres y balones utilizados en las delicadas arterias tibiales y peroneas.</p>\n</li>\n</ul>\n", "image": "assets/1f8c064fb75a496d.webp", "pdfs": [{"url": "https://medical.asahi-intecc.com/sites/default/files/2026-03/Peripheral%2BGuide%2BWire%2BAMK-DT724%2BVer.1.00%20%282%29.pdf", "path": "assets/documento-cbaa5470ddc4.pdf", "name": "IFU guías periféricas Asahi · multilingüe", "label": "IFU guías periféricas Asahi · multilingüe"}], "source": "https://academiayumyeong.com/alfacor/product/astato-40/", "quickType": "Guía periférica BTK de alta penetración", "quickSpecs": [["Carga de punta", "40 gf"], ["Diámetro", "0.014″"], ["Punta", "Cónica; extremo sin recubrimiento"], ["Núcleo", "ACT ONE"]], "tipLoad": 40, "useCase": "Oclusiones periféricas resistentes que requieren una guía de alta penetración. Confirmar el modelo exacto en el empaque.", "officialSource": "https://medical.asahi-intecc.com/en/products-peripheral/astato-xs-20-xs-40.html", "asahiGroup": "guides", "guideGroup": "peripheral"}, {"id": 718, "slug": "gaia-pv", "name": "Gaia PV", "specialty": "vascular-periferico", "categories": [{"slug": "atk", "name": "ATK"}, {"slug": "guias-vascular", "name": "Guías"}, {"slug": "asahi-guides", "name": "Guías Asahi"}], "category": "ATK", "brand": "Asahi Intecc", "summary": "Alambre guía periférico de 0.018″ y carga distal de 7.5 gramos, diseñado para el cruce direccional y controlado de Oclusiones Totales Crónicas (CTO).  Su punta micro-cónica facilita la creación de una ruta de entrada en tejido duro y placas fibrosas, mientras que su tecnología de núcleo ACT ONE asegura un control de deflexión y torsión milimétrico.", "content": "<p>La guía periférica ASAHI Gaia PV es una herramienta de alta precisión diseñada para el tratamiento endovascular de Oclusiones Totales Crónicas (CTO) complejas en el sector iliofemoral y poplíteo. Construida sobre una plataforma de 0.018 pulgadas, esta guía se especializa en brindar un control de deflexión direccional absoluto, permitiendo al cirujano vascular «navegar» activamente a través de la anatomía ocluida para mantenerse en el lumen verdadero, en lugar de empujar a ciegas y arriesgar una disección subintimal.</p>\n<p>El diseño mecánico de este dispositivo incorpora una punta micro-cónica (Micro-cone tip) en la cual el diámetro de la bola distal ha sido reducido estratégicamente. Esta miniaturización geométrica concentra la fuerza de penetración en un punto focal mínimo, facilitando la ruptura inicial del casquete fibroso. A pesar de su firme carga de punta de 7.5 gramos, el extremo distal conserva una flexibilidad excepcional que le permite resbalar sobre el calcio extremo y avanzar suavemente por las zonas de menor resistencia de la placa.</p>\n<p>Impulsada por la tecnología de núcleo de acero inoxidable trenzado ACT ONE, la Gaia PV ofrece una transmisión de torque exacta de 1:1, sin efecto de latigazo (whip motion). Para optimizar el seguimiento intravascular, el cuerpo de la guía cuenta con el recubrimiento hidrofílico avanzado Slip-Coat de Asahi, mientras que la micro-bola distal se ha dejado deliberadamente sin recubrimiento (Uncoated Ball Tip) para proporcionar un anclaje táctil perfecto y evitar deslizamientos indeseados al impactar perpendicularmente contra la lesión.</p>\n<h3>Beneficios y Características:</h3>\n<ul>\n<li>\n<p><b>Punta Micro-Cónica (Micro-cone Tip):</b> Su diseño de bola reducida maximiza la eficacia de penetración, creando una ruta de entrada precisa en placas fibróticas y tejidos oclusivos duros.</p>\n</li>\n<li>\n<p><b>Control Activo de Deflexión:</b> Diseñada para responder instantáneamente a la rotación aplicada por el operador, permitiendo redirigir la punta de 7.5 gramos dentro de la lesión para rastrear el microcanal anatómico correcto.</p>\n</li>\n<li>\n<p><b>Tecnología de Núcleo ACT ONE:</b> El trenzado de múltiples hilos garantiza un control de torque inigualable, durabilidad estructural prolongada y resistencia al acodamiento durante procedimientos periféricos extensos.</p>\n</li>\n<li>\n<p><b>Bola Distal sin Recubrimiento (Uncoated Ball Tip):</b> La ausencia de lubricidad en el extremo distal asegura que la guía se adhiera al tejido calcificado al chocar, otorgando la máxima retroalimentación táctil (tactile feedback).</p>\n</li>\n<li>\n<p><b>Curva Premoldeada de Fábrica (1 mm Pre-shape):</b> Disponible con una micro-curva de 1 mm integrada durante el proceso de producción, la cual ofrece una retención de forma significativamente superior a las curvas moldeadas manualmente en el quirófano por el médico.</p>\n</li>\n</ul>\n", "image": "assets/607dc42074b0f2bb.webp", "pdfs": [{"url": "https://medical.asahi-intecc.com/sites/default/files/2026-03/Peripheral%2BGuide%2BWire%2BAMK-DT724%2BVer.1.00%20%282%29.pdf", "path": "assets/documento-cbaa5470ddc4.pdf", "name": "IFU guías periféricas Asahi · multilingüe", "label": "IFU guías periféricas Asahi · multilingüe"}], "source": "https://academiayumyeong.com/alfacor/product/gaia-pv/", "quickType": "Guía periférica direccional", "quickSpecs": [["Carga de punta", "7.5 gf"], ["Diámetro", "0.018″"], ["Punta", "Microcónica, preformada de 1 mm"], ["Núcleo", "ACT ONE"]], "tipLoad": 7.5, "useCase": "Cruce de oclusiones periféricas con control direccional; plataforma de 0.018″ para orientar la punta dentro de la lesión.", "officialSource": "https://medical.asahi-intecc.com/products-peripheral/asahi-gaia-pv.html", "asahiGroup": "guides", "guideGroup": "peripheral"}, {"id": 716, "slug": "halberd", "name": "Halberd", "specialty": "vascular-periferico", "categories": [{"slug": "atk", "name": "ATK"}, {"slug": "guias-vascular", "name": "Guías"}, {"slug": "asahi-guides", "name": "Guías Asahi"}], "category": "ATK", "brand": "Asahi Intecc", "summary": "Alambre guía periférico de alto soporte (0.014″) y carga distal de 12 gramos, diseñado para proporcionar un control de torque preciso y alta penetración en lesiones resistentes y Oclusiones Totales Crónicas (CTO).   Su estructura integra una punta blindada (Armored Tip) y la tecnología de núcleo trenzado ACT ONE, garantizando direccionalidad y resistencia mecánica superior.", "content": "<p>La guía periférica ASAHI Halberd 014 es una herramienta endovascular de penetración avanzada, estructurada específicamente para enfrentar oclusiones calcificadas y estenosis altamente resistentes en los miembros inferiores. Con un perfil de 0.014 pulgadas y una firme carga de punta de 12 gramos, este alambre guía proporciona a los especialistas vasculares el soporte rígido necesario para cruzar placas complejas que los alambres de trabajo estándar no pueden perforar.</p>\n<p>La superioridad biomecánica del Halberd 014 radica en su innovador diseño distal. Incorpora una punta micro-cónica (Micro-cone tip) en la cual el diámetro de la bola de impacto ha sido reducido estratégicamente para maximizar la eficacia de penetración intraplaca. Además, esta sección cuenta con un diseño «blindado» (Armored tip), donde la punta ha sido soldada de forma continua para otorgar una retención de forma inquebrantable y un control direccional absoluto incluso al navegar a través de gruesas capas de calcio.</p>\n<p>El cuerpo de la guía está construido sobre la plataforma patentada ACT ONE de Asahi Intecc. Este núcleo trenzado de múltiples hilos transmite la fuerza de torsión (torque) en una relación exacta de 1:1, eliminando el riesgo de latigazo (whip motion). Para asegurar un avance fluido a través del vaso, el cuerpo cuenta con el recubrimiento hidrofílico avanzado Slip-Coat, mientras que la micro-bola distal se mantiene deliberadamente sin recubrimiento (Uncoated Ball Tip) para proporcionar un agarre táctil perfecto y evitar el deslizamiento al impactar perpendicularmente contra la oclusión.</p>\n<h3>Beneficios y Características:</h3>\n<ul>\n<li>\n<p><b>Carga de Punta de 12 Gramos:</b> Ofrece una alta fuerza de perforación, ideal para el cruce asertivo de oclusiones totales crónicas (CTO) periféricas y lesiones severamente fibróticas.</p>\n</li>\n<li>\n<p><b>Punta Micro-Cónica Blindada (Armored Tip):</b> Su diseño soldado y de perfil reducido asegura una penetración incisiva en el casquete de la placa, manteniendo la integridad de la forma bajo tensión mecánica extrema.</p>\n</li>\n<li>\n<p><b>Tecnología de Núcleo ACT ONE:</b> Su eje trenzado de acero inoxidable proporciona una respuesta de torque excepcional, máxima durabilidad y resistencia al acodamiento (kinking) durante maniobras prolongadas.</p>\n</li>\n<li>\n<p><b>Bola Distal sin Recubrimiento (Uncoated Ball Tip):</b> La micro-bola de la punta carece de lubricidad hidrofílica para lograr anclarse al tejido duro y no resbalar, mejorando drásticamente la retroalimentación táctil a las manos del operador.</p>\n</li>\n<li>\n<p><b>Opciones de Premoldeado (Mini Pre-shape):</b> Se encuentra disponible con una curva de fábrica de 1 mm que facilita la navegación inmediata, evitando que el médico deba moldear manualmente una punta tan rígida y arriesgue la integridad del dispositivo.</p>\n</li>\n</ul>\n", "image": "assets/5715ae1cb08bf601.webp", "pdfs": [{"url": "https://medical.asahi-intecc.com/sites/default/files/2026-03/Peripheral%2BGuide%2BWire%2BAMK-DT724%2BVer.1.00%20%282%29.pdf", "path": "assets/documento-cbaa5470ddc4.pdf", "name": "IFU guías periféricas Asahi · multilingüe", "label": "IFU guías periféricas Asahi · multilingüe"}], "source": "https://academiayumyeong.com/alfacor/product/halberd/", "quickType": "Guía periférica de penetración", "quickSpecs": [["Carga de punta", "12 gf"], ["Variantes", "0.014″ / 0.018″; confirmar referencia"], ["Punta", "Microcónica reforzada"], ["Configuración", "Mini pre-shape de 1 mm"]], "tipLoad": 12, "useCase": "Oclusiones periféricas resistentes, con énfasis en penetración y soporte. Confirmar si la referencia es de 0.014″ o 0.018″.", "officialSource": "https://medical.asahi-intecc.com/en/products-peripheral/asahi-halberd-0018.html", "asahiGroup": "guides", "guideGroup": "peripheral"}, {"id": 715, "slug": "gladius-pv", "name": "Gladius PV", "specialty": "vascular-periferico", "categories": [{"slug": "atk", "name": "ATK"}, {"slug": "guias-vascular", "name": "Guías"}, {"slug": "asahi-guides", "name": "Guías Asahi"}], "category": "ATK", "brand": "Asahi Intecc", "summary": "Alambre guía periférico recubierto de polímero (0.014″), diseñado para el cruce suave y atraumático de oclusiones totales crónicas (CTO) y lesiones largas.  Su tecnología de núcleo distal «Micro Gap» permite la formación de un bucle estrecho de seguridad, mientras que la tecnología ACT ONE asegura una respuesta de torque excepcional.  Disponible en versión de navegación estándar y versión ES (Extra Support) para la entrega de dispositivos pesados.", "content": "<p>La familia de guías periféricas ASAHI Gladius MG 14 PV está concebida para superar los retos biomecánicos de las intervenciones vasculares complejas en extremidades inferiores. Construidas sobre una plataforma de 0.014 pulgadas y con una carga de punta de 3 gramos, estas guías combinan un control direccional milimétrico con una lubricidad extrema, permitiendo navegar por anatomías severamente ocluidas sin comprometer la respuesta táctil del operador.</p>\n<p>La ingeniería detrás de este dispositivo se sustenta en la tecnología patentada ACT ONE de Asahi Intecc, un núcleo trenzado de múltiples hilos que proporciona una transmisión de torque 1:1 sin el efecto de latigazo (whip motion). Además, incorpora una modificación exclusiva en el núcleo distal conocida como «Micro Gap». Esta arquitectura permite que, al chocar contra una lesión resistente, la punta forme un bucle estrecho (narrow loop) controlado. Esto facilita el avance intraplaca minimizando la expansión del espacio subintimal y previniendo disecciones extensas no deseadas.</p>\n<p>Para adaptarse a distintos escenarios anatómicos, la serie se divide en dos modelos. El Gladius MG 14 PV estándar cuenta con 41 cm de recubrimiento hidrofílico sobre camisa de polímero, siendo la herramienta ideal para el seguimiento en oclusiones largas y difusas. Por su parte, el modelo ES (Extra Support) limita el recubrimiento a los 10 cm distales y refuerza el cuerpo proximal, otorgando una plataforma de trabajo mucho más rígida para empujar balones o stents a través de estenosis severamente calcificadas.</p>\n<h3>Beneficios y Características:</h3>\n<ul>\n<li>\n<p><b>Tecnología de Núcleo Distal (Micro Gap):</b> Permite la formación de un bucle estrecho al encontrar resistencia, cruzando la oclusión de manera suave y evitando la expansión indeseada del espacio subintimal.</p>\n</li>\n<li>\n<p><b>Arquitectura ACT ONE:</b> Su núcleo de acero inoxidable de alta tensión mejora drásticamente el control de torque, la durabilidad de la punta y la resistencia al acodamiento durante procedimientos prolongados.</p>\n</li>\n<li>\n<p><b>Lubricidad de Alto Rendimiento:</b> Su camisa de polímero (Polymer Jacket) combinada con el recubrimiento hidrofílico garantiza un deslizamiento ininterrumpido, reduciendo la fricción endotelial.</p>\n</li>\n<li>\n<p><b>Opciones de Soporte (Estándar y ES):</b> El modelo estándar maximiza la navegación distal (41 cm de recubrimiento), mientras que el modelo ES otorga un soporte estructural superior para el avance de dispositivos terapéuticos (10 cm de recubrimiento).</p>\n</li>\n<li>\n<p><b>Mini Premoldeado (Mini Pre-shape):</b> Disponible con una curva de fábrica de aproximadamente 1 mm que resiste la deformación, facilitando el direccionamiento sin que el médico deba moldear manualmente la punta y arriesgar daños en la camisa de polímero.</p>\n</li>\n</ul>\n", "image": "assets/a1851017b3d46bcb.webp", "pdfs": [{"url": "https://medical.asahi-intecc.com/sites/default/files/2026-03/Peripheral%2BGuide%2BWire%2BAMK-DT724%2BVer.1.00%20%282%29.pdf", "path": "assets/documento-cbaa5470ddc4.pdf", "name": "IFU guías periféricas Asahi · multilingüe", "label": "IFU guías periféricas Asahi · multilingüe"}], "source": "https://academiayumyeong.com/alfacor/product/gladius-pv/", "quickType": "Guía periférica con polímero", "quickSpecs": [["Carga de punta", "3 gf"], ["Diámetro", "0.014″"], ["Versiones", "Estándar / ES (extra soporte)"], ["Recubrimiento", "41 cm estándar / 10 cm ES"], ["Tecnología", "Micro Gap + ACT ONE"]], "tipLoad": 3, "useCase": "Cruce de lesiones periféricas largas u ocluidas; la versión ES aporta mayor soporte para entregar dispositivos.", "officialSource": "https://medical.asahi-intecc.com/en/products-peripheral/asahi-gladius-mg14-pv-mg14-pv-es.html", "asahiGroup": "guides", "guideGroup": "peripheral"}, {"id": 713, "slug": "astato-30", "name": "Astato 30", "specialty": "vascular-periferico", "categories": [{"slug": "atk", "name": "ATK"}, {"slug": "guias-vascular", "name": "Guías"}, {"slug": "asahi-guides", "name": "Guías Asahi"}], "category": "ATK", "brand": "Asahi Intecc", "summary": "Alambre guía periférico de alto soporte (0.018″), diseñado específicamente para la revascularización de Oclusiones Totales Crónicas (CTO) y placas severamente calcificadas.  Su extraordinaria fuerza en la punta (30 gramos) y su diseño cónico lo convierten en la herramienta definitiva para penetrar las lesiones más hostiles del sistema iliofemoral y poplíteo.", "content": "<p>La guía ASAHI Astato 30 es el equivalente endovascular a la artillería pesada en el laboratorio de intervenciones periféricas. Mientras que las guías de trabajo estándar (workhorse) ofrecen cargas de punta que varían entre los 3 y 5 gramos, el Astato 30 entrega una fuerza mecánica masiva de 30 gramos. Este nivel de rigidez distal está concebido exclusivamente para un propósito: perforar los casquetes fibróticos y calcificados que bloquean por completo las arterias de los miembros inferiores.</p>\n<p>Para maximizar esta capacidad de penetración sin perder direccionalidad, Asahi Intecc ha diseñado la punta con una geometría cónica (Tapered Tip). Este extremo actúa como una micro-cuña que encuentra y dilata de forma activa los microcanales dentro de la oclusión.</p>\n<p>A nivel de superficie, el dispositivo cuenta con un recubrimiento estratégico. El cuerpo de la guía posee un tratamiento hidrofílico (Slip-Coat) para anular la fricción en la anatomía sana, pero la bola distal se mantiene deliberadamente sin recubrimiento (Uncoated Ball Tip). Esta ausencia de lubricidad en la punta es vital en la práctica clínica: evita que la guía resbale, patine o rebote al impactar perpendicularmente contra el calcio duro, otorgando al cirujano una retroalimentación táctil perfecta.</p>\n<h3>Beneficios y Características:</h3>\n<ul>\n<li>\n<p><b>Fuerza de Penetración Extrema:</b> Su carga de punta (tip load) de 30 gramos ofrece la rigidez necesaria para cruzar casquetes oclusivos que colapsarían o rechazarían a las guías periféricas convencionales.</p>\n</li>\n<li>\n<p><b>Punta Cónica (Tapered Tip):</b> El extremo distal afilado se adapta a las microfisuras de la placa aterosclerótica, facilitando el avance intraplaca a través de la estenosis.</p>\n</li>\n<li>\n<p><b>Bola Distal sin Recubrimiento (Uncoated Ball Tip):</b> Proporciona un agarre antideslizante al chocar contra el calcio y garantiza la máxima transferencia de sensibilidad táctil a las manos del operador.</p>\n</li>\n<li>\n<p><b>Cuerpo Hidrofílico:</b> A pesar de su punta de agarre, los 15 cm distales del cuerpo cuentan con lubricidad avanzada para minimizar la resistencia endotelial durante el seguimiento.</p>\n</li>\n<li>\n<p><b>Transmisión de Torque 1:1:</b> Su núcleo reforzado de acero inoxidable transfiere el movimiento de torsión de forma inmediata. Compatible con sistemas de 0.018″, está disponible en longitudes de 180 cm y 300 cm.</p>\n</li>\n</ul>\n", "image": "assets/1f8c064fb75a496d.webp", "pdfs": [{"url": "https://medical.asahi-intecc.com/sites/default/files/2026-03/Peripheral%2BGuide%2BWire%2BAMK-DT724%2BVer.1.00%20%282%29.pdf", "path": "assets/documento-cbaa5470ddc4.pdf", "name": "IFU guías periféricas Asahi · multilingüe", "label": "IFU guías periféricas Asahi · multilingüe"}], "source": "https://academiayumyeong.com/alfacor/product/astato-30/", "quickType": "Guía periférica de alta penetración", "quickSpecs": [["Carga de punta", "30 gf"], ["Diámetro", "0.018″"], ["Longitudes", "180 / 300 cm"], ["Recubrimiento", "Hidrofílico distal, 15 cm"], ["Punta", "Cónica, extremo sin recubrimiento"]], "tipLoad": 30, "useCase": "Oclusiones periféricas resistentes o calcificadas, cuando se necesita una punta cónica de alta penetración.", "officialSource": "https://medical.asahi-intecc.com/mea-en/products-peripheral/astato-30.html", "asahiGroup": "guides", "guideGroup": "peripheral"}, {"id": 711, "slug": "caravel-150", "name": "Caravel 150", "specialty": "vascular-periferico", "categories": [{"slug": "microcateter-vascular", "name": "Microcatéter"}, {"slug": "asahi-microcatheters", "name": "Microcatéteres Asahi"}], "category": "Microcatéter", "brand": "Asahi Intecc", "summary": "Microcatéter de soporte de perfil ultra bajo (1.9 Fr) con una longitud extendida de 150 cm, diseñado para alcanzar anatomías coronarias distales y abordajes retrógrados complejos. Su estructura, basada en la tecnología de eje trenzado ACT ONE, está concebida exclusivamente para la técnica de empuje continuo (push-only), otorgando máxima flexibilidad y un recubrimiento hidrofílico de 85 cm sin requerir rotación mecánica.", "content": "<p>El microcatéter ASAHI Caravel 150 destaca en el laboratorio de hemodinamia por su diseño de perfil ultra bajo y su alcance maximizado. Esta versión con longitud utilizable de 150 cm es la herramienta de elección cuando el especialista requiere acceder a lesiones extremadamente distales, navegar por canales colaterales en abordajes retrógrados de Oclusiones Totales Crónicas (CTO), o cuando se necesita una longitud extra fuera del paciente para el manejo y maniobra de alambres guía largos.</p>\n<p>A diferencia de otras familias de microcatéteres que basan su eficacia en la penetración rotacional, el Caravel 150 ha sido diseñado estrictamente para técnicas de avance por empuje, por lo que el operador no debe aplicar fuerza de torsión (torque) sobre el dispositivo.</p>\n<p>Su estructura interna está impulsada por la tecnología patentada ACT ONE, un eje trenzado de precisión geométrica que otorga una flexibilidad incomparable en curvas muy cerradas sin comprometer la integridad del lumen interno. Esta resistencia mejorada frente al acodamiento (kinking) asegura un rendimiento fluido al momento de intercambiar guías. Además, su diseño exterior extremadamente delgado permite alojar hasta dos microcatéteres Caravel simultáneamente dentro de un catéter guía de 6Fr, ampliando las opciones terapéuticas en abordajes de bifurcación complejos.</p>\n<h3>Beneficios y Características:</h3>\n<ul>\n<li>\n<p><b>Longitud Extendida (150 cm):</b> Proporciona un alcance superior para llegar a la microvasculatura más distal y facilita las técnicas de abordaje retrógrado donde los catéteres de longitud estándar resultan insuficientes.</p>\n</li>\n<li>\n<p><b>Cobertura Hidrofílica Optimizada:</b> Incorpora 85 cm de recubrimiento hidrofílico de alto rendimiento desde la punta hacia la base, anulando la fricción endotelial durante el largo trayecto anatómico.</p>\n</li>\n<li>\n<p><b>Diseño Exclusivo para Empuje (Push-Only):</b> Optimizado biomecánicamente para rastrear suavemente el vaso sin rotación, reduciendo el estrés sobre el endotelio en redes anatómicas muy anguladas.</p>\n</li>\n<li>\n<p><b>Perfil Ultra Bajo:</b> Su extremo distal suave y cónico se afina hasta los 1.4Fr (0.48 mm), otorgando una capacidad de seguimiento (trackability) superior para cruzar microcanales.</p>\n</li>\n<li>\n<p><b>Tecnología Trenzada ACT ONE:</b> Asegura una transición gradual de la rigidez, manteniendo la resistencia estructural a lo largo del cuerpo de 150 cm y protegiendo el lumen interno contra deformaciones durante el paso de la guía de 0.014″.</p>\n</li>\n</ul>\n", "image": "assets/488e228d5633b431.webp", "pdfs": [], "source": "https://academiayumyeong.com/alfacor/product/caravel-150/", "quickType": "Microcatéter de soporte", "quickSpecs": [["Longitud", "150 cm"], ["Guía", "0.014″"], ["Punta", "1.4 Fr"], ["Recubrimiento", "Hidrofílico, 85 cm"], ["Avance", "Por empuje; no rotacional"]], "asahiGroup": "microcatheters"}, {"id": 710, "slug": "corsair-armet", "name": "Corsair Armet", "specialty": "vascular-periferico", "categories": [{"slug": "microcateter-vascular", "name": "Microcatéter"}, {"slug": "asahi-microcatheters", "name": "Microcatéteres Asahi"}], "category": "Microcatéter", "brand": "Asahi Intecc", "summary": "Microcatéter de soporte periférico de alto rendimiento, diseñado con capacidad de torsión mecánica para el cruce de oclusiones totales crónicas (CTO) y lesiones severamente calcificadas.   Su exclusiva estructura combina un eje trenzado Super SHINKA-Shaft con una punta metálica de bajo perfil que resiste el aplastamiento, garantizando una fuerza de penetración excepcional en el sector iliofemoral e infrapoplíteo.", "content": "<p>El microcatéter ASAHI Corsair Armet representa una evolución crítica en el arsenal terapéutico para intervenciones vasculares periféricas de alta complejidad. Los especialistas en salvamento de extremidades a menudo se enfrentan a placas de calcio mucho más extensas y duras que las coronarias. Para superar este desafío, Asahi Intecc ha reforzado la legendaria plataforma Corsair, creando un dispositivo capaz de soportar fuerzas mecánicas extremas sin comprometer la integridad del lumen interno.</p>\n<p>La principal innovación de este dispositivo radica en su extremo distal. A diferencia de los microcatéteres convencionales con puntas de polímero blando que suelen achatarse o colapsar al impactar contra el calcio duro, el Corsair Armet incorpora una punta metálica. Esta estructura blindada mantiene su bajo perfil de entrada inalterable, actuando como una cuña indeformable que facilita la penetración inicial en el casquete de la oclusión.</p>\n<p>La fuerza propulsora detrás de esta punta es la tecnología Super SHINKA-Shaft, un eje compuesto por una intrincada malla de múltiples hilos metálicos. Esta arquitectura permite al cirujano vascular aplicar torque directo y avanzar el catéter mediante rotación activa (atornillado) a través de la lesión. Al mismo tiempo, proporciona un soporte estructural masivo para el intercambio seguro de alambres guía de 0.014″ en anatomías hostiles.</p>\n<h3>Beneficios y Características:</h3>\n<ul>\n<li>\n<p><b>Punta Metálica Indeformable:</b> Su extremo distal metálico impide el aplastamiento (crushing) al chocar contra calcificaciones severas, conservando un perfil afilado que maximiza la capacidad de cruce.</p>\n</li>\n<li>\n<p><b>Tecnología Super SHINKA-Shaft:</b> Un eje reforzado que proporciona una fuerza de empuje (pushability) superior y una resistencia inigualable contra la compresión y el acodamiento (kinking) en anatomías anguladas.</p>\n</li>\n<li>\n<p><b>Avance Rotacional Activo:</b> El diseño del trenzado permite al especialista rotar mecánicamente el catéter para perforar el tejido fibrótico, con un límite seguro de hasta 10 rotaciones continuas por dirección.</p>\n</li>\n<li>\n<p><b>Soporte de Guía Inquebrantable:</b> Actúa como un riel rígido de alta estabilidad, previniendo el prolapso del alambre guía cuando se intenta cruzar lesiones que ofrecen una alta resistencia al empuje.</p>\n</li>\n<li>\n<p><b>Recubrimiento de Alta Navegabilidad:</b> Su superficie exterior cuenta con un tratamiento hidrofílico que reduce drásticamente la fricción contra la pared vascular, mientras que la banda radiopaca distal garantiza un seguimiento fluoroscópico exacto.</p>\n</li>\n</ul>\n", "image": "assets/79a334272dce535f.webp", "pdfs": [], "source": "https://academiayumyeong.com/alfacor/product/corsair-armet/", "quickType": "Microcatéter de cruce y soporte", "quickSpecs": [["Guía", "0.014″"], ["Punta", "Metálica"], ["Eje", "Super SHINKA-Shaft"], ["Diseño", "Rotacional"]], "asahiGroup": "microcatheters"}, {"id": 708, "slug": "prestige", "name": "Prestige", "specialty": "vascular-periferico", "categories": [{"slug": "coils-vascular-periferico", "name": "Coils"}], "category": "Coils", "brand": "Balt", "summary": "Sistema avanzado de coils de embolización periférica de desprendimiento controlado, diseñado para la oclusión rápida y precisa de anomalías arteriales y venosas.   Destaca por su mecanismo de liberación instantánea (menos de 1 segundo) y su núcleo empujador (pusher) con hipotubo de corte en espiral que maximiza la navegabilidad y la fuerza de empuje.", "content": "<p>El sistema de coils Prestige Plus de Balt es una solución endovascular de máxima precisión para procedimientos de embolización en la vasculatura periférica. Su principal objetivo clínico es obstruir de manera controlada y permanente el flujo sanguíneo en vasos patológicos, siendo una herramienta vital en el tratamiento de aneurismas periféricos, fístulas, malformaciones arteriovenosas (MAV) o hemorragias activas.</p>\n<p>La principal ventaja tecnológica de esta familia de coils es su sistema de liberación. A diferencia de los sistemas de desprendimiento térmico o mecánico que requieren varios segundos para actuar, el Prestige Plus se separa del catéter de empuje en menos de un segundo utilizando el controlador de desprendimiento Ultra (Ultra Detachment Controller). Esta inmediatez otorga al radiólogo intervencionista una seguridad geométrica absoluta, minimizando el tiempo de exposición y evitando que el coil se desplace accidentalmente de la zona objetivo durante la implantación.</p>\n<p>A nivel biomecánico, el catéter de empuje (pusher) está fabricado con un hipotubo de corte en espiral que transita hacia una bobina distal progresivamente más suave. Esta transición de rigidez (flexibility transition) asegura una excelente transmisión de fuerza (pushability) a través del microcatéter, garantizando que el coil alcance lechos distales tortuosos de manera suave y sin atascos.</p>\n<h3>Beneficios y Características:</h3>\n<ul>\n<li>\n<p><b>Desprendimiento Instantáneo (&lt; 1 segundo):</b> Su mecanismo de liberación de alta fiabilidad garantiza una separación inmediata y estable, evitando la tensión mecánica o el micro-movimiento del coil dentro del aneurisma.</p>\n</li>\n<li>\n<p><b>Configuraciones Complejas y Helicoidales:</b> Disponible en una gama completa de geometrías (Complex y Helical) para adaptarse a diferentes escenarios clínicos. Permite tanto el enmarcado inicial de la pared (framing) como el empaquetado denso del núcleo (filling).</p>\n</li>\n<li>\n<p><b>Hipotubo de Corte en Espiral:</b> El diseño avanzado de su sistema de entrega proporciona una navegabilidad (trackability) superior, evitando el acodamiento durante el avance por microcatéteres en anatomías complejas.</p>\n</li>\n<li>\n<p><b>Empujador Distal Visible:</b> Incorpora marcadores radiopacos estratégicamente ubicados que permiten al operador confirmar visualmente bajo fluoroscopia que la zona de desprendimiento ha salido completamente del microcatéter antes de la liberación.</p>\n</li>\n<li>\n<p><b>Compatibilidad Condicional para RM:</b> Toda la familia de coils Prestige Plus es compatible con resonancia magnética (MR Conditional), garantizando la seguridad del paciente en escaneos posteriores de 1.5 y 3 Teslas.</p>\n</li>\n</ul>\n", "image": "assets/611f4c810aaf4457.webp", "pdfs": [{"url": "https://academiayumyeong.com/alfacor/wp-content/uploads/2026/03/ET-Prestige-Plus-linea-27.pdf", "path": "assets/3657c490d84c9f68.pdf", "name": "ET-Prestige-Plus-linea-27.pdf"}], "source": "https://academiayumyeong.com/alfacor/product/prestige/", "quickType": "Coils de embolización periférica", "quickSpecs": [["Configuraciones", "Complejas / helicoidales"], ["Liberación", "Desprendimiento mecánico rápido"], ["Empujador", "Distal radiopaco"], ["Diseño", "Hipotubo con corte en espiral"]]}, {"id": 706, "slug": "angiolite-btk", "name": "Angiolite BTK", "specialty": "vascular-periferico", "categories": [{"slug": "stent-con-droga", "name": "Stent con Droga"}], "category": "Stent con Droga", "brand": "iVascular", "summary": "Stent periférico liberador de sirolimus (DES) concebido específicamente para el tratamiento de lesiones estenóticas críticas en el sector infrapoplíteo (Bajo la Rodilla / BTK). Su diseño combina una alta fuerza radial con la tecnología de recubrimiento TransferWise y un polímero de fluoroacrilato, garantizando una endotelización temprana y reduciendo drásticamente las tasas de reestenosis.", "content": "<p>El sistema Angiolite BTK de iVascular es un stent liberador de sirolimus diseñado para el tratamiento de la enfermedad arterial por debajo de la rodilla (BTK). Desarrollado para afrontar los desafíos de vasos de pequeño calibre, ofrece soporte mecánico y liberación controlada del fármaco para contribuir a reducir la reestenosis y mantener la permeabilidad del vaso a largo plazo.</p>\n<p>Su plataforma de nitinol proporciona alta fuerza radial y un retroceso elástico (recoil) prácticamente nulo, adaptándose al contorno del vaso y ofreciendo un soporte confiable incluso en arterias sometidas a movimientos constantes.</p>\n<p>La tecnología patentada TransferWise® permite una liberación uniforme y controlada de sirolimus hacia la pared arterial, favoreciendo una respuesta vascular saludable y resultados duraderos.</p>\n<h3>Beneficios y Características:</h3>\n<ul>\n<li><strong>Liberación Controlada de Sirolimus (TransferWise®):</strong> Tecnología patentada que permite una liberación uniforme y controlada del sirolimus hacia la pared arterial, contribuyendo a reducir la reestenosis y favorecer la permeabilidad del vaso a largo plazo.</li>\n<li><strong>Plataforma de Nitinol:</strong> Diseñada para ofrecer alta fuerza radial, excelente conformabilidad y resistencia a las exigencias mecánicas de las arterias por debajo de la rodilla.</li>\n<li><strong>Diseño Optimizado del Stent:</strong> Su arquitectura de celdas proporciona una adaptación uniforme a la anatomía vascular y un soporte confiable de la pared arterial.</li>\n<li><strong>Sistema de Entrega de Bajo Perfil:</strong> Facilita la navegación en anatomías complejas y el acceso a lesiones distales, permitiendo un despliegue preciso y controlado del stent.</li>\n<li><strong>Diseñado para Lesiones BTK:</strong> Desarrollado específicamente para el tratamiento de arterias infrapoplíteas, donde se requiere un equilibrio entre flexibilidad, soporte y precisión en la liberación del fármaco Se</li>\n<li></li>\n</ul>\n", "image": "assets/3a3a77ff63d195d6.webp", "pdfs": [], "source": "https://academiayumyeong.com/alfacor/product/angiolite-btk/", "quickType": "Stent liberador de fármaco para BTK", "quickSpecs": [["Fármaco", "Sirolimus"], ["Tecnología", "TransferWise"], ["Territorio", "Infrapoplíteo"], ["Entrega", "Sistema de bajo perfil"]]}, {"id": 704, "slug": "restorer", "name": "Restorer", "specialty": "vascular-periferico", "categories": [{"slug": "stent-sin-droga", "name": "Stent sin Droga"}], "category": "Stent sin Droga", "brand": "iVascular", "summary": "Stent periférico expandible con balón (BES) fabricado en aleación de Cromo-Cobalto (CoCr L605). Diseñado para el tratamiento de estenosis severas en el sector iliofemoral, destaca por ofrecer una fuerza radial excepcional con una mínima cantidad de metal y un perfil de cruce ultra bajo, siendo compatible con introductores de 6Fr en todos sus diámetros.", "content": "<p>El sistema de stent periférico Restorer de iVascular es un stent expandible con balón (BES), diseñado para el tratamiento de lesiones en el sector iliofemoral. Su plataforma de cromo-cobalto (CoCr L605) incorpora una arquitectura de celda abierta que combina alta fuerza radial con una baja carga metálica, proporcionando un soporte vascular preciso sin comprometer la flexibilidad. A diferencia de los stents autoexpandibles, permite un control preciso del diámetro de expansión durante el procedimiento, facilitando una implantación adaptada a las necesidades de cada lesión. Premontado sobre la plataforma Oceanus 35 y compatible con introductores de 6 Fr en todos sus diámetros, ofrece una excelente navegabilidad y un despliegue preciso incluso en anatomías complejas.</p>\n<h3>Beneficios y Características:</h3>\n<ul>\n<li>\n<p><b>Fuerza Radial Extraordinaria:</b> Su aleación de Cromo-Cobalto L605 proporciona un soporte arterial insuperable frente al retroceso elástico de las placas calcificadas, utilizando menos metal para preservar la integridad biomecánica del vaso.</p>\n</li>\n<li>\n<p><b>Diseño de Strut Avanzado:</b> La estructura de enlaces helicoidales y picos anidados garantiza una adaptabilidad (conformability) perfecta a la anatomía vascular, evitando la rectificación rígida y antinatural de la arteria.</p>\n</li>\n<li>\n<p><b>Plataforma de Entrega Oceanus 35:</b> El catéter balón integrado de alto rendimiento asegura una navegabilidad fluida, alta capacidad de empuje y un desinflado casi inmediato, agilizando el retiro del dispositivo tras la implantación.</p>\n</li>\n<li>\n<p><strong>Baja Carga Metálica:</strong> Su diseño optimizado reduce la cantidad de metal implantado sin comprometer la fuerza radial, favoreciendo la flexibilidad y la adaptación del stent a la anatomía vascular.</p>\n</li>\n<li>\n<p><b>Perfil de Cruce Bajo (6Fr):</b> Gracias a su óptimo proceso de ensamblaje y plegado, toda la gama de diámetros del stent Restorer es completamente compatible con vainas introductoras de 6Fr, minimizando el trauma en el sitio de acceso arterial.</p>\n</li>\n</ul>\n", "image": "assets/6fee7ee02f3b98f3.webp", "pdfs": [], "source": "https://academiayumyeong.com/alfacor/product/restorer/", "quickType": "Stent periférico expandible con balón", "quickSpecs": [["Material", "Cromo-cobalto L605"], ["Diseño", "Celda abierta"], ["Introductor", "6 Fr, según catálogo"], ["Entrega", "Balón Oceanus 35"]]}, {"id": 701, "slug": "ivolution-pro", "name": "iVolution PRO", "specialty": "vascular-periferico", "categories": [{"slug": "stent-autoexpandible", "name": "Stent Autoexpandible"}], "category": "Stent Autoexpandible", "brand": "iVascular", "summary": "Stent periférico autoexpandible de Nitinol, diseñado para la revascularización de arterias ilíacas y femoropoplíteas. Destaca por su alta fuerza radial, flexibilidad y un sistema de liberación de bajo perfil (6Fr) con recubrimiento hidrofílico, garantizando un despliegue preciso y seguro en anatomías altamente tortuosas.", "content": "<p>El stent autoexpandible iVolution PRO de iVascular es una solución endovascular diseñada para el tratamiento de lesiones estenóticas u oclusivas en el territorio periférico, especialmente en las arterias ilíacas y femoropoplíteas. Su plataforma de nitinol está diseñada para proporcionar alta fuerza radial, excelente flexibilidad y una óptima adaptación a la anatomía vascular, incluso en vasos sometidos a movimientos y compresiones constantes.</p>\n<p>Su arquitectura de celda abierta (Open Cell Design) permite una adaptación uniforme al contorno del vaso, manteniendo una fuerza radial sostenida para favorecer la permeabilidad a largo plazo. Además, incorpora marcadores radiopacos de tántalo en ambos extremos, proporcionando una excelente visibilidad bajo fluoroscopia para un posicionamiento preciso durante el despliegue.</p>\n<p>El sistema de liberación está diseñado para ofrecer un control preciso durante el procedimiento. Compatible con guías de 0.035″ y con un perfil de cruce de 6 Fr, incorpora el recubrimiento hidrofílico HYDRAX® y un diseño anti-salto (Anti-Jumping), facilitando la navegación en anatomías complejas y un despliegue suave y controlado.</p>\n<h3>Beneficios y Características:</h3>\n<ul>\n<li>\n<p><b>Arquitectura de Nitinol (Celda Abierta):</b> Proporciona un equilibrio óptimo entre alta fuerza radial para resistir la compresión externa y una flexibilidad superior para adaptarse a los movimientos articulares continuos.</p>\n</li>\n<li>\n<p><b>Marcadores de Tántalo:</b> Integra 4 marcadores radiopacos en cada extremo del stent, garantizando una visualización nítida para un despliegue preciso y sin errores de posicionamiento.</p>\n</li>\n<li>\n<p><b>Sistema Anti-Salto (Anti-Jumping):</b> El mecanismo de liberación está diseñado para evitar la elongación o el acortamiento brusco del stent durante el despliegue, asegurando que aterrice exactamente en el sitio planificado.</p>\n</li>\n<li>\n<p><b>Perfil de Cruce Bajo y Recubrimiento HYDRAX:</b> Su sistema de entrega de 6Fr incorpora un recubrimiento hidrofílico avanzado en el extremo distal, reduciendo drásticamente la fricción durante la navegación anatómica.</p>\n</li>\n<li>\n<p><b>Amplia Cobertura Lesional:</b> Disponible en una extensa gama de diámetros (5 mm a 10 mm) y longitudes (hasta 200 mm), permitiendo tratar desde estenosis focales cortas hasta oclusiones femorales largas con un solo dispositivo.</p>\n</li>\n</ul>\n", "image": "assets/48b3651a1b5a2a8b.webp", "pdfs": [], "source": "https://academiayumyeong.com/alfacor/product/ivolution-pro/", "quickType": "Stent periférico autoexpandible", "quickSpecs": [["Material", "Nitinol, celda abierta"], ["Guía", "0.035″"], ["Sistema de entrega", "6 Fr"], ["Diámetros", "5–10 mm"], ["Longitudes", "Hasta 200 mm"]]}, {"id": 700, "slug": "luminor-35", "name": "Luminor 35", "specialty": "vascular-periferico", "categories": [{"slug": "balon-con-droga", "name": "Balón con Droga"}], "category": "Balón con Droga", "brand": "iVascular", "summary": "Catéter balón recubierto de fármaco (DCB) de máximo soporte, estructurado para guías de intervención de gran calibre (0.035″). Diseñado para la dilatación eficaz de estenosis severas en arterias ilíacas, renales, femorales proximales y fístulas AV, liberando paclitaxel de forma precisa para evitar la proliferación celular.", "content": "<p>El catéter de dilatación Luminor 35 es la solución definitiva de iVascular para las intervenciones vasculares de mayor calibre y alta carga obstructiva. Este balón liberador de paclitaxel, diseñado bajo una arquitectura OTW para alambres guía estándar de 0.035″, proporciona la estabilidad mecánica extrema requerida para dilatar y tratar arterias proximales rígidas, incluyendo el sector ilíaco, vasos femorales anchos y el rescate de fístulas arteriovenosas (AV) disfuncionales.</p>\n<p>Para tratar estas lesiones restrictivas de gran diámetro, el Luminor 35 aplica una potente fuerza de dilatación radial simultáneamente a la entrega de una dosis terapéutica exacta de paclitaxel (3 µg/mm²). La tecnología TransferTech asegura que, en el punto de máximo estrés mecánico contra la placa, la estructura microcristalina del fármaco penetre profundamente en la íntima arterial. Además, gracias a su diseño interno optimizado, garantiza tiempos de desinflado ultrarrápidos a pesar de movilizar grandes volúmenes de contraste.</p>\n<h3>Beneficios y Características:</h3>\n<ul>\n<li>\n<p><b>Fuerza de Empuje Extrema (Pushability):</b> Su núcleo robusto, adaptado para guías de 0.035″, transfiere la energía cinética directamente a la lesión, facilitando el cruce de oclusiones calcificadas sin deformar el catéter.</p>\n</li>\n<li>\n<p><strong>Eficacia Antireestenosis:</strong> La potente presión ejercida, combinada con el paclitaxel microcristalino, inactiva la hiperplasia intimal en vasos gruesos, prolongando la permeabilidad primaria de manera sustancial.</p>\n</li>\n<li>\n<p><b>Evacuación y Desinflado Rápido:</b> Su diseño interno de lumen dual ampliado permite que el balón recupere su perfil original rápidamente tras el inflado, garantizando una retracción segura a través del introductor.</p>\n</li>\n<li>\n<p><b>Tecnología Multicapa Altamente Resistente:</b> A pesar de la elevada fricción que presentan las arterias iliofemorales, el recubrimiento nanotecnológico soporta el estrés de la inserción intacto, evitando pérdidas prematuras de dosis.</p>\n</li>\n</ul>\n", "image": "assets/8a8d83aa089027db.webp", "pdfs": [], "source": "https://academiayumyeong.com/alfacor/product/luminor-35/", "quickType": "Balón periférico liberador de fármaco", "quickSpecs": [["Guía", "0.035″"], ["Sistema", "OTW"], ["Fármaco", "Paclitaxel"], ["Dosis de recubrimiento", "3 µg/mm²"]]}, {"id": 699, "slug": "luminor-18", "name": "Luminor 18", "specialty": "vascular-periferico", "categories": [{"slug": "balon-con-droga", "name": "Balón con Droga"}], "category": "Balón con Droga", "brand": "iVascular", "summary": "Catéter balón recubierto de paclitaxel (DCB) versátil y de alto rendimiento, optimizado para alambres guía de 0.018″. Combina un perfil de cruce excepcionalmente bajo, compatible con introductores de 4Fr, con la avanzada tecnología de transferencia de fármaco TransferTech para el tratamiento definitivo de lesiones femoropoplíteas.", "content": "<p>El Luminor 18 es el catéter balón liberador de fármaco más versátil de la cartera de iVascular, diseñado para abordar un amplio espectro de oclusiones periféricas desde el sector femoral hasta el infrapoplíteo. Al estar estructurado para guías de 0.018″, ofrece un equilibrio mecánico excepcional: proporciona el soporte estructural necesario para cruzar lesiones resistentes, al tiempo que mantiene la flexibilidad indispensable para navegar por redes arteriales complejas.</p>\n<p>Su verdadero valor clínico reside en la combinación de esta sólida plataforma mecánica con el recubrimiento de paclitaxel TransferTech. La tecnología de secado especializado (Dry-off) genera microcristales que se adhieren de forma segura a las paredes del balón, evitando el agrietamiento del recubrimiento. Además, el Luminor 18 destaca en el mercado por su perfil extraordinariamente bajo, permitiendo a los especialistas realizar angioplastias terapéuticas avanzadas a través de accesos menos invasivos.</p>\n<h3>Beneficios y Características:</h3>\n<ul>\n<li>\n<p><b>Compatibilidad con Introductores de 4Fr:</b> Su diseño aerodinámico y plegado hermético ofrecen uno de los perfiles más bajos del mercado DCB, reduciendo drásticamente las complicaciones en el sitio de acceso.</p>\n</li>\n<li>\n<p><b>Transferencia Farmacológica Uniforme:</b> La tecnología de recubrimiento multicapa guiada por ultrasonido asegura que el paclitaxel se distribuya homogéneamente, logrando un impacto terapéutico consistente en toda la pared arterial.</p>\n</li>\n<li>\n<p><b>Equilibrio Óptimo de Soporte:</b> El eje OTW proporciona la fuerza de empuje (pushability) exacta para atravesar oclusiones sin riesgo de acodamiento de la guía de 0.018″.</p>\n</li>\n<li>\n<p><b>Recubrimiento de Alta Estabilidad:</b> Su excipiente matriz lipofílico y biocompatible sujeta el fármaco firmemente hasta llegar a la lesión, evitando el desprendimiento prematuro de partículas en el torrente sanguíneo.</p>\n</li>\n<li>\n<p><b>Amplio Espectro Anatómico:</b> Disponible en un vasto rango de diámetros (2 mm a 8 mm) y longitudes extendidas (hasta 200 mm), cubriendo desde estenosis focales hasta oclusiones difusas extremadamente largas.</p>\n</li>\n</ul>\n", "image": "assets/8a8d83aa089027db.webp", "pdfs": [], "source": "https://academiayumyeong.com/alfacor/product/luminor-18/", "quickType": "Balón periférico liberador de fármaco", "quickSpecs": [["Guía", "0.018″"], ["Sistema", "OTW"], ["Diámetros", "2–8 mm"], ["Longitudes", "Hasta 200 mm"]]}, {"id": 697, "slug": "luminor-14", "name": "Luminor 14", "specialty": "vascular-periferico", "categories": [{"slug": "balon-con-droga", "name": "Balón con Droga"}], "category": "Balón con Droga", "brand": "iVascular", "summary": "Catéter balón liberador de fármaco (DCB) de perfil ultra bajo, diseñado para la revascularización de lesiones distales severas. Compatible con guía de 0.014″, libera paclitaxel (3 µg/mm²) mediante nanotecnología TransferTech para inhibir la reestenosis a largo plazo en la microvasculatura infrapoplítea (Bajo la Rodilla / BTK).", "content": "<p>Luminor 14 es un balón liberador de fármaco (DCB) con recubrimiento de paclitaxel, diseñado para el tratamiento endovascular de lesiones en arterias periféricas de pequeño calibre. Compatible con guías de 0.014”, su plataforma OTW (Over-The-Wire) facilita el acceso y tratamiento de lesiones complejas en territorios femorales, poplíteos e infrapoplíteos.</p>\n<p>Su exclusiva tecnología TransferTech® utiliza un proceso de recubrimiento multicapa que favorece una transferencia eficiente y homogénea del paclitaxel a la pared arterial, minimizando la pérdida de fármaco durante la navegación. Esta combinación de tecnología y diseño contribuye a reducir la reestenosis y mantener la permeabilidad vascular a largo plazo.</p>\n<h3>Beneficios y Características:</h3>\n<ul>\n<li>\n<p><b>Recubrimiento Nanotecnológico TransferTech:</b> Minimiza la pérdida de fármaco durante la inserción y asegura una transferencia microcristalina óptima del paclitaxel (3 µg/mm²) a la lesión.</p>\n</li>\n<li>\n<p><b>Perfil de Cruce Ultra Bajo:</b> Diseñado para las lesiones más restrictivas, cuenta con perfiles distales afilados que permiten una penetración excepcional en anatomías ultra distales.</p>\n</li>\n<li>\n<p><b>Navegabilidad (Trackability) Superior:</b> Su eje flexible y su revestimiento hidrofílico aseguran que el balón pueda sortear vasos tortuosos y calcificados sin comprometer la matriz del fármaco.</p>\n</li>\n<li>\n<p><b>Tiempos de Desinflado Rápidos:</b> Acelera la recuperación del flujo sanguíneo y minimiza el tiempo de isquemia tisular durante el procedimiento, facilitando un retiro expedito del catéter.</p>\n</li>\n<li>\n<p><b>Eficacia Clínica Comprobada:</b> Respaldado por múltiples ensayos clínicos internacionales, ha demostrado altas tasas de permeabilidad primaria y una reducción drástica en la Revascularización de la Lesión Diana (TLR).</p>\n</li>\n</ul>\n", "image": "assets/8a8d83aa089027db.webp", "pdfs": [], "source": "https://academiayumyeong.com/alfacor/product/luminor-14/", "quickType": "Balón periférico liberador de fármaco", "quickSpecs": [["Guía", "0.014″"], ["Sistema", "OTW"], ["Fármaco", "Paclitaxel, 3 µg/mm²"], ["Recubrimiento", "TransferTech"]]}, {"id": 696, "slug": "oceanus-35", "name": "Oceanus 35", "specialty": "vascular-periferico", "categories": [{"slug": "balon-semicomplaciente", "name": "Balón Semicomplaciente"}], "category": "Balón Semicomplaciente", "brand": "iVascular", "summary": "El  Oceanus 35  es un catéter balón PTA de intercambio sobre guía (OTW), compatible con guías de  0.035″ , diseñado para el tratamiento de lesiones en arterias de gran calibre. Su diseño de doble lumen proporciona un excelente soporte y capacidad de empuje, mientras que su rápida deflación y perfil optimizado favorecen una navegación eficiente y un manejo preciso durante procedimientos en arterias ilíacas y femorales.", "content": "<p>El <strong>Oceanus 35</strong> es un catéter balón PTA de intercambio sobre guía (OTW), compatible con guías de <strong>0.035″</strong>, desarrollado para procedimientos de angioplastia periférica en arterias de gran calibre. Su diseño de doble lumen proporciona un excelente soporte, capacidad de empuje y una rápida deflación del balón, favoreciendo un manejo preciso durante el tratamiento de lesiones complejas en los territorios ilíaco y femoral.</p>\n<p>Además, incorpora una punta distal atraumática y un sistema de plegado de <strong>6 alas (6-Wing Folding)</strong>, que contribuyen a un perfil de cruce reducido y facilitan la navegación y el retiro del dispositivo. Su combinación de soporte, eficiencia y versatilidad lo convierte en una solución confiable para el tratamiento endovascular de la enfermedad arterial periférica.</p>\n", "image": "assets/dd622c49a08f26f3.webp", "pdfs": [], "source": "https://academiayumyeong.com/alfacor/product/oceanus-35/", "quickType": "Balón de angioplastia periférica (PTA)", "quickSpecs": [["Guía", "0.035″"], ["Sistema", "OTW"], ["Plegado", "6 alas"], ["Punta", "Distal flexible"]]}, {"id": 695, "slug": "oceanus-18", "name": "Oceanus 18", "specialty": "vascular-periferico", "categories": [{"slug": "balon-semicomplaciente", "name": "Balón Semicomplaciente"}], "category": "Balón Semicomplaciente", "brand": "iVascular", "summary": "Catéter balón PTA versátil y de alto rendimiento, diseñado para abordar oclusiones desde las arterias ilíacas hasta los vasos infrapoplíteos. Compatible con guías de 0.018″, incorpora una tecnología exclusiva de plegado de 3 alas que le otorga el perfil de cruce más bajo de su clase y asegura una retracción rápida a través de la vaina introductora.", "content": "<p><strong>Oceanus 18</strong> es un catéter balón PTA de intercambio sobre guía (OTW) diseñado para procedimientos de angioplastia periférica. Compatible con guías de <strong>0.018″</strong> y <strong>0.014″</strong>, ofrece un excelente equilibrio entre soporte, flexibilidad y navegabilidad para el tratamiento de lesiones en arterias renales, ilíacas, femorales y poplíteas.</p>\n<p>Incorpora la tecnología <strong>3-Wing Refolding</strong>, que facilita la recuperación de un perfil de retirada reducido tras el inflado, y el recubrimiento hidrofílico <strong>HYDRAX®</strong>, que mejora el deslizamiento del catéter y favorece una navegación más eficiente en anatomías complejas.</p>\n", "image": "assets/dd622c49a08f26f3.webp", "pdfs": [], "source": "https://academiayumyeong.com/alfacor/product/oceanus-18/", "quickType": "Balón de angioplastia periférica (PTA)", "quickSpecs": [["Guías", "0.018″ / 0.014″"], ["Sistema", "OTW"], ["Plegado", "3-Wing Refolding"], ["Recubrimiento", "Hidrofílico HYDRAX"]]}, {"id": 693, "slug": "oceanus-14", "name": "Oceanus 14", "specialty": "vascular-periferico", "categories": [{"slug": "balon-semicomplaciente", "name": "Balón Semicomplaciente"}], "category": "Balón Semicomplaciente", "brand": "iVascular", "summary": "Catéter balón de dilatación para angioplastia transluminal percutánea (PTA) de perfil ultra bajo, diseñado específicamente para lesiones distales severas. Compatible con guía de 0.014″, destaca por su flexibilidad extrema y su recubrimiento hidrofílico avanzado que garantizan el acceso infrapoplíteo (Bajo la Rodilla / BTK).", "content": "<p>El catéter balón Oceanus 14 de iVascular es una herramienta de precisión diseñada para la revascularización de arterias distales y anatomías periféricas complejas. Con una arquitectura Over-The-Wire (OTW) optimizada para alambres guía de 0.014″, este dispositivo se especializa en navegar a través de estenosis críticas en los vasos femorales, poplíteos e infrapoplíteos.</p>\n<p>El secreto de su excepcional navegabilidad (trackability) radica en su diseño de eje de tres segmentos, el cual aumenta progresivamente su flexibilidad hacia el extremo distal. Esto se combina con la tecnología HYDRAX, un recubrimiento hidrofílico patentado y de alta durabilidad que reduce la fricción al mínimo durante todo el procedimiento. Además, su compatibilidad con introductores de 4Fr y su perfil de punta ultra afilado (0.017″) permiten a los especialistas tratar las lesiones más desafiantes con un trauma vascular prácticamente nulo.</p>\n", "image": "assets/dd622c49a08f26f3.webp", "pdfs": [], "source": "https://academiayumyeong.com/alfacor/product/oceanus-14/", "quickType": "Balón de angioplastia periférica (PTA)", "quickSpecs": [["Guía", "0.014″"], ["Sistema", "OTW"], ["Introductor", "4 Fr, según catálogo"], ["Perfil de punta", "0.017″"]]}, {"id": 690, "slug": "filtro-de-vena-cava", "name": "Filtro de Vena Cava", "specialty": "vascular-periferico", "categories": [{"slug": "filtros", "name": "Filtros"}], "category": "Filtros", "brand": "ALN Implants Chirurgicaux", "summary": "Filtro de vena cava inferior (VCI) de diseño opcional, concebido para la prevención permanente o temporal del embolismo pulmonar.   Fabricado en acero inoxidable 316LVM sin puntos de soldadura, destaca por su arquitectura de 9 puntales con tecnología anti-inclinación (anti-tilting) y su capacidad para adaptarse a venas cavas de hasta 32 mm de diámetro.", "content": "<p>El Filtro de Vena Cava ALN representa un estándar de seguridad y eficacia en el manejo profiláctico y terapéutico del tromboembolismo venoso. Su clasificación como filtro «opcional» otorga al especialista vascular la máxima flexibilidad clínica: puede dejarse implantado de forma permanente como barrera vitalicia, o puede ser recuperado percutáneamente una vez que el riesgo de embolia pulmonar del paciente haya mitigado.</p>\n<p>La integridad biomecánica es el pilar de este dispositivo. Es el único filtro del mercado fabricado íntegramente en acero inoxidable 316LVM sin un solo punto de soldadura, lo que elimina el riesgo de fractura estructural a largo plazo inducida por la fatiga del metal. Su diseño se compone de dos niveles de retención estratificados: un nivel inferior de centrado formado por 3 puntales largos, y un nivel superior de anclaje formado por 6 puntales cortos con terminaciones anti-transfixión, evitando la perforación de la pared venosa.</p>\n<p>A nivel de entrega, el sistema está optimizado para un perfil sumamente bajo, requiriendo únicamente un catéter introductor de 7Fr. Su ápex puede incluir un gancho (hook) que facilita enormemente la captura y extracción del filtro mediante un lazo endovascular o las pinzas de extracción específicas de ALN.</p>\n<h3>Beneficios y Características:</h3>\n<ul>\n<li>\n<p><b>Arquitectura Anti-Inclinación (Anti-Tilting):</b> Sus 9 puntales de diferente longitud evitan el entrelazamiento dentro del introductor y aseguran un centrado perfecto dentro de la vena, anulando el riesgo de inclinación que suele comprometer la eficacia de filtrado.</p>\n</li>\n<li>\n<p><b>Integridad sin Soldaduras:</b> Fabricado a partir de una única pieza de acero inoxidable 316LVM de grado médico, garantizando una resistencia mecánica excepcional frente a las constantes contracciones de la vena cava.</p>\n</li>\n<li>\n<p><b>Versatilidad de Accesos (7Fr):</b> Su diseño aerodinámico permite la implantación a través de 4 vías de acceso diferentes (Yugular, Femoral, Braquial y Poplítea) utilizando un introductor de bajo perfil de 7Fr.</p>\n</li>\n<li>\n<p><b>Adaptabilidad Anatómica Máxima:</b> Está clínicamente aprobado para ser desplegado en venas cavas con un diámetro máximo de hasta 32 mm, cubriendo un espectro de pacientes mucho más amplio que los filtros estándar.</p>\n</li>\n<li>\n<p><b>Compatibilidad RM (MRI):</b> A pesar de su núcleo de acero, el filtro ALN cuenta con compatibilidad condicional comprobada para Resonancia Magnética de alto campo (hasta 3 Tesla), permitiendo futuros seguimientos imagenológicos del paciente.</p>\n</li>\n</ul>\n", "image": "assets/cbcabefbd84a97a5.webp", "pdfs": [], "source": "https://academiayumyeong.com/alfacor/product/filtro-de-vena-cava/", "quickType": "Filtro de vena cava", "quickSpecs": [["Material", "Acero inoxidable 316LVM"], ["Introductor", "7 Fr"], ["Diámetro de cava", "Hasta 32 mm, según catálogo"], ["Estructura", "9 puntales; sin soldaduras"]]}, {"id": 689, "slug": "fargomini", "name": "FargoMini", "specialty": "neuro-intervencion", "categories": [{"slug": "cateter-guia-neuro", "name": "Catéter Guía"}, {"slug": "fargo", "name": "Fargo"}], "category": "Fargo", "brand": "Balt", "summary": "Catéter guía de acceso intermedio de bajo perfil diseñado para navegación distal extrema en procedimientos neurovasculares complejos. Su perfil transicional de 4.2Fr a 3.9Fr permite un acceso telescópico a través de catéteres guía de 6Fr, proporcionando soporte distal avanzado y una excelente capacidad de navegación intracraneal.", "content": "<h3><strong>Beneficios Clínicos Clave:</strong></h3>\n<ul>\n<li><strong>Soporte Distal Triaxial: </strong>Diseñado para utilizarse telescópicamente dentro de catéteres guía de 6Fr, extendiendo el soporte mecánico hasta territorios intracraneales distales.</li>\n</ul>\n<ul>\n<li><strong>Perfil Exterior Transicional: </strong>La transición progresiva de 4.2Fr a 3.9Fr combina estabilidad proximal con una navegación distal suave y atraumática.</li>\n</ul>\n<ul>\n<li><strong>Lumen Interno de 0.040″: </strong>Su lumen interno de 1.02 mm proporciona el espacio necesario para microcatéteres de embolización, permitiendo además la inyección eficiente de medio de contraste.</li>\n</ul>\n<ul>\n<li><strong>Punta Súper Flexible (Super-Supple): </strong>El segmento distal de alta flexibilidad facilita el acceso a anatomías complejas, sifones carotídeos y trayectos altamente tortuosos.</li>\n</ul>\n<ul>\n<li><strong>Variantes Geométricas: </strong>Disponible en diferentes longitudes y configuraciones de punta para adaptarse a diversas estrategias de acceso neurovascular.</li>\n</ul>\n", "image": "assets/3ce297edf05a5c6e.webp", "pdfs": [], "source": "https://academiayumyeong.com/alfacor/product/fargomini/", "quickType": "Catéter de soporte neurovascular", "quickSpecs": [["Lumen interno", "0.040″ (1.02 mm)"], ["Perfil externo", "4.2 → 3.9 Fr"], ["Sistema", "Triaxial, dentro de guía de 6 Fr"], ["Punta", "Distal flexible"]]}, {"id": 687, "slug": "fargomax", "name": "FargoMax", "specialty": "neuro-intervencion", "categories": [{"slug": "cateter-guia-neuro", "name": "Catéter Guía"}, {"slug": "fargo", "name": "Fargo"}], "category": "Fargo", "brand": "Balt", "summary": "Catéter guía neurovascular de alto rendimiento con lumen interno extra grande de 0.070″ (1.78 mm) en un perfil de 6Fr. Diseñado para proporcionar soporte proximal excepcional, facilitar técnicas multidispositivo y optimizar la navegación en anatomías intracraneales complejas.", "content": "<h3><strong>Beneficios Clínicos Clave:</strong></h3>\n<ul>\n<li><strong>Lumen Interno Extra Grande (0.070″):</strong> Su amplio diámetro interno permite el uso simultáneo de múltiples dispositivos, facilitando técnicas triaxiales y procedimientos neurovasculares complejos.</li>\n<li><strong>Trenzado de Geometría Variable:</strong> La arquitectura progresiva de la malla metálica proporciona excelente soporte proximal, resistencia al acodamiento y flexibilidad distal para una navegación estable.</li>\n<li><strong>Punta Distal Súper Flexible:</strong> Diseñada para atravesar anatomías severamente anguladas de forma segura y atraumática, minimizando el riesgo de lesión vascular.</li>\n<li><strong>Deslizamiento Hidrofílico Optimizado:</strong> El recubrimiento hidrofílico distal reduce la fricción durante el avance intracraneal y mejora la navegabilidad en vasos tortuosos.</li>\n<li><strong>Versatilidad Geométrica:</strong>  Disponible en diferentes longitudes y configuraciones de punta para adaptarse a múltiples estrategias de acceso neurovascular.</li>\n</ul>\n", "image": "assets/3ce297edf05a5c6e.webp", "pdfs": [], "source": "https://academiayumyeong.com/alfacor/product/fargomax/", "quickType": "Catéter de soporte neurovascular", "quickSpecs": [["Lumen interno", "0.070″"], ["Estructura", "Trenzado de geometría variable"], ["Recubrimiento", "Hidrofílico"], ["Punta", "Distal flexible"]]}, {"id": 685, "slug": "hybrid-guidewire", "name": "HYBRID Guidewire", "specialty": "neuro-intervencion", "categories": [{"slug": "microguia", "name": "Microguía"}], "category": "Microguía", "brand": "Balt", "summary": "Microguía neurovascular de acceso avanzado diseñada para proporcionar un equilibrio excepcional entre soporte proximal, transmisión de torque y flexibilidad distal. Su arquitectura bimetálica exclusiva combina acero inoxidable y nitinol para facilitar la navegación segura en anatomías complejas y altamente tortuosas.", "content": "<p>La familia de micro-guías HYBRID de Balt representa una solución de ingeniería excepcional para el acceso a las anatomías más tortuosas del cuerpo humano, específicamente en los intrincados lechos intracraneales y periféricos distales. Su diseño resuelve uno de los mayores dilemas clínicos en hemodinamia: obtener un alambre lo suficientemente firme para empujar un microcatéter, pero lo suficientemente dócil para no perforar los delicados microvasos cerebrales.</p>\n<p>Para lograrlo, Balt desarrolló un núcleo bimetálico continuo. El eje proximal está fabricado en acero inoxidable de alta tensión, lo que proporciona al operador un control direccional absoluto, excelente respuesta a la torsión (torque) y la fuerza de empuje (pushability) necesaria. Sin embargo, en su sección distal, el núcleo hace una transición fluida hacia el Nitinol. Esta aleación superelástica garantiza una extrema flexibilidad, una retención de forma inigualable y la capacidad de sortear vasos severamente angulados sin que la punta sufra deformaciones permanentes.</p>\n<h3>Beneficios y Características:</h3>\n<ul>\n<li>\n<p><b>Arquitectura Bimetálica Híbrida:</b> Integra las propiedades mecánicas críticas de dos aleaciones: máximo soporte proximal (Acero Inoxidable) y excepcional memoria de forma y flexibilidad distal (Nitinol).</p>\n</li>\n<li>\n<p><b>Perfil de Cruce Ultra Fino:</b> Es una de las guías más delgadas del mercado intervencionista, disponible en diámetros exteriores que inician en 0.007″ (0.18 mm), ideal para microvasculatura severamente estrecha.</p>\n</li>\n<li>\n<p><b>Punta Radiopaca Moldeable:</b> Su extremo distal incorpora una espiral (coil) altamente radiopaca que otorga una visibilidad nítida bajo fluoroscopia. Además, la punta es fácilmente moldeable por el especialista antes de la inserción.</p>\n</li>\n<li>\n<p><b>Navegabilidad Hidrofílica:</b> Cuenta con un recubrimiento hidrofílico de alto rendimiento a lo largo de su estructura insertable, anulando la fricción y permitiendo un seguimiento (trackability) fluido.</p>\n</li>\n<li>\n<p><b>Configuraciones Anatómicas:</b> Se comercializa en múltiples calibres (0.007″, 0.008″, 0.010″, 0.012″ y 0.014″), longitudes de trabajo estándar (200 a 220 cm) o de intercambio (310 cm), y opciones de punta Recta (Straight) o en Doble Ángulo (J/Double Angle).</p>\n</li>\n</ul>\n", "image": "assets/69d615db96888edd.webp", "pdfs": [{"url": "https://academiayumyeong.com/alfacor/wp-content/uploads/2026/03/ET-Hybrid-012-y-014-linea-94.pdf", "path": "assets/618f68b9c0be7033.pdf", "name": "ET-Hybrid-012-y-014-linea-94.pdf"}], "source": "https://academiayumyeong.com/alfacor/product/hybrid-guidewire/", "quickType": "Microguía neurovascular", "quickSpecs": [["Diámetros", "0.007 / 0.008 / 0.010 / 0.012 / 0.014″"], ["Longitudes", "200–220 cm / intercambio 310 cm"], ["Estructura", "Bimetálica"], ["Punta", "Radiopaca y moldeable"]]}, {"id": 682, "slug": "tightrail", "name": "TightRail", "specialty": "cardio-intervencion", "categories": [{"slug": "extraccion-de-electrodos", "name": "Extracción de Electrodos"}, {"slug": "vaina-dilatadora", "name": "Vaina Dilatadora"}], "category": "Vaina Dilatadora", "brand": "Philips", "summary": "Vaina mecánica de dilatación rotacional, diseñada para la extracción segura de electrodos cardíacos crónicamente implantados.  Su mecanismo de corte bidireccional se acciona mediante un gatillo manual, desplegando una cuchilla protegida que corta eficazmente el tejido fibrótico y las lesiones calcificadas sin comprometer la integridad de la pared vascular.", "content": "<p>La vaina de dilatación mecánica TightRail de Philips es una herramienta de vanguardia para los procedimientos de extracción de dispositivos electrónicos implantables cardiovasculares (CIED). Tras años de permanencia en el cuerpo humano, los electrodos desarrollan adherencias severas de tejido fibrótico y calcificaciones a lo largo del sistema venoso. El TightRail permite diseccionar mecánicamente estas uniones de forma controlada, avanzando coaxialmente sobre el electrodo a extraer.</p>\n<p>Su núcleo tecnológico se basa en un mecanismo de corte accionado por un gatillo manual en el extremo proximal. Al presionar el gatillo, la cuchilla distal protegida se extiende apenas 0.5 mm (0.02 pulgadas) y ejecuta una rotación bidireccional de 574° (287° en sentido horario y 287° en sentido antihorario). Esta acción fragmenta instantáneamente el tejido cicatricial. Al soltar el gatillo, la cuchilla se retrae inmediatamente dentro de su escudo metálico, garantizando que el borde cortante nunca quede expuesto accidentalmente contra la pared del vaso sanguíneo o los electrodos adyacentes.</p>\n<h3>Beneficios y Características:</h3>\n<ul>\n<li>\n<p><b>Corte Bidireccional Preciso:</b> Con cada activación completa del gatillo, la cuchilla realiza una rotación combinada de 574°, maximizando la eficiencia de la dilatación en sitios de unión duros o calcificados.</p>\n</li>\n<li>\n<p><b>Cuchilla Distal Protegida (Shielded Blade):</b> El filo de la cuchilla permanece oculto dentro del eje estático hasta que el médico acciona el mecanismo, otorgando un control absoluto y minimizando el riesgo de desgarros en la vena cava superior u otras estructuras vasculares.</p>\n</li>\n<li>\n<p><b>Eje Exterior Estático (Static Outer Shaft):</b> A diferencia de las vainas mecánicas tradicionales que giran en su totalidad, el tubo exterior del TightRail no rota con la cuchilla, evitando la fricción indeseada contra el endotelio durante el avance.</p>\n</li>\n<li>\n<p><b>Eje Altamente Flexible:</b> Su diseño estructural permite una excelente navegabilidad, ayudando al intervencionista a mantener una progresión frontal coaxial incluso en anatomías venosas tortuosas.</p>\n</li>\n<li>\n<p><b>Compatibilidad de Tamaños:</b> Disponible en calibres de 9 Fr, 11 Fr y 13 Fr, permitiendo al operador seleccionar la vaina adecuada según el diámetro del electrodo objetivo y la complejidad de la fibrosis.</p>\n</li>\n</ul>\n", "image": "assets/6a3bd686030cdb84.webp", "pdfs": [{"url": "https://www.documents.philips.com/assets/20240529/6300f7773d604b0dad07b17f00cda8da.pdf", "path": "assets/documento-7663df51df1e.pdf", "name": "Folleto TightRail · inglés", "label": "Folleto TightRail · inglés"}], "source": "https://academiayumyeong.com/alfacor/product/tightrail/", "quickType": "Vaina mecánica para extracción de electrodos", "quickSpecs": [["Tamaños", "9 / 11 / 13 Fr"], ["Corte", "Rotacional bidireccional"], ["Cuchilla", "Distal protegida"], ["Eje externo", "Estático"]], "philipsGroup": "extraction"}, {"id": 678, "slug": "lld-lead-locking-device", "name": "LLD (Lead Locking Device)", "specialty": "cardio-intervencion", "categories": [{"slug": "estilete-retencion-electrodo", "name": "Estilete de Retención de Electrodo"}, {"slug": "extraccion-de-electrodos", "name": "Extracción de Electrodos"}], "category": "Estilete de Retención de Electrodo", "brand": "Philips", "summary": "Dispositivo de bloqueo interno y tracción, diseñado específicamente para la extracción transvenosa de electrodos de marcapasos y desfibriladores crónicamente implantados. Su innovador mecanismo de malla de acero inoxidable se expande para anclarse a lo largo de todo el lumen interno del electrodo, proporcionando una tracción estable, segura y distribuyendo la fuerza para evitar la fractura del cable.", "content": "<p>El dispositivo de bloqueo de electrodos LLD de Philips es la herramienta fundamental en los procedimientos de extracción de dispositivos electrónicos implantables cardiovasculares (CIED). Cuando un electrodo de estimulación debe ser retirado debido a infección, oclusión venosa o falla mecánica, aplicar tracción desde el exterior conlleva un altísimo riesgo de ruptura. El LLD resuelve este desafío ingresando directamente por el lumen interno (hueco) del electrodo a extraer.</p>\n<p>Su ingeniería biomecánica se basa en un mandril central recubierto por una malla de acero inoxidable. Al desplegar el mecanismo proximal, esta malla se expande y se entrelaza firmemente contra las paredes internas del electrodo a lo largo de toda su longitud de contacto. Esta arquitectura única garantiza que la fuerza de tracción no se concentre en un solo punto distal, sino que se distribuya uniformemente. Además, las versiones de última generación (LLD EZ y LLD E) incorporan puntas flexibles que permiten sortear daños previos en el lumen y curvas pronunciadas con facilidad.</p>\n<h3>Beneficios y Características:</h3>\n<ul>\n<li>\n<p><b>Fijación a lo Largo de Todo el Lumen:</b> A diferencia de otros sistemas que solo se anclan en la punta, el LLD bloquea a lo largo de todo el lumen interno del electrodo, creando una plataforma de tracción sumamente estable.</p>\n</li>\n<li>\n<p><b>Reposicionamiento Clínico:</b> Su mecanismo es completamente reversible. El operador tiene la capacidad comprobada de bloquear, desbloquear y reposicionar el dispositivo dentro del electrodo si la estrategia quirúrgica lo requiere.</p>\n</li>\n<li>\n<p><b>Navegabilidad: </b>Los LLD cuentan con un perfil aerodinámico y una punta de platino-iridio altamente flexible, facilitando el avance a través de cables tortuosos o parcialmente colapsados.</p>\n</li>\n<li>\n<p><b>Máxima Fuerza de Tensión:</b> Diseñado para soportar tracciones mecánicas extremas durante la extracción, ofreciendo fuerzas de resistencia promedio que van desde las 12 libras hasta las 45 libras, dependiendo del modelo seleccionado.</p>\n</li>\n<li>\n<p><b>Marcadores Radiopacos:</b> Integra marcadores de alta densidad en su extremo distal que garantizan una visibilidad superior bajo fluoroscopia, permitiendo confirmar que el dispositivo ha alcanzado la punta del electrodo antes de iniciar la tracción.</p>\n</li>\n</ul>\n", "image": "assets/24264f32628fcaec.webp", "pdfs": [{"url": "https://www.documents.philips.com/assets/20260310/e2e88b6c06854ac3a89cb409016ebdf9.pdf", "path": "assets/documento-7e8974677b6a.pdf", "name": "Información de seguridad LLD · inglés", "label": "Información de seguridad LLD · inglés"}], "source": "https://academiayumyeong.com/alfacor/product/lld-lead-locking-device/", "quickType": "Estilete de bloqueo para extracción de electrodos", "quickSpecs": [["Fijación", "A lo largo del lumen del electrodo"], ["Bloqueo", "Reposicionable"], ["Visibilidad", "Marcadores radiopacos"]], "philipsGroup": "extraction"}, {"id": 676, "slug": "hyperion", "name": "Hyperion", "specialty": "cardio-intervencion", "categories": [{"slug": "cateter-guia", "name": "Catéter Guía"}, {"slug": "coronario", "name": "Coronario"}, {"slug": "asahi-catheters", "name": "Catéteres Asahi"}], "category": "Catéter Guía", "brand": "Asahi Intecc", "summary": "Catéter guía coronario de alto rendimiento, diseñado para proporcionar una plataforma de trabajo estable y un soporte de respaldo (backup) excepcional en Intervenciones Coronarias Percutáneas (PCI) complejas. Su tecnología de trenzado de rigidez variable y su diseño de triple curva garantizan una maniobrabilidad superior y una intubación atraumática del vaso.", "content": "<p>El catéter guía ASAHI Hyperion de Asahi Intecc está concebido para superar las condiciones anatómicas más exigentes durante procedimientos cardiovasculares. Como conducto principal de la intervención, este dispositivo asegura que el cardiólogo intervencionista cuente con un entorno mecánicamente estable, un factor fundamental para avanzar balones, stents y microcatéteres hacia lesiones distales o altamente restrictivas sin perder el acceso.</p>\n<p>La ingeniería estructural del Hyperion se distingue por su arquitectura «Hyper Shaft» y la tecnología de trenzado «HENKA-Braid». A diferencia de los catéteres guía convencionales, su malla metálica interna varía el patrón de trenzado desde la sección proximal hasta la distal. Esto otorga una alta rigidez en el extremo del operador para la transmisión directa de fuerza, y una transición fluida hacia una punta altamente flexible. Además, sus materiales poliméricos de vanguardia evitan la deformación estructural inducida por la temperatura y la humedad de la sangre, manteniendo el soporte intacto en procedimientos prolongados.</p>\n<h3>Beneficios y Características:</h3>\n<ul>\n<li>\n<p><b>Soporte de Respaldo Superior (Backup):</b> Incorpora una segunda curva reforzada para máxima retención de forma, y una tercera curva proximal exclusiva que incrementa el área de apoyo contra la pared aórtica, maximizando el anclaje del catéter.</p>\n</li>\n<li>\n<p><b>Tecnología HENKA-Braid:</b> Su estructura de trenzado variable previene el prolapso y evita el retroceso del catéter (salto fuera del ostium) al momento de empujar dispositivos terapéuticos de alto perfil.</p>\n</li>\n<li>\n<p><b>Lumen Interno Amplio y de Baja Fricción:</b> Su gran diámetro interno (1.80 mm para el modelo de 6Fr) facilita técnicas de bifurcación complejas como la técnica de balones simultáneos (Kissing Balloon Technique) y optimiza el flujo de contraste. Todo el lumen cuenta con un revestimiento de PTFE.</p>\n</li>\n<li>\n<p><b>Punta Flexible con Tungsteno:</b> Su extremo distal utiliza el mismo polímero blando con polvo de tungsteno empleado en el microcatéter Corsair Pro, asegurando una intubación segura y una visibilidad radiopaca profunda.</p>\n</li>\n<li>\n<p><b>Bordes Completamente Redondeados:</b> Las paredes de la punta han sido procesadas con un acabado esférico (All-Round Processed Tip) para garantizar una interacción atraumática y proteger el endotelio vascular durante el acoplamiento.</p>\n</li>\n</ul>\n", "image": "assets/a6d8b407bd5791eb.webp", "pdfs": [], "source": "https://academiayumyeong.com/alfacor/product/hyperion/", "quickType": "Catéter guía coronario", "quickSpecs": [["Trenzado", "HENKA-Braid"], ["Modelo 6 Fr", "Lumen interno de 1.80 mm"], ["Punta", "Flexible con tungsteno"], ["Bordes", "Redondeados"]], "asahiGroup": "catheters"}, {"id": 674, "slug": "capturer", "name": "Capturer", "specialty": "cardio-intervencion", "categories": [{"slug": "coronario", "name": "Coronario"}, {"slug": "tromboaspirador", "name": "Tromboaspirador"}], "category": "Tromboaspirador", "brand": "iVascular", "summary": "Catéter extractor de trombos de alta capacidad, diseñado para la remoción rápida de émbolos o trombos blandos de reciente formación en el sistema arterial coronario y periférico.   Equipado con un área de extracción maximizada y recubrimiento hidrofílico Hidrax+, garantiza una excelente navegabilidad, un bajo radio de acodamiento y una succión altamente efectiva.", "content": "<p>El catéter de aspiración Capturer es un dispositivo de intervención diseñado específicamente para el manejo de alta carga trombótica en vasos con un diámetro mínimo de 2 mm. Su uso es crítico en pacientes con Infarto Agudo de Miocardio con Elevación del Segmento ST (STEMI) y otras oclusiones agudas, donde la remoción mecánica del coágulo antes de la implantación del stent resulta vital para prevenir la embolización distal y restaurar el flujo miocárdico.</p>\n<p>La arquitectura de este catéter destaca por su área de extracción excepcionalmente grande (0.99 mm), lo que le permite alcanzar una tasa de aspiración superior de 1.7 cc/s en su versión de 6Fr. A nivel de diseño intravascular, cuenta con una capa interna de PTFE que facilita el deslizamiento ininterrumpido sobre la guía, mientras que su exterior está tratado con el recubrimiento hidrofílico avanzado Hidrax+. Esto, sumado a sus marcadores poliméricos, confiere al dispositivo un perfil de cruce ágil, alta fuerza de empuje (pushability) y un radio de acodamiento (kinking) virtualmente nulo.</p>\n<h3>Beneficios y Características:</h3>\n<ul>\n<li>\n<p><b>Alta Capacidad de Aspiración:</b> Su diseño optimizado presenta un área de extracción de 0.99 mm, logrando una succión rápida y potente de 1.7 cc/s (modelo 6Fr) para remover coágulos de gran volumen.</p>\n</li>\n<li>\n<p><b>Recubrimiento Avanzado Hidrax+:</b> El exterior del tubo está revestido con esta tecnología hidrofílica que reduce drásticamente la fricción contra el endotelio, asegurando una navegabilidad fluida en vasos tortuosos.</p>\n</li>\n<li>\n<p><b>Marcadores Poliméricos de Tungsteno:</b> Integra dos marcadores radiopacos (ubicados a 1.5 cm y a 15 cm de la punta) fabricados en polímero de tungsteno, lo que proporciona excelente visibilidad bajo fluoroscopia sin sacrificar la flexibilidad distal del catéter.</p>\n</li>\n<li>\n<p><b>Lumen Interno de PTFE:</b> La capa de politetrafluoroetileno garantiza un seguimiento suave (trackability) sobre el alambre guía, eliminando la resistencia mecánica durante el avance hacia la lesión.</p>\n</li>\n<li>\n<p><b>Reducción de Complicaciones Isquémicas:</b> El diseño de su punta y su eficacia de extracción permiten eliminar el trombo de forma simple, reduciendo significativamente la posibilidad de accidentes cerebrovasculares o ataques isquémicos transitorios post-operatorios.</p>\n</li>\n</ul>\n", "image": "assets/e20782d1140fa22f.webp", "pdfs": [], "source": "https://academiayumyeong.com/alfacor/product/capturer/", "quickType": "Catéter de aspiración de trombos", "quickSpecs": [["Modelo citado", "6 Fr"], ["Lumen interno", "PTFE"], ["Recubrimiento", "Hidrax+"], ["Marcadores", "A 1.5 y 15 cm de la punta"]]}, {"id": 671, "slug": "pronto", "name": "Pronto®", "specialty": "cardio-intervencion", "categories": [{"slug": "coronario", "name": "Coronario"}, {"slug": "tromboaspirador", "name": "Tromboaspirador"}], "category": "Tromboaspirador", "brand": "Teleflex", "summary": "Familia de catéteres de aspiración de alto rendimiento, diseñados para la remoción percutánea rápida y segura de trombos y émbolos frescos en el sistema coronario y periférico.   Cuentan con un lumen de extracción uniformemente grande y la punta patentada Silva, garantizando un poder de succión superior sin riesgo de adherencia a la pared vascular.", "content": "<p>Los catéteres de extracción Pronto® de Teleflex representan la solución definitiva en el laboratorio de hemodinamia para la aspiración de carga trombótica. Diseñados para optimizar el flujo de trabajo durante emergencias cardiovasculares, estos dispositivos combinan un lumen de extracción de volumen maximizado con una ingeniería estructural que previene el colapso del tubo (kinking) al aplicar presión negativa de vacío.</p>\n<p>El núcleo de su eficacia clínica reside en la punta patentada Silva. Este diseño distal cónico permite que el catéter se auto-centre dentro de la luz del vaso, previniendo el daño endotelial y evitando que el dispositivo succione y se adhiera a la pared vascular (íntima) durante la extracción. Para asegurar la máxima versatilidad clínica, la familia Pronto® se divide en cuatro variantes arquitectónicas: V4 para máxima resistencia, V3 para extrema navegabilidad, LP para perfiles distales estrechos y el modelo .035″ para carga trombótica masiva periférica.</p>\n<h3>Beneficios y Características:</h3>\n<ul>\n<li>\n<p><b>Punta Silva Patentada:</b> Su diseño distal biselado y auto-centrable protege el vaso y dirige la fuerza de vacío exclusivamente hacia el trombo, minimizando el riesgo de daño endotelial.</p>\n</li>\n<li>\n<p><b>Lumen de Extracción Maximizado:</b> Su arquitectura interna uniforme evita los cuellos de botella y permite la evacuación fluida de coágulos de gran tamaño sin obstruir el catéter. </p>\n</li>\n<li>\n<p><b>Deslizamiento Superior:</b> Todos los modelos integran un lumen interno revestido de PTFE y un recubrimiento hidrofílico en el segmento distal, promoviendo una navegación rápida y suave.</p>\n</li>\n<li>\n<p><b>Cuatro Modelos Especializados:</b></p>\n<ul>\n<li>\n<p><b>Pronto® V4:</b> Equipado con un alambre longitudinal incrustado que maximiza la resistencia al acodamiento y la fuerza de empuje. Disponible en 5.5, 6, 7 y 8 Fr.</p>\n</li>\n<li>\n<p><b>Pronto® V3:</b> Presenta un eje trenzado de longitud completa que equilibra una navegabilidad (deliverability) excepcional con alta protección estructural.</p>\n</li>\n<li>\n<p><b>Pronto® LP (Low Profile):</b> Perfil de cruce ultra bajo de 0.053″, ideal para vasos ≥1.5 mm. Compatible con catéteres guía de 5 y 6 Fr, e incluye un estilete precargado de soporte.</p>\n</li>\n<li>\n<p><b>Pronto® .035″:</b> Diseñado para carga trombótica en vasos periféricos o venosos profundos (&gt;4 mm de diámetro), operando sobre una guía periférica estándar de 0.035″</p>\n</li>\n</ul>\n</li>\n</ul>\n", "image": "assets/22daab082658159e.webp", "pdfs": [], "source": "https://academiayumyeong.com/alfacor/product/pronto/", "quickType": "Familia de catéteres de aspiración", "quickSpecs": [["Versiones", "V4 / V3 / LP / .035″"], ["V4", "5.5 / 6 / 7 / 8 Fr"], ["LP", "Perfil de cruce de 0.053″"], ["Modelo .035″", "Guía de 0.035″; aplicación periférica"]]}, {"id": 669, "slug": "guardian", "name": "Guardian", "specialty": "cardio-intervencion", "categories": [{"slug": "coronario", "name": "Coronario"}, {"slug": "valvula-hemostatica", "name": "Válvula Hemostática"}], "category": "Válvula Hemostática", "brand": "Teleflex", "summary": "Válvula hemostática de alto rendimiento, diseñada con una vía interna de 8 Fr.   y tecnología de sellado en forma de estrella.   Su diseño ergonómico asegura simultáneamente múltiples dispositivos, reduciendo significativamente la pérdida de sangre y permitiendo el movimiento independiente del alambre guía durante intervenciones complejas.", "content": "<p>La Válvula de Hemostasia Guardian II de Teleflex es un componente indispensable para mantener la seguridad y el control de fluidos durante Intervenciones Coronarias y Periféricas Percutáneas (PCI / PPI). Su función primaria es crear un sello hermético en el acceso vascular proximal, permitiendo al operador introducir, manipular e intercambiar instrumental diagnóstico o terapéutico sin comprometer la presión arterial del paciente ni provocar pérdidas hemáticas.</p>\n<p>Esta válvula destaca en el mercado gracias a su amplio lumen interno de 8 Fr., el cual incrementa en un 30% el área de trabajo útil en comparación con las válvulas hemostáticas estándar de 7 Fr. Esta amplitud espacial se combina con una innovadora junta de sellado en forma de estrella.</p>\n<h3>Beneficios y Características:</h3>\n<ul>\n<li>\n<p><b>Vía Interna de 8 Fr.:</b> Amplía sustancialmente el espacio de trabajo intravascular, facilitando el paso de dispositivos voluminosos o técnicas de bifurcación con un 30% más de holgura que los modelos de 7 Fr.</p>\n</li>\n<li>\n<p><b>Sellado en Forma de Estrella:</b> La matriz hemostática especial sella el paso de sangre alrededor del instrumental de forma independiente, preservando la libertad de fricción para poder manipular el alambre guía sin resistencia.</p>\n</li>\n<li>\n<p><b>Mecanismo Rotolock:</b> Incorpora un sistema rotatorio proximal que otorga al intervencionista la opción de fijar firmemente el dispositivo en su lugar para evitar desplazamientos accidentales durante la fluoroscopia.</p>\n</li>\n<li>\n<p><b>Operación Ergonómica (Una Sola Mano):</b> Su estructura física está diseñada para ser abierta y cerrada fácilmente con una sola mano, liberando la otra extremidad del médico para el control absoluto del catéter.</p>\n</li>\n<li>\n<p><b>Versatilidad de Cierre:</b> Para adaptarse a la sensibilidad táctil de cada especialista, está disponible en versión con retroalimentación auditiva y mecánica («Click») y en versión de presión lisa («No-Click»).</p>\n</li>\n</ul>\n", "image": "assets/79c5d55af99436d1.webp", "pdfs": [], "source": "https://academiayumyeong.com/alfacor/product/guardian/", "quickType": "Válvula hemostática", "quickSpecs": [["Lumen interno", "8 Fr"], ["Sellado", "Forma de estrella"], ["Mecanismo", "Rotolock"], ["Manejo", "Una mano"]]}, {"id": 667, "slug": "guideliner-v3", "name": "GuideLiner V3", "specialty": "cardio-intervencion", "categories": [{"slug": "coronario", "name": "Coronario"}, {"slug": "extensor-de-cateter", "name": "Extensor de Catéter"}], "category": "Extensor de Catéter", "brand": "Teleflex", "summary": "Extensor de catéter guía de tercera generación, diseñado para proporcionar soporte de respaldo (backup support) excepcional y alineación coaxial. Su tecnología patentada de media tubería (Half-Pipe) asegura una entrega suave y distal de dispositivos intervencionistas en anatomías coronarias tortuosas o complejas.", "content": "<p>El catéter GuideLiner V3 de Teleflex es la herramienta estándar de la industria en la categoría de extensión de catéteres guía, con más de medio millón de unidades utilizadas en laboratorios de hemodinamia a nivel mundial. Su propósito clínico es resolver uno de los desafíos más críticos en las Intervenciones Coronarias Percutáneas (PCI): La insuficiencia de soporte del catéter guía durante el avance de dispositivos a través de anatomías calcificadas, tortuosas o con angulaciones pronunciadas.</p>\n<p>La innovación fundamental del Guideliner V3 es su segmento de transición con tecnología de medio tubo (Half-Pipe), cuyo diseño semicircular actúa como un embudo direccional que alinea y facilita el avance de dispositivos intervencionistas (stents, balones, microcateres, etc) hacia el lumen del dispositivo. Al estar reforzado con coils metálicos, el segmento de extensión puede ser insertado profundamente en el vaso objetivo de manera segura y controlada, creando una vía directa hacia la lesión distal.</p>\n<h3>Beneficios y Características:</h3>\n<ul>\n<li>\n<p><b>Tecnología de Medio Tubo (Half-Pipe):</b> Su segmento de transición semicircular reduce la fricción, minimiza la interacción y facilita el paso de los dispositivos, permitiendo una entrada suave y una entrega continua de los mismos</p>\n</li>\n<li>\n<p><b>Soporte de Respaldo Excepcional:</b> Su diseño de extensión permite que el catéter ingrese selectivamente en arterias de difícil acceso, otorgando el máximo nivel de soporte (backup support) y alineación coaxial.</p>\n</li>\n<li>\n<p><b>Construcción Reforzada (Coil-Reinforced): </b>El segmento tubular distal incorpora una estructura interna reforzada con coil metálico que mejora la resistencia al acodamiento y mantiene la integridad del lumen interno bajo tensión mecánica.</p>\n</li>\n<li>\n<p><b>Navegación en Tortuosidad Extrema:</b> Reconocido como una herramienta esencial para abordar anatomías desafiantes, ángulos agudos e intubación profunda en vasos distales.</p>\n</li>\n<li>\n<p><b>Amplia Gama de Tamaños:</b> Disponible en configuraciones de 5, 5.5, 6, 7 y 8 Fr, asegurando total compatibilidad con la gran mayoría de catéteres guía estándar utilizados en el laboratorio.</p>\n</li>\n</ul>\n", "image": "assets/b91e6d0ac6c3f23a.webp", "pdfs": [{"url": "https://www.teleflex.com/la/es/product-areas/interventional/coronary-interventions/guideliner-coast-catheter/GuideLiner_Portfolio_Brochure_MC-009504_ES.pdf", "path": "assets/documento-78c1dbf6f73c.pdf", "name": "Folleto GuideLiner V3 / Coast · español", "label": "Folleto GuideLiner V3 / Coast · español"}], "source": "https://academiayumyeong.com/alfacor/product/guideliner-v3/", "quickType": "Extensión de catéter guía", "quickSpecs": [["Tamaños", "5 / 5.5 / 6 / 7 / 8 Fr"], ["Transición", "Half-Pipe"], ["Estructura", "Reforzada con espiral"], ["Función", "Soporte para entrega de dispositivos"]]}, {"id": 665, "slug": "sasuke", "name": "SASUKE", "specialty": "cardio-intervencion", "categories": [{"slug": "coronario", "name": "Coronario"}, {"slug": "microcateter", "name": "Microcatéter"}, {"slug": "asahi-microcatheters", "name": "Microcatéteres Asahi"}], "category": "Microcatéter", "brand": "Asahi Intecc", "summary": "Microcatéter coronario de doble lumen (Dual Lumen Microcatheter) diseñado para proporcionar máxima estabilidad y control en intervenciones complejas.  Su innovadora arquitectura de eje ovalado y su diseño de lumen rápido (Rx) actúan como un sistema de anclaje, evitando la rotación indeseada del dispositivo durante la manipulación de alambres guía de alta penetración.", "content": "<p>El microcatéter ASAHI SASUKE representa una solución de soporte avanzado para las Intervenciones Coronarias Percutáneas (PCI) más desafiantes. A diferencia de los microcatéteres tradicionales de lumen único, este dispositivo integra dos vías de acceso independientes: un lumen principal (Over-The-Wire u OTW) y un lumen de intercambio rápido (Rapid Exchange o Rx).</p>\n<p>El valor clínico fundamental de esta arquitectura dual reside en su capacidad de estabilización espacial. Cuando se aloja una guía en el lumen Rx, esta actúa como un ancla contra la pared del vaso. Esto neutraliza el movimiento de retroceso y evita el prolapso del catéter al momento de avanzar o rotar una segunda guía a través del lumen OTW. Para potenciar esta seguridad, el SASUKE presenta un diseño de eje ovalado (Oval design shaft) que se asienta de manera plana contra el endotelio, eliminando el efecto de rodadura típico de los catéteres cilíndricos al enfrentar lesiones restrictivas o bifurcaciones.</p>\n<h3>Beneficios y Características:</h3>\n<ul>\n<li>\n<p><b>Arquitectura de Doble Lumen:</b> Permite el uso simultáneo de dos alambres guía. El lumen Rx proporciona un efecto de anclaje firme, mientras que el lumen OTW se utiliza para avanzar el alambre de tratamiento hacia la lesión.</p>\n</li>\n<li>\n<p><b>Eje de Diseño Ovalado:</b> Su geometría distal ovalada estabiliza el catéter contra la pared vascular y ecualiza el grosor del material, reduciendo drásticamente el riesgo de que una guía rígida perfore la estructura del dispositivo.</p>\n</li>\n<li>\n<p><b>Resistencia Extrema al Acodamiento:</b> Construido con un núcleo trenzado de doble hilo de acero inoxidable que preserva la luz interna de los lúmenes y garantiza una excelente transmisión de la fuerza de empuje (pushability).</p>\n</li>\n<li>\n<p><b>Punta Cónica de 1.5Fr:</b> Hereda la tecnología de punta suave y cónica de las familias Corsair y Caravel, otorgando una navegabilidad (trackability) excepcional en redes arteriales severamente tortuosas.</p>\n</li>\n<li>\n<p><b>Recubrimiento Hidrofílico L³:</b> Incorpora 38 cm de recubrimiento L³ (Long Lasting Lubricity), una formulación química patentada que prolonga la durabilidad de la lubricidad durante los intercambios múltiples.</p>\n</li>\n</ul>\n", "image": "assets/96f7310cd11a4700.webp", "pdfs": [], "source": "https://academiayumyeong.com/alfacor/product/sasuke/", "quickType": "Microcatéter de doble lumen", "quickSpecs": [["Lúmenes", "2"], ["Punta", "1.5 Fr"], ["Eje", "Ovalado"], ["Recubrimiento", "Hidrofílico L³, 38 cm"]], "asahiGroup": "microcatheters"}, {"id": 663, "slug": "caravel", "name": "Caravel", "specialty": "cardio-intervencion", "categories": [{"slug": "coronario", "name": "Coronario"}, {"slug": "microcateter", "name": "Microcatéter"}, {"slug": "asahi-microcatheters", "name": "Microcatéteres Asahi"}], "category": "Microcatéter", "brand": "Asahi Intecc", "summary": "Microcatéter de soporte de perfil ultra bajo, diseñado para una navegación excepcional en anatomías coronarias y periféricas altamente tortuosas.   A diferencia de otros dispositivos, está concebido exclusivamente para el empuje (push-only), garantizando flexibilidad y resistencia al acodamiento mediante su eje trenzado ACT ONE sin necesidad de rotación mecánica.", "content": "<p>El microcatéter ASAHI Caravel destaca en el laboratorio de hemodinamia por su versatilidad y diseño de perfil ultra bajo, estructurado para simplificar el acceso a las redes vasculares más desafiantes. Mientras que la serie Corsair basa su eficacia en la penetración rotacional, el Caravel ha sido diseñado estrictamente para técnicas de avance por empuje continuo, por lo que el operador no debe aplicar fuerza de torsión (torque) sobre el dispositivo.</p>\n<p>Su arquitectura interna está impulsada por la tecnología patentada ACT ONE, un eje trenzado de precisión geométrica que otorga una flexibilidad incomparable en curvas muy cerradas sin comprometer la integridad del lumen interno. Esta resistencia mejorada frente al acodamiento (kinking) asegura un rendimiento fluido al momento de intercambiar alambres guía de soporte. Además, gracias a su diseño exterior extremadamente delgado, el especialista puede alojar hasta dos microcatéteres Caravel simultáneamente dentro de un solo catéter guía de 6Fr, ampliando radicalmente las opciones terapéuticas en abordajes de bifurcación complejos.</p>\n<h3>Beneficios y Características:</h3>\n<ul>\n<li>\n<p><b>Diseño Exclusivo para Empuje (Push-Only):</b> Optimizado biomecánicamente para rastrear suavemente el vaso sin rotación, reduciendo la fricción y el estrés sobre el endotelio en redes anatómicas muy anguladas.</p>\n</li>\n<li>\n<p><b>Punta de Perfil Ultra Bajo:</b> Su extremo distal suave y cónico se afina hasta los 1.4Fr (0.48 mm), otorgando una capacidad de seguimiento (trackability) superior para cruzar microcanales y estenosis restrictivas.</p>\n</li>\n<li>\n<p><b>Eje Trenzado ACT ONE:</b> Su estructura interna de múltiples hilos asegura una transición gradual de la rigidez, manteniendo la resistencia estructural a lo largo del cuerpo y protegiendo el lumen interno contra deformaciones.</p>\n</li>\n<li>\n<p><b>Compatibilidad de Múltiples Dispositivos:</b> Su bajo perfil de cruce (1.9Fr) permite el uso de dos microcatéteres Caravel en un catéter guía de 6Fr, o un Caravel combinado con un catéter IVUS en un catéter guía de 7Fr.</p>\n</li>\n<li>\n<p><b>Opciones de Longitud:</b> Disponible en el diámetro interno estándar para guías de 0.014″, con longitudes utilizables de 135 cm (70 cm de recubrimiento hidrofílico) y 150 cm (85 cm de recubrimiento hidrofílico).</p>\n</li>\n</ul>\n", "image": "assets/0d7547ae70bdd1bb.webp", "pdfs": [], "source": "https://academiayumyeong.com/alfacor/product/caravel/", "quickType": "Microcatéter de soporte", "quickSpecs": [["Guía", "0.014″"], ["Longitudes", "135 / 150 cm"], ["Punta", "1.4 Fr"], ["Recubrimiento", "70 / 85 cm, respectivamente"], ["Avance", "Por empuje; no rotacional"]], "asahiGroup": "microcatheters"}, {"id": 661, "slug": "corsair-pro-xs", "name": "Corsair Pro XS", "specialty": "cardio-intervencion", "categories": [{"slug": "coronario", "name": "Coronario"}, {"slug": "microcateter", "name": "Microcatéter"}, {"slug": "asahi-microcatheters", "name": "Microcatéteres Asahi"}], "category": "Microcatéter", "brand": "Asahi Intecc", "summary": "Microcatéter de soporte avanzado y bajo perfil, optimizado para el abordaje retrógrado en Oclusiones Totales Crónicas (CTO).   Su estructura interna cuenta con una trenza de 14 hilos que proporciona una navegabilidad extrema y un 43% más de fuerza de torsión en anatomías severamente tortuosas, manteniendo una punta ultrafina de 1.3Fr.", "content": "<p>El microcatéter ASAHI Corsair Pro XS representa la cima de la ingeniería de Asahi Intecc para intervenciones coronarias y periféricas de máxima complejidad. Ha sido meticulosamente diseñado para resolver el desafío clínico de rastrear canales epicárdicos o septales durante procedimientos CTO por vía retrógrada, donde la flexibilidad extrema y el bajo perfil son mandatorios.</p>\n<p>El secreto de su superioridad técnica frente a generaciones anteriores radica en la evolución de su tecnología SHINKA-Shaft. Mientras que el modelo estándar utiliza 10 hilos, el Corsair Pro XS incorpora una trenza concéntrica de 14 hilos metálicos ultrafinos. Esta innovación reduce el diámetro exterior del eje distal (a 2.1Fr) sin sacrificar resistencia, logrando transmitir hasta un 43% más de fuerza de torque directo hacia la punta. Su punta cónica, ahora más corta (6.5 mm), facilita una penetración incisiva en las placas calcificadas sin dilatar excesivamente la microvasculatura.</p>\n<h3>Beneficios y Características:</h3>\n<ul>\n<li>\n<p><b>Evolución SHINKA-Shaft (14 Hilos):</b> Su arquitectura de trenzado con 14 micro-hilos proporciona un rendimiento rotacional insuperable y una fuerza de torque un 43% mayor a las 10 rotaciones en comparación con el modelo anterior.</p>\n</li>\n<li>\n<p><b>Especialista en Abordaje Retrógrado:</b> Cuenta con la punta más flexible de la línea Corsair, lo que facilita el seguimiento de la guía (trackability) y el acceso seguro a través de canales colaterales severamente tortuosos.</p>\n</li>\n<li>\n<p><b>Punta Cónica Corta de 1.3Fr:</b> Su extremo de entrada mantiene un perfil ultrafino de 1.3Fr (0.44 mm) pero con una longitud cónica reducida a 6.5 mm, optimizando la capacidad de penetración inicial.</p>\n</li>\n<li>\n<p><b>Lubricidad Extendida:</b> Incorpora un recubrimiento hidrofílico de alto rendimiento disponible en longitudes de 70 cm y 85 cm, garantizando un deslizamiento profundo sin fricción.</p>\n</li>\n<li>\n<p><b>Spiral Protector:</b> Al igual que el modelo Pro, integra un refuerzo en espiral en el cono proximal que protege el eje contra acodamientos (kinking) durante el avance o retirada brusca.</p>\n</li>\n</ul>\n", "image": "assets/3d699862b6db996f.webp", "pdfs": [], "source": "https://academiayumyeong.com/alfacor/product/corsair-pro-xs/", "quickType": "Microcatéter CTO de bajo perfil", "quickSpecs": [["Punta", "1.3 Fr; segmento cónico de 6.5 mm"], ["Eje distal", "2.1 Fr"], ["Trenzado", "SHINKA-Shaft, 14 hilos"], ["Recubrimiento", "Hidrofílico"]], "asahiGroup": "microcatheters"}, {"id": 659, "slug": "corsair-pro", "name": "Corsair Pro", "specialty": "cardio-intervencion", "categories": [{"slug": "coronario", "name": "Coronario"}, {"slug": "microcateter", "name": "Microcatéter"}, {"slug": "asahi-microcatheters", "name": "Microcatéteres Asahi"}], "category": "Microcatéter", "brand": "Asahi Intecc", "summary": "Microcatéter de soporte avanzado con capacidad de torsión, diseñado específicamente para intervenciones percutáneas complejas y Oclusiones Totales Crónicas (CTO).   Su eje trenzado patentado y su punta cónica de bajo perfil permiten un avance rotacional seguro, brindando soporte estructural inigualable durante el intercambio de guías.", "content": "<p>El microcatéter ASAHI Corsair Pro es una herramienta fundamental en el laboratorio de hemodinamia para el abordaje de Oclusiones Totales Crónicas (CTO) y la revascularización en anatomías severamente tortuosas. Evolucionando a partir del diseño original de la familia Corsair, este dispositivo combina un soporte proximal excepcional con una flexibilidad distal optimizada, logrando rastrear vasos angulados con un mínimo grado de resistencia.</p>\n<p>La principal ventaja mecánica de este catéter radica en su capacidad de avance mediante rotación. Su estructura interna está impulsada por la tecnología SHINKA-Shaft, un eje compuesto por una bobina de acero inoxidable trenzada con 10 hilos metálicos. Esta arquitectura permite al cardiólogo intervencionista aplicar torque directo, facilitando que el catéter penetre y cruce placas densas de manera activa. Su diseño asegura que la fuerza se transmita eficientemente desde el operador hasta la lesión, sin sufrir acodaduras ni comprometer el lumen interno durante el intercambio de guías.</p>\n<h3>Beneficios y Características:</h3>\n<ul>\n<li>\n<p><b>Tecnología SHINKA-Shaft:</b> Integra un trenzado de 10 hilos metálicos (con adición de tungsteno) que proporciona una alta fuerza de empuje y permite una manipulación rotacional segura (límite de 10 rotaciones por dirección) para atravesar oclusiones.</p>\n</li>\n<li>\n<p><b>Punta Cónica de 1.3Fr:</b> Su extremo distal presenta un perfil de entrada ultra bajo de 1.3Fr (0.42 mm), lo que maximiza la capacidad de rastreo en lesiones restrictivas y facilita la penetración inicial en el tejido.</p>\n</li>\n<li>\n<p><b>Transición de Rigidez Lineal:</b> A diferencia de modelos anteriores, el Corsair Pro posee un perfil de rigidez mucho más gradual entre la punta blanda y el cuerpo rígido, mejorando la flexibilidad general en lechos vasculares complejos.</p>\n</li>\n<li>\n<p><b>Protector en Espiral (Spiral Protector):</b> Cuenta con un refuerzo mecánico en el cono proximal que incrementa la resistencia al acodamiento (kinking) protegiendo el eje durante las maniobras de avance o retirada abrupta.</p>\n</li>\n<li>\n<p><b>Visibilidad y Deslizamiento:</b> La totalidad de la punta es visible bajo fluoroscopia para un posicionamiento exacto. Además, incluye 60 cm de recubrimiento hidrofílico y está disponible en longitudes de 135 cm y 150 cm.</p>\n</li>\n</ul>\n", "image": "assets/1ce178c3420b9332.webp", "pdfs": [], "source": "https://academiayumyeong.com/alfacor/product/corsair-pro/", "quickType": "Microcatéter CTO rotacional", "quickSpecs": [["Longitudes", "135 / 150 cm"], ["Punta", "1.3 Fr"], ["Trenzado", "SHINKA-Shaft, 10 hilos"], ["Recubrimiento", "Hidrofílico, 60 cm"]], "asahiGroup": "microcatheters"}, {"id": 657, "slug": "turnpike", "name": "Turnpike®", "specialty": "cardio-intervencion", "categories": [{"slug": "coronario", "name": "Coronario"}, {"slug": "microcateter", "name": "Microcatéter"}], "category": "Microcatéter", "brand": "Teleflex", "summary": "Familia avanzada de microcatéteres de soporte, diseñados para cruzar Oclusiones Totales Crónicas (CTO) y acceder a anatomías coronarias y periféricas complejas. Cuenta con un eje robusto de cinco capas y está disponible en cuatro configuraciones de punta especializadas (Gold, LP, Smooth y Spiral) para adaptarse a diferentes niveles de calcificación y perfiles de lesión.", "content": "<p>La serie de microcatéteres Turnpike® de Teleflex representa un avance significativo en el soporte y la navegabilidad durante intervenciones percutáneas de alta complejidad. Estos dispositivos están diseñados específicamente para facilitar el acceso a vasos discretos, proporcionar soporte estructural continuo durante el intercambio de guías (wire escalation) y permitir la infusión subselectiva de agentes terapéuticos o contraste directamente en el lecho de la lesión.</p>\n<p>El núcleo del rendimiento de la familia Turnpike reside en su eje reforzado de cinco capas, el cual integra una trenza biaxial que otorga una transmisión de torque excepcional y una resistencia superior al acodamiento (kink resistance). Para enfrentar la diversidad anatómica de las estenosis, Teleflex ha desarrollado cuatro perfiles distintos en el extremo distal del catéter. Esta versatilidad permite al especialista rotar y avanzar el catéter a través de oclusiones fibrosas, lesiones fuertemente calcificadas o vasos tortuosos de bajo perfil con un control milimétrico.</p>\n<h3>Beneficios y Características:</h3>\n<ul>\n<li>\n<p><b>Eje Reforzado de 5 Capas:</b> Su construcción multicapa con trenza biaxial garantiza que la fuerza de torsión y el empuje aplicados en el extremo proximal se transmitan eficientemente a la punta distal sin deformar el catéter.</p>\n</li>\n<li>\n<p><b>Cuatro Configuraciones de Punta:</b></p>\n<ul>\n<li>\n<p><b>Turnpike® Spiral:</b> Incorpora un hilo metálico en espiral en el exterior de la punta, permitiendo un avance rotacional mecánico tipo «sacacorchos» a través de oclusiones densas.</p>\n</li>\n<li>\n<p><b>Turnpike® Gold:</b> Mantiene el hilo en espiral pero añade una punta roscada chapada en oro (Gold-plated), otorgando la máxima rigidez y fuerza de penetración para las calcificaciones más extremas.</p>\n</li>\n<li>\n<p><b>Turnpike® LP (Low Profile):</b> Ofrece un perfil de cruce y un diámetro exterior reducidos, ideal para navegar vasos tortuosos, pequeños lechos colaterales y conductos epicárdicos.</p>\n</li>\n<li>\n<p><b>Turnpike® Smooth:</b> Variante que elimina la espiral metálica y añade una transición suave y lisa, maximizando el deslizamiento para maniobras de intercambio estándar o soporte en lesiones menos restrictivas.</p>\n</li>\n</ul>\n</li>\n<li>\n<p><b>Recubrimiento de Teflón Interno:</b> El lumen interno de toda la serie está recubierto con PTFE para minimizar la fricción, garantizando una manipulación fluida de guías de hasta 0.014″.</p>\n</li>\n<li>\n<p><b>Variantes de Longitud:</b> Toda la familia (Gold, LP, Smooth y Spiral) se encuentra disponible en longitudes utilizables de 135 cm y 150 cm, abarcando abordajes tanto proximales como distales severos.</p>\n</li>\n</ul>\n", "image": "assets/00d46762e12c87c4.webp", "pdfs": [{"url": "https://www.teleflex.com/la/es/product-areas/interventional/coronary-interventions/turnpike-catheters/ES_MC-005030-Turnpike-brochure.pdf", "path": "assets/documento-62ec9eec8c20.pdf", "name": "Folleto Turnpike · español", "label": "Folleto Turnpike · español"}], "source": "https://academiayumyeong.com/alfacor/product/turnpike/", "quickType": "Familia de microcatéteres de soporte", "quickSpecs": [["Guía", "Hasta 0.014″"], ["Longitudes", "135 / 150 cm"], ["Versiones", "Gold / LP / Smooth / Spiral"], ["Eje", "5 capas"], ["Lumen interno", "PTFE"]]}, {"id": 655, "slug": "supercross", "name": "SuperCross™", "specialty": "cardio-intervencion", "categories": [{"slug": "coronario", "name": "Coronario"}, {"slug": "microcateter", "name": "Microcatéter"}], "category": "Microcatéter", "brand": "Teleflex", "summary": "Microcatéter avanzado diseñado para brindar un soporte excepcional en anatomías tortuosas y facilitar el acceso a ramas laterales complejas.   Su construcción de doble espiral y múltiples opciones de angulación de punta garantizan una navegabilidad superior y una entrega segura de guías en intervenciones coronarias y periféricas.", "content": "<p>El microcatéter SuperCross™ de Teleflex es una herramienta indispensable en el laboratorio de hemodinamia para abordar anatomías vasculares altamente desafiantes. Diseñado para utilizarse en conjunto con alambres guía orientables, este dispositivo facilita el acceso a regiones anatómicas discretas, el intercambio seguro de instrumental y la administración subselectiva de medios de contraste o agentes terapéuticos.</p>\n<p>Su arquitectura interna destaca por un eje de doble espiral reforzado con una trenza de acero inoxidable. Esta ingeniería se traduce en una excelente respuesta de torsión (torque), una óptima capacidad de empuje y una altísima resistencia al acodamiento (kink resistance). Además, su lumen interior está completamente recubierto de PTFE, garantizando que el alambre guía se deslice de manera fluida y sin fricción durante los intercambios más críticos del procedimiento.</p>\n<h3>Beneficios y Características:</h3>\n<ul>\n<li>\n<p><b>Múltiples Opciones de Punta:</b> Disponible en configuraciones de punta Flexible (FT), Recta, 45°, 90°, 120° y 90° XT (punta extendida), permitiendo al especialista seleccionar el ángulo geométrico exacto para canular de forma segura cualquier bifurcación.</p>\n</li>\n<li>\n<p><b>Construcción de Doble Espiral (Dual Coil):</b> Su diseño estructural proporciona el equilibrio perfecto entre flexibilidad y soporte, permitiendo maniobrar a través de vasos angulados sin perder transmisión de fuerza ni control.</p>\n</li>\n<li>\n<p><b>Lumen Interno de PTFE:</b> La capa interna de politetrafluoroetileno (PTFE) asegura un control sobresaliente del alambre guía y facilita la inyección rápida de contraste a lo largo de todo el catéter.</p>\n</li>\n<li>\n<p><b>Recubrimiento Hidrófilo Estratégico:</b> Cuenta con un recubrimiento hidrófilo en los 80 cm distales para las versiones de punta en ángulo, y en los 40 cm distales para las versiones de punta flexible o recta, maximizando el deslizamiento en curvas cerradas.</p>\n</li>\n<li>\n<p><b>Visibilidad Radiopaca Superior:</b> Integra una espiral de platino y tungsteno incrustada en el extremo distal, brindando una nitidez visual excepcional bajo fluoroscopia a lo largo de toda la longitud de la punta.</p>\n</li>\n</ul>\n", "image": "assets/9cfea683dc1d4603.webp", "pdfs": [{"url": "https://www.teleflex.com/la/es/product-areas/interventional/coronary-interventions/supercross-microcatheters/ES_SuperCross_Microcatheter_Brochure.pdf", "path": "assets/documento-c6f93119430d.pdf", "name": "Folleto SuperCross · español", "label": "Folleto SuperCross · español"}], "source": "https://academiayumyeong.com/alfacor/product/supercross/", "quickType": "Microcatéter de acceso angulado", "quickSpecs": [["Puntas", "Flexible / recta / 45° / 90° / 120° / 90° XT"], ["Estructura", "Doble espiral"], ["Lumen interno", "PTFE"], ["Recubrimiento", "80 cm angulados / 40 cm flexible y recto"]]}, {"id": 653, "slug": "omniwire", "name": "OmniWire", "specialty": "cardio-intervencion", "categories": [{"slug": "coronario", "name": "Coronario"}, {"slug": "fisiologia", "name": "Fisiología"}], "category": "Fisiología", "brand": "Philips", "summary": "La primera guía coronaria de presión de núcleo sólido del mundo.   Combina la excelente navegabilidad y soporte de una guía de trabajo polivalente (workhorse) con la tecnología más avanzada para la medición de índices fisiológicos como iFR y FFR, permitiendo evaluar la isquemia directamente en la sala de hemodinamia.", "content": "<p>La guía de presión OmniWire de Philips revoluciona el diagnóstico funcional y la intervención coronaria percutánea al eliminar el tradicional diseño de hipotubo hueco. En su lugar, presenta una arquitectura de núcleo sólido construida con una aleación de cobalto de alta resistencia en su porción proximal y un núcleo distal de Nitinol superelástico. Esta innovación estructural le otorga una respuesta de torque, una capacidad de empuje y una resistencia a las acodaduras (kinking) idénticas a las de una guía de intervención polivalente convencional.</p>\n<p>Para transmitir los datos fisiológicos sin comprometer el perfil de la guía, OmniWire utiliza bandas conductoras integradas en su capa de polímero externo. Este diseño no solo facilita la carga y el intercambio de dispositivos sobre la guía, sino que asegura una fiabilidad de señal excepcional durante todo el procedimiento. Al sincronizarse con plataformas de terapia guiada como Philips IntraSight, permite realizar el co-registro de datos iFR, superponiendo los valores de presión directamente sobre el angiograma para identificar con exactitud milimétrica la ubicación de la lesión causante de la isquemia.</p>\n<h3>Beneficios y Características:</h3>\n<ul>\n<li>\n<p><b>Diseño de Núcleo Sólido:</b> Su construcción exclusiva reemplaza el hipotubo hueco por un núcleo sólido de aleación de cobalto y Nitinol, mejorando drásticamente el torque, el soporte y la durabilidad frente a anatomías complejas.</p>\n</li>\n<li>\n<p><b>Medición Fisiológica (iFR / FFR):</b> Equipada con un micro-sensor de presión, permite obtener mediciones precisas de la Reserva de Flujo Fraccional (FFR) y del Ratio Instantáneo sin Ondas (iFR), el índice de reposo respaldado por los mayores ensayos clínicos.</p>\n</li>\n<li>\n<p><b>Bandas Conductoras Integradas:</b> Transmite la señal de presión mediante cintas conductoras adheridas a su estructura, permitiendo que el extremo posterior sea una pieza continua sin juntas, lo que facilita reconexiones rápidas y seguras.</p>\n</li>\n<li>\n<p><b>Co-registro iFR Angiográfico:</b> Es plenamente compatible con el sistema de co-registro iFR, el cual mapea y proyecta los valores fisiológicos directamente sobre la imagen de rayos X, ayudando a planificar la longitud y el posicionamiento exacto del stent.</p>\n</li>\n<li>\n<p><b>Recubrimientos Especializados:</b> Cuenta con un revestimiento hidrofílico en sus 39 cm distales para minimizar la fricción en la lesión, y un recubrimiento hidrofóbico en los 146 cm proximales para garantizar un control táctil firme por parte del operador.</p>\n</li>\n</ul>\n", "image": "assets/e4286c241f7430d8.webp", "pdfs": [{"url": "https://www.documents.philips.com/assets/20200406/e05abe9f2fcb4fbb8d1fab95017b7757.pdf", "path": "assets/documento-8a95d56156f5.pdf", "name": "Ficha OmniWire · inglés", "label": "Ficha OmniWire · inglés"}], "source": "https://academiayumyeong.com/alfacor/product/omniwire/", "quickType": "Guía de presión coronaria", "quickSpecs": [["Mediciones", "iFR / FFR"], ["Núcleo", "Sólido"], ["Integración", "Co-registro iFR"], ["Recubrimiento distal", "Hidrofílico, 39 cm"]], "philipsGroup": "coronary"}, {"id": 651, "slug": "refinity-st", "name": "Refinity ST", "specialty": "cardio-intervencion", "categories": [{"slug": "coronario", "name": "Coronario"}, {"slug": "ivus", "name": "IVUS"}], "category": "IVUS", "brand": "Philips", "summary": "Refinity®  (Short-tip rotational) es un catéter de ultra sonido intravascular (IVUS) digital con una capacidad de entrega excepcional, compatible con guías 5Fr, 135cm de longitud de trabajo, perfil proximal de 3F y con 45 MHz imagen de alta resolución.", "content": "<p><strong>Sus características más relevantes son las siguientes:</strong></p>\n<p>• Cable de transmisión Asahi Intecc grande de 0,026 pulgadas para una mayor capacidad de empuje.<br>\n• Transición uniforme desde el extremo proximal hasta el eje medio.<br>\n• Recubrimiento hidrófilo GlyDx que ofrece una mejor capacidad de empuje y trazabilidad.<br>\n• La punta suave y flexible facilita el acceso distal.</p>\n<p><strong>Alta resolución de imagen de 45 MHz:</strong></p>\n<p>• Imágenes claras y nítidas para una interpretación y evaluación precisa de los vasos coronarios.<br>\n• Ayuda a evaluar la anatomía de la lesión para proporcionar precisión en el tamaño y colocación del stent.<br>\n• La ecografía Hi-Q permite personalizar la imagen para identificar mejor las características de la luz del vaso.</p>\n<p>La Refinity® es compatible con el dispositivo de retracción automática SpinVision en el cual se permiten realizar retracciones suaves y automáticas que ayudan a realizar mediciones exactas de los vasos y las lesiones, a su vez posee la opción de retracción manual lo que ofrece un mayor control cuando es necesario.</p>\n<p>Diámetro máximo de imagen 14mm.</p>\n", "image": "assets/61f5ad5bbee181e8.webp", "pdfs": [{"url": "https://www.documents.philips.com/assets/20180612/12c4e10490bc40a18458a8fd015a7482.pdf", "path": "assets/documento-4d01b58381ec.pdf", "name": "Folleto Refinity ST · inglés", "label": "Folleto Refinity ST · inglés"}], "source": "https://academiayumyeong.com/alfacor/product/refinity-st/", "quickType": "Catéter IVUS rotacional", "quickSpecs": [["Longitud de trabajo", "135 cm"], ["Frecuencia nominal", "45 MHz"], ["Marcas radiopacas", "1 banda a 5 mm de la punta + transductor"], ["Campo de imagen", "14 mm"], ["Transmisión", "Cable Asahi Intecc de 0.026″"]], "officialSource": "https://www.documents.philips.com/assets/Instruction%20for%20Use/20240205/29d224a3700b4a27afc7b10d017bf6c3.pdf", "specificationSources": ["https://www.documents.philips.com/assets/20240524/76534953c09a42ddb212b17a008c9160.pdf", "https://www.documents.philips.com/assets/Instruction%20for%20Use/20240205/29d224a3700b4a27afc7b10d017bf6c3.pdf"], "philipsGroup": "coronary"}, {"id": 649, "slug": "eagle-eye-platinum-st", "name": "Eagle Eye Platinum ST", "specialty": "cardio-intervencion", "categories": [{"slug": "coronario", "name": "Coronario"}, {"slug": "ivus", "name": "IVUS"}], "category": "IVUS", "brand": "Philips", "summary": "Eagle Eye Platinum Punta Corta (ST)  es un catéter de ultrasonido intravascular (IVUS) digital, con tecnología “plug-and-play”. \nSus características incluyen: una punta cónica suave, recubrimiento hidrófilo para mayor lubricidad, catéter de 3.5Fr con una luz de intercambio rápida y larga para mejorar la capacidad de empuje, tres marcadores radiopacos, distancia de la punta del dispositivo al trasductor de 2.5mm y compatibilidad con SyncVision para el co-registro conjunto con la angiografía.", "content": "<p><strong>Características estándar de la punta corta del Eagle Eye Platinum </strong><strong>ST:</strong></p>\n<p>• Catéter de IVUS, con un transductor digital.</p>\n<p>• ChromaFlo: Visualización a color del flujo de sangre en vivo. Corregistro: Integración de las imágenes del IVUS con su correlación anatómica por medio de la angiografía. Punta corta 2.5mm: facilidad de acceso a ramas o bifurcaciones y asistencia en procedimientos de oclusiones crónicas</p>\n<p>• Inserción excepcional – revestimiento hidrófilo glyDx con un bajo perfil de entrada.</p>\n<p>• Marcadores radiopacos – estimación de la longitud rápida y cómoda.</p>\n<p>• Plug-and-play: único IVUS digital disponible en el mercado, rapidez y simplicidad de conexión. Diámetro máximo de imagen 20mm.</p>\n<p>• Flujo de trabajo eficiente mediante la obtención permanente de imágenes, incluso durante la colocación.</p>\n<p><strong>Características adicionales de la punta corta del Eagle Eye Platinum ST:</strong></p>\n<p>• Distancia más corta de la punta al transductor (2,5 mm) que permite una visualización más cercana de las lesiones muy estenosadas, bifurcaciones y anatomía distal.<br>\n• Navegabilidad mejorada</p>\n", "image": "assets/e7ffe9a3d6dcfe9c.webp", "pdfs": [{"url": "https://www.documents.philips.com/assets/20240524/76534953c09a42ddb212b17a008c9160.pdf", "path": "assets/documento-3b06564e654e.pdf", "name": "Especificaciones IVUS coronario · inglés", "label": "Especificaciones IVUS coronario · inglés"}], "source": "https://academiayumyeong.com/alfacor/product/eagle-eye-platinum-st/", "quickType": "Catéter IVUS digital de punta corta", "quickSpecs": [["Longitud de trabajo", "150 cm"], ["Frecuencia nominal", "20 MHz"], ["Marcas radiopacas", "Transductor + 3 marcas separadas 10 mm"], ["Punta a transductor", "2.5 mm"], ["Campo de imagen", "20 mm"], ["Recubrimiento", "Hidrofílico glyDx"], ["Adquisición", "Digital"]], "officialSource": "https://www.documents.philips.com/assets/20240524/76534953c09a42ddb212b17a008c9160.pdf", "specificationSources": ["https://www.documents.philips.com/assets/20240524/76534953c09a42ddb212b17a008c9160.pdf"], "philipsGroup": "coronary"}, {"id": 646, "slug": "eagle-eye-platinum", "name": "Eagle Eye Platinum", "specialty": "cardio-intervencion", "categories": [{"slug": "coronario", "name": "Coronario"}, {"slug": "ivus", "name": "IVUS"}], "category": "IVUS", "brand": "Philips", "summary": "Eagle Eye Platinum®  es un catéter de ultrasonido intravascular (IVUS) digital, con tecnología “plug-and-play”. Sus características incluyen: una punta cónica suave, recubrimiento hidrófilo para mayor lubricidad, catéter de 3.5Fr con una luz de intercambio rápida y larga para mejorar la capacidad de empuje, tres marcadores radiopacos, distancia de la punta del dispositivo al transductor de 10mm y compatibilidad con SyncVision para el co-registro conjunto con la angiografía.", "content": "<p><strong>Características punta estándar del Eagle Eye Platinum (10mm):</strong></p>\n<p>• Catéter IVUS digital, con un transductor digital.<br>\n• ChromaFlo: Visualización a color del flujo de sangre en vivo. Corregistro: Integración de las imágenes del IVUS con su correlación anatómica por medio de la angiografía<br>\n• Inserción excepcional – revestimiento hidrófilo glyDx con un bajo perfil de entrada.<br>\n• Marcadores radiopacos – estimación de la longitud rápida y cómoda.<br>\n• Rapidez y simplicidad de conexión – facilidad de uso. Plug-and-play: único IVUS digital disponible en el mercado, rapidez y simplicidad de conexión. Diámetro máximo de imagen 20mm.<br>\n• Flujo de trabajo eficiente mediante la obtención permanente de imágenes, incluso durante la colocación.</p>\n", "image": "assets/d72d355968eef453.webp", "pdfs": [{"url": "https://www.documents.philips.com/assets/20240524/51ecdd7957364ddc9ce5b17a008c2fa1.pdf", "path": "assets/documento-ddf33aae24e4.pdf", "name": "Folleto Eagle Eye Platinum · inglés", "label": "Folleto Eagle Eye Platinum · inglés"}], "source": "https://academiayumyeong.com/alfacor/product/eagle-eye-platinum/", "quickType": "Catéter IVUS digital", "quickSpecs": [["Longitud de trabajo", "150 cm"], ["Frecuencia nominal", "20 MHz"], ["Marcas radiopacas", "Transductor + 3 marcas separadas 10 mm"], ["Punta estándar", "10 mm"], ["Campo de imagen", "20 mm"], ["Transductor", "Digital"]], "officialSource": "https://www.documents.philips.com/assets/20240524/76534953c09a42ddb212b17a008c9160.pdf", "specificationSources": ["https://www.documents.philips.com/assets/20240524/76534953c09a42ddb212b17a008c9160.pdf"], "philipsGroup": "coronary"}, {"id": 645, "slug": "astato-xs-40", "name": "Astato XS 40", "specialty": "cardio-intervencion", "categories": [{"slug": "coronario", "name": "Coronario"}, {"slug": "cto", "name": "CTO"}, {"slug": "guias", "name": "Guías"}, {"slug": "asahi-guides", "name": "Guías Asahi"}], "category": "CTO", "brand": "Asahi Intecc", "summary": "Alambre guía periférico de máxima penetración, diseñado con una punta cónica para atravesar oclusiones altamente calcificadas.  Disponible en dos variantes de alta carga (20gf y 40gf) que resultan ideales para aplicar la técnica de escalada de alambres (wire escalation) en escenarios de resistencia anatómica extrema.", "content": "<p>Las guías periféricas ASAHI Astato XS 20 y XS 40 están desarrolladas específicamente para enfrentar los desafíos más severos en la revascularización de extremidades y anatomía periférica. Cuando el cirujano vascular o el radiólogo intervencionista se encuentra ante Oclusiones Totales Crónicas (CTO) con niveles de calcificación que bloquean el paso de guías de trabajo convencionales, la familia Astato despliega su poder de penetración directa.</p>\n<p>El secreto de su eficacia clínica reside en su punta cónica (tapered tip) y su eje distal estructurado, los cuales concentran toda la fuerza de empuje del operador en un micro-punto enfocado. Esto facilita la perforación mecánica de la placa. Además, al ofrecer dos niveles de fuerza de soporte excepcionalmente altos, el médico puede comenzar el abordaje con la XS 20 y, de ser necesario, escalar a la XS 40 para superar las barreras calcáreas más impenetrables del vaso.</p>\n<h3>Beneficios y Características:</h3>\n<ul>\n<li>\n<p><b>Penetración Cónica Superior:</b> Su extremo distal cónico está diseñado para actuar de forma incisiva, proporcionando una capacidad de perforación focalizada e insuperable en lesiones periféricas endurecidas.</p>\n</li>\n<li>\n<p><b>Técnica de Escalada (Wire Escalation):</b> La disponibilidad de dos modelos con cargas de punta de 20 gramos-fuerza y 40 gramos-fuerza permite al intervencionista adaptar gradualmente el nivel de fuerza según la dureza de la lesión.</p>\n</li>\n<li>\n<p><b>Punta de Bola sin Recubrimiento (Uncoated Ball Tip):</b> Su punta distal intencionalmente carece de recubrimiento hidrofílico, lo que asegura un anclaje firme sobre la calcificación y proporciona una retroalimentación táctil pura, previniendo desvíos hacia rutas subintimales.</p>\n</li>\n<li>\n<p><b>Deslizamiento Intravascular:</b> A pesar de tener la punta sin recubrir, el resto de la estructura cuenta con un recubrimiento hidrofílico que reduce la fricción y asegura un seguimiento suave a través de las tortuosidades del acceso.</p>\n</li>\n<li>\n<p><b>Configuraciones de Longitud Periférica:</b> Disponibles en un diámetro base de 0.014″, con opciones de longitud utilizable de 180 cm y 300 cm (para el modelo XS 20) y 200 cm y 300 cm (para el modelo XS 40).</p>\n</li>\n</ul>\n", "image": "assets/286e845467bca11a.webp", "pdfs": [{"url": "https://medical.asahi-intecc.com/sites/default/files/2026-03/Peripheral%2BGuide%2BWire%2BAMK-DT724%2BVer.1.00%20%282%29.pdf", "path": "assets/documento-cbaa5470ddc4.pdf", "name": "IFU guías periféricas Asahi · multilingüe", "label": "IFU guías periféricas Asahi · multilingüe"}], "source": "https://academiayumyeong.com/alfacor/product/astato-xs-40/", "quickType": "Guía de alta penetración", "quickSpecs": [["Carga de punta", "40 gf"], ["Modelo", "XS 40"], ["Diámetro", "0.014″"], ["Longitudes XS 40", "200 / 300 cm"], ["Punta", "Cónica; extremo sin recubrimiento"]], "tipLoad": 40, "useCase": "Cruce de oclusiones periféricas muy resistentes dentro de una estrategia de escalamiento de guías.", "officialSource": "https://medical.asahi-intecc.com/en/products-peripheral/astato-xs-20-xs-40.html", "asahiGroup": "guides", "guideGroup": "cto"}, {"id": 644, "slug": "conquest-pro-12", "name": "Conquest Pro 12", "specialty": "cardio-intervencion", "categories": [{"slug": "coronario", "name": "Coronario"}, {"slug": "cto", "name": "CTO"}, {"slug": "guias", "name": "Guías"}, {"slug": "asahi-guides", "name": "Guías Asahi"}], "category": "CTO", "brand": "Asahi Intecc", "summary": "Alambre guía coronario de extrema penetración, diseñado específicamente con una alta carga de punta de 12gf para intervenciones en Oclusiones Totales Crónicas (CTO). Su perfil cónico ultrafino permite perforar mecánicamente las placas más calcificadas y resistentes del endotelio vascular con precisión milimétrica.", "content": "<p>La guía ASAHI Conquest Pro 12 (comercializada también como Confianza Pro 12) es el estándar de oro en cardiología intervencionista para el abordaje de Oclusiones Totales Crónicas (CTO) severamente calcificadas. Cuando los alambres de soporte intermedio no logran cruzar la lesión, este dispositivo entra en acción gracias a su diseño de fuerza concentrada y alta rigidez.</p>\n<p>Su arquitectura biomecánica se basa en un núcleo de acero de alta tensión y una punta cónica que se reduce de 0.014 a 0.009 pulgadas. Al combinar este perfil afilado con una carga de punta exacta de 12 gramos-fuerza (12gf), la Conquest Pro 12 actúa como una herramienta de micro-perforación mecánica. El operador puede aplicar una fuerza de empuje significativa sabiendo que la guía mantendrá su rectitud y no colapsará, permitiendo un cruce directo y controlado a través de tejidos fibróticos o placas oclusivas de altísima densidad.</p>\n<h3>Beneficios y Características:</h3>\n<ul>\n<li>\n<p><b>Carga de Punta de 12gf:</b> Proporciona un altísimo nivel de soporte y fuerza de penetración (12 gramos-fuerza), calibrado específicamente para atravesar oclusiones calcificadas que resisten a otras guías de menor gramaje.</p>\n</li>\n<li>\n<p><b>Punta Cónica de 0.009″:</b> Su extremo distal se afila desde 0.014″ hasta 0.009″ (0.23 mm), maximizando la presión focal ejercida sobre la placa para facilitar la perforación mecánica directa.</p>\n</li>\n<li>\n<p><b>Núcleo de Alta Retención:</b> Su construcción interna garantiza una excelente transmisión del torque y una retención de forma superior, evitando el prolapso o la deformación del alambre al aplicar presión extrema contra la oclusión.</p>\n</li>\n<li>\n<p><b>Recubrimiento Estratégico:</b> El cuerpo principal cuenta con lubricidad para un deslizamiento intravascular óptimo, mientras que la punta distal carece de recubrimiento (uncoated) para anclarse firmemente en la lesión sin resbalar hacia el espacio subintimal.</p>\n</li>\n<li>\n<p><b>Control Táctil Directo:</b> La rigidez de su eje y la ausencia de polímeros en la punta brindan al especialista una retroalimentación táctil inmediata y sumamente precisa sobre la dureza del tejido que se está perforando.</p>\n</li>\n</ul>\n", "image": "assets/286e845467bca11a.webp", "pdfs": [{"url": "https://medical.asahi-intecc.com/sites/default/files/2024-11/ASAHI%2BConquest%2BPro%2BConfianza%2BPro%2BPCI%2BGuide%2BWire%2BAMK-DT710%2BVer.1.00_0.pdf", "path": "assets/documento-8c397a6774cb.pdf", "name": "IFU Conquest Pro / Confianza Pro · multilingüe", "label": "IFU Conquest Pro / Confianza Pro · multilingüe"}], "source": "https://academiayumyeong.com/alfacor/product/conquest-pro-12/", "quickType": "Guía CTO de penetración", "quickSpecs": [["Carga de punta", "12 gf"], ["Diámetro", "0.014″; punta de 0.009″"], ["Punta", "Cónica, extremo sin recubrimiento"], ["Núcleo", "Acero"]], "tipLoad": 12, "useCase": "CTO coronarias con segmentos duros o calcificados que requieren penetración focal y control de la punta.", "officialSource": "https://medical.asahi-intecc.com/en/products-coronary/asahi-conquest-pro-confianza-pro-series.html", "asahiGroup": "guides", "guideGroup": "cto"}, {"id": 642, "slug": "conquest-pro", "name": "Conquest Pro", "specialty": "cardio-intervencion", "categories": [{"slug": "coronario", "name": "Coronario"}, {"slug": "cto", "name": "CTO"}, {"slug": "guias", "name": "Guías"}, {"slug": "asahi-guides", "name": "Guías Asahi"}], "category": "CTO", "brand": "Asahi Intecc", "summary": "Alambre guía coronario de alta especialidad diseñado con una fuerza de penetración excepcional.  Su arquitectura de punta cónica y alto soporte está optimizada para atravesar lesiones complejas, oclusiones totales crónicas (CTO) con calcificaciones pesadas y tejidos fibrosos extremadamente duros.", "content": "<p>La guía ASAHI Conquest Pro representa una de las herramientas de penetración más potentes y resolutivas dentro del portafolio de Asahi Intecc. Diseñada específicamente para los escenarios clínicos más hostiles, esta guía se diferencia por su capacidad de ejercer una fuerza de empuje superior sin perder estabilidad ni rectitud direccional.</p>\n<p>Su diseño biomecánico se centra en una punta cónica (tapered tip) que reduce su diámetro de 0.014″ a 0.009″. Esta transición permite concentrar toda la fuerza de avance en un micro-punto, actuando como un taladro de precisión para perforar placas densamente calcificadas donde otras guías colapsan o se desvían. Para asegurar que esta extrema fuerza no comprometa el control, el extremo distal se mantiene intencionalmente libre de recubrimiento, mientras que el resto del cuerpo cuenta con un revestimiento hidrofílico que mitiga la fricción intravascular.</p>\n<h3>Beneficios y Características:</h3>\n<ul>\n<li>\n<p><b>Fuerza de Penetración Extrema:</b> Diseñada específicamente para cruzar oclusiones crónicas que presentan resistencia máxima debido a calcificaciones severas o tejido fibroso endurecido.</p>\n</li>\n<li>\n<p><b>Punta Cónica de 0.009″:</b> Su extremo distal se afina hasta las 0.009 pulgadas (0.23 mm), lo que maximiza la presión de contacto punto a punto y facilita la perforación mecánica directa de la placa ocluyente.</p>\n</li>\n<li>\n<p><b>Opciones de Alta Carga (Tip Load):</b> Está disponible en variantes de altísimo soporte, incluyendo modelos con cargas de punta de 9gf, 12gf y hasta 20gf, permitiendo al operador escalar la fuerza según la dureza y resistencia de la lesión anatómica.</p>\n</li>\n<li>\n<p><b>Extremo Distal sin Recubrir:</b> Presenta un recubrimiento hidrofílico a lo largo de su estructura para un deslizamiento suave, pero mantiene la punta distal esférica sin recubrir (Uncoated Ball Tip) para garantizar un agarre táctil preciso en la lesión y evitar deslizamientos subintimales indeseados.</p>\n</li>\n<li>\n<p><b>Alta Retención de Rectitud:</b> Su núcleo avanzado proporciona una rigidez y rectitud excepcionales, asegurando que la fuerza aplicada desde las manos del médico se transmita a la punta sin que el cuerpo de la guía sufra prolapsos.</p>\n</li>\n</ul>\n", "image": "assets/286e845467bca11a.webp", "pdfs": [{"url": "https://medical.asahi-intecc.com/sites/default/files/2024-11/ASAHI%2BConquest%2BPro%2BConfianza%2BPro%2BPCI%2BGuide%2BWire%2BAMK-DT710%2BVer.1.00_0.pdf", "path": "assets/documento-8c397a6774cb.pdf", "name": "IFU Conquest Pro / Confianza Pro · multilingüe", "label": "IFU Conquest Pro / Confianza Pro · multilingüe"}], "source": "https://academiayumyeong.com/alfacor/product/conquest-pro/", "quickType": "Guía CTO de penetración", "quickSpecs": [["Carga de punta", "9 gf"], ["Diámetro", "0.014″; punta de 0.009″"], ["Punta", "Cónica"], ["Extremo distal", "Sin recubrimiento"], ["Modelo", "Conquest Pro estándar; Pro 12 en ficha separada"]], "tipLoad": 9, "useCase": "CTO coronarias resistentes que requieren una punta cónica de penetración. Pro estándar: 9 gf; Pro 12: 12 gf.", "officialSource": "https://medical.asahi-intecc.com/en/products-coronary/asahi-conquest-pro-confianza-pro-series.html", "asahiGroup": "guides", "guideGroup": "cto"}, {"id": 640, "slug": "gladius-mg14", "name": "Gladius MG14", "specialty": "cardio-intervencion", "categories": [{"slug": "coronario", "name": "Coronario"}, {"slug": "cto", "name": "CTO"}, {"slug": "guias", "name": "Guías"}, {"slug": "asahi-guides", "name": "Guías Asahi"}], "category": "CTO", "brand": "Asahi Intecc", "summary": "Alambre guía de alto rendimiento diseñado para avanzar en intervenciones periféricas complejas.  Su estructura cuenta con un núcleo distal modificado y tecnología de envoltura de polímero, optimizando la capacidad de cruce en lesiones ocluidas prolongadas mediante la formación de un bucle estrecho (narrow loop) seguro y controlado.", "content": "<p>La serie de guías ASAHI Gladius MG14 PV y MG14 PV ES representa una solución avanzada para los desafíos de la revascularización periférica. A diferencia de las guías coronarias, este dispositivo está calibrado para soportar las exigencias biomecánicas de los vasos periféricos, permitiendo al especialista avanzar con seguridad a través de oclusiones crónicas y tejidos altamente resistentes.</p>\n<p>La innovación principal de este modelo radica en su núcleo distal modificado que incorpora un «microespacio» (Micro Gap). Esta arquitectura interna permite que, al enfrentar resistencia, la guía forme intencionalmente un bucle estrecho. Este mecanismo reduce la resistencia frontal de la lesión y asegura un avance suave, evitando una de las complicaciones más comunes en la periferia: la expansión o daño del espacio subintimal. En conjunto con su tecnología ACT ONE, el dispositivo asegura que el operador mantenga el dominio total del trayecto.</p>\n<h3>Beneficios y Características:</h3>\n<ul>\n<li>\n<p><b>Tecnología de Bucle Estrecho (Micro Gap):</b> Su diseño de núcleo distal modificado facilita la creación de un bucle estrecho, minimizando la resistencia del tejido calcificado y previniendo la disección indeseada del espacio subintimal.</p>\n</li>\n<li>\n<p><b>Lubricidad de Larga Duración:</b> Integra una envoltura de polímero combinada con un recubrimiento hidrofílico (Polymer + Hydrophilic), garantizando un deslizamiento sostenido y continuo al cruzar oclusiones de gran longitud.</p>\n</li>\n<li>\n<p><b>Punta Mini Premoldeada (Mini Pre-shape):</b> Su extremo distal presenta un moldeado preciso que puede ser adaptado a curvas de mayor tamaño según las necesidades del procedimiento, destacando por su altísima capacidad de retención de forma.</p>\n</li>\n<li>\n<p><b>Control Direccional ACT ONE:</b> Construida sobre la tecnología de bobina multifilar ACT ONE, que optimiza la transmisión de la fuerza de torsión, la durabilidad y la rigidez de la guía durante intervenciones hostiles.</p>\n</li>\n<li>\n<p><b>Especificaciones Periféricas Especializadas:</b> Presenta una firme carga de punta (Tip Load) de 3gf y está disponible en longitudes utilizables estratégicas de 190 cm, 235 cm y 300 cm, adaptándose a distintos abordajes vasculares.</p>\n</li>\n</ul>\n", "image": "assets/a1851017b3d46bcb.webp", "pdfs": [], "source": "https://academiayumyeong.com/alfacor/product/gladius-mg14/", "quickType": "Guía con polímero y tecnología Micro Gap", "quickSpecs": [["Carga de punta", "3 gf"], ["Plataforma", "Coronaria, 0.014″"], ["Recubrimiento", "Polímero + hidrofílico"], ["Núcleo", "ACT ONE"]], "tipLoad": 3, "useCase": "Cruce de CTO coronarias con recubrimiento polimérico y diseño Micro Gap para navegación en segmentos ocluidos.", "officialSource": "https://medical.asahi-intecc.com/en/products-coronary/asahi-gladius-mg.html", "asahiGroup": "guides", "guideGroup": "cto"}, {"id": 638, "slug": "rg3", "name": "RG3", "specialty": "cardio-intervencion", "categories": [{"slug": "coronario", "name": "Coronario"}, {"slug": "cto", "name": "CTO"}, {"slug": "guias", "name": "Guías"}, {"slug": "asahi-guides", "name": "Guías Asahi"}], "category": "CTO", "brand": "Asahi Intecc", "summary": "Alambre guía coronario de alta especialidad (Purpose Built Guidewire) diseñado de manera exclusiva para la maniobra de externalización durante procedimientos de oclusión total crónica (CTO) por vía retrógrada.  Destaca por su longitud excepcional de 330 cm y un perfil ultrafino que facilita el intercambio seguro de dispositivos.", "content": "<p>La guía ASAHI RG3 es una herramienta fundamental en las intervenciones coronarias percutáneas de máxima complejidad, específicamente concebida para la fase crítica de recanalización de Oclusiones Totales Crónicas (CTO) mediante técnica retrógrada. Su función no es navegar arterias nativas ni penetrar placas, sino servir como un riel de externalización ininterrumpido que conecta el acceso arterial anterógrado y retrógrado para establecer un circuito seguro de trabajo.</p>\n<p>Para cumplir esta delicada función, la RG3 presenta un diseño estructural único. Posee una longitud total de 330 cm y un diámetro uniformemente reducido de apenas 0.010 pulgadas, lo que permite avanzar y retirarla a través del lumen interno de los microcatéteres con suma facilidad. Además, incorpora un sistema de recubrimiento dual que optimiza el comportamiento del alambre: máxima lubricidad dentro de la anatomía del paciente y agarre firme en el segmento exterior.</p>\n<h3>Beneficios y Características:</h3>\n<ul>\n<li>\n<p><b>Diseño Exclusivo para Externalización:</b> Fabricada con un propósito específico, es el estándar de la industria para facilitar la externalización segura durante procedimientos CTO retrógrados.</p>\n</li>\n<li>\n<p><b>Longitud Extendida de 330 cm:</b> Su longitud de más de tres metros permite que el alambre recorra el cuerpo desde el acceso donante, cruce la oclusión y salga por el catéter guía opuesto sin perder longitud de trabajo.</p>\n</li>\n<li>\n<p><b>Perfil Ultrafino de 0.010″:</b> A diferencia de las guías de intervención estándar (0.014″), su diámetro de 0.010″ (0.26 mm) previene el roce extremo y facilita el paso a través de microcatéteres de bajo perfil.</p>\n</li>\n<li>\n<p><b>Recubrimiento Dual Estratégico:</b> Cuenta con 170 cm de recubrimiento hidrofílico distal para un deslizamiento fluido intravascular, y 160 cm de recubrimiento hidrofóbico proximal para asegurar el control táctil del cardiólogo.</p>\n</li>\n<li>\n<p><b>Carga de Punta de 3.0gf:</b> Presenta un Tip Load firme de 3.0gf acompañado de 3 cm de radiopacidad, proporcionando el soporte necesario para avanzar por el microcatéter guía de forma predecible y visible bajo rayos X.</p>\n</li>\n</ul>\n", "image": "assets/e3e5871bee13dff5.webp", "pdfs": [{"url": "https://asahi-inteccusa-medical.com/wp-content/uploads/2021/01/Asahi-14254-PTCA-GuideWiresBrochure-Trifold-FINAL-web.pdf", "path": "assets/documento-2e93d9406b11.pdf", "name": "Catálogo de guías coronarias Asahi · inglés", "label": "Catálogo de guías coronarias Asahi · inglés"}], "source": "https://academiayumyeong.com/alfacor/product/rg3/", "quickType": "Guía de externalización CTO", "quickSpecs": [["Carga de punta", "3 gf"], ["Diámetro", "0.010″"], ["Longitud", "330 cm"], ["Radiopacidad", "3 cm"], ["Recubrimiento hidrofílico", "170 cm distales"]], "tipLoad": 3, "useCase": "Externalización en procedimientos CTO retrógrados; su función principal es mantener una vía de trabajo larga.", "officialSource": "https://medical.asahi-intecc.com/en/products-coronary/asahi-rg3.html", "asahiGroup": "guides", "guideGroup": "retrograde"}, {"id": 636, "slug": "ultimatebros-3", "name": "ULTIMATEbros 3", "specialty": "cardio-intervencion", "categories": [{"slug": "coronario", "name": "Coronario"}, {"slug": "cto", "name": "CTO"}, {"slug": "guias", "name": "Guías"}, {"slug": "asahi-guides", "name": "Guías Asahi"}], "category": "CTO", "brand": "Asahi Intecc", "summary": "Alambre guía coronario de alta especialidad, diseñado específicamente para el tratamiento de Oclusiones Totales Crónicas (CTO) con morfología mixta. Su estructura combina una alta maniobrabilidad y una capacidad de moldeado fino, permitiendo optimizar la selectividad del vaso y reducir significativamente el riesgo de expansión de la luz falsa.", "content": "<p>La guía ULTIMATEbros 3 de Asahi Intecc es una herramienta esencial en el arsenal del cardiólogo intervencionista para abordar Oclusiones Totales Crónicas (CTO). A diferencia de las guías diseñadas puramente para penetración, este modelo destaca por su excepcional rendimiento en estenosis severas compuestas por morfologías mixtas (áreas alternas de tejido blando, fibroso y calcificado).</p>\n<p>El núcleo de su éxito clínico radica en su capacidad de retención de forma. Su punta está diseñada para permitir un «moldeado fino» (fine shaping) por parte del operador, lo que mejora drásticamente la selectividad al momento de navegar la lesión. Esto permite mantener el avance estrictamente dentro de la luz verdadera del vaso, mitigando uno de los mayores riesgos en PCI complejas: la creación o expansión de una falsa luz (false lumen). Además, su diseño integra un recubrimiento hidrofílico extendido que asegura una maniobrabilidad sostenida a lo largo de toda la intervención.</p>\n<h3>Beneficios y Características:</h3>\n<ul>\n<li>\n<p><b>Ideal para Morfologías Mixtas:</b> Su diseño estructural la convierte en la opción de elección (Good choice) para cruzar lesiones ocluidas que presentan variaciones en la densidad y composición del tejido.</p>\n</li>\n<li>\n<p><b>Moldeado Fino de Punta:</b> La estructura distal permite un moldeado preciso, lo que incrementa la selectividad direccional y previene la desviación del alambre hacia vías subintimales o falsas luces.</p>\n</li>\n<li>\n<p><b>Recubrimiento SLIP-COAT Extendido:</b> Incorpora 40 cm de recubrimiento hidrofílico de alto rendimiento, lo que garantiza una disminución de la fricción y mantiene una alta maniobrabilidad incluso dentro de las oclusiones más restrictivas.</p>\n</li>\n<li>\n<p><b>Punta Distal sin Recubrir (Uncoated):</b> Para asegurar el máximo nivel de retroalimentación táctil, la punta más distal del dispositivo se mantiene libre de recubrimiento, permitiendo al operador «sentir» la textura de la lesión en tiempo real.</p>\n</li>\n<li>\n<p><b>Radiopacidad Estratégica:</b> Cuenta con un segmento radiopaco de 11 cm (Spring Coil Length), brindando una excelente visibilidad bajo fluoroscopia para monitorear el avance y la posición exacta de la guía.</p>\n</li>\n</ul>\n", "image": "assets/e5cae3663e982ed9.webp", "pdfs": [{"url": "https://asahi-inteccusa-medical.com/wp-content/uploads/2021/01/Asahi-14254-PTCA-GuideWiresBrochure-Trifold-FINAL-web.pdf", "path": "assets/documento-2e93d9406b11.pdf", "name": "Catálogo de guías coronarias Asahi · inglés", "label": "Catálogo de guías coronarias Asahi · inglés"}], "source": "https://academiayumyeong.com/alfacor/product/ultimatebros-3/", "quickType": "Guía coronaria CTO", "quickSpecs": [["Carga de punta", "3 gf"], ["Recubrimiento", "SLIP-COAT, 40 cm"], ["Radiopacidad", "11 cm"], ["Punta distal", "Sin recubrimiento"], ["Punta", "Moldeable"]], "tipLoad": 3, "useCase": "Cruce de CTO de morfología ambigua, con una guía hidrofílica de carga intermedia y punta no cónica.", "officialSource": "https://medical.asahi-intecc.com/latam-es/node/902", "asahiGroup": "guides", "guideGroup": "cto"}, {"id": 634, "slug": "suoh-03", "name": "SUOH 03", "specialty": "cardio-intervencion", "categories": [{"slug": "coronario", "name": "Coronario"}, {"slug": "cto", "name": "CTO"}, {"slug": "guias", "name": "Guías"}, {"slug": "asahi-guides", "name": "Guías Asahi"}], "category": "CTO", "brand": "Asahi Intecc", "summary": "Alambre guía coronario de vanguardia diseñado con la carga de punta más suave del mercado (0.3gf).   Gracias a su excepcional flexibilidad, ofrece una capacidad de seguimiento (trackability) superior para navegar con seguridad a través de vasos colaterales frágiles y anatomías extremadamente tortuosas donde otros dispositivos fallan.", "content": "<p>La guía ASAHI SUOH 03 representa un avance fundamental en las herramientas para Intervenciones Coronarias Percutáneas (PCI) complejas. A diferencia de los alambres diseñados para penetración, este modelo prioriza la seguridad absoluta al interactuar con el endotelio vascular. Su rasgo más distintivo es su flexibilidad inigualable, contando con la carga de punta más baja de todo el portafolio de Asahi Intecc.</p>\n<p>Concebida como una guía «suave como la seda», la SUOH 03 permite rastrear trayectos anatómicos severamente angulados sin generar tensión contra las paredes arteriales. Esta cualidad minimiza drásticamente el riesgo de perforación al cruzar microcanales o vasos colaterales delicados. Además, su núcleo de acero inoxidable de alta tensión se complementa con un extenso recubrimiento hidrofílico que garantiza un avance fluido, atraumático y altamente predecible.</p>\n<h3>Beneficios y Características:</h3>\n<ul>\n<li>\n<p><b>La Carga de Punta Más Suave:</b> Cuenta con un Tip Load de tan solo 0.3gf, siendo la guía más suave de la línea ASAHI. Esto le otorga una flexibilidad y seguridad de punta sin precedentes.</p>\n</li>\n<li>\n<p><b>Seguimiento Excepcional en Colaterales:</b> Su estructura está específicamente diseñada para navegar a través de conductos tortuosos y redes colaterales frágiles en los que otros alambres estándar presentan resistencia o riesgo de daño.</p>\n</li>\n<li>\n<p><b>Recubrimiento SLIP-COAT Extendido:</b> Incorpora 52 cm de recubrimiento hidrofílico de alto rendimiento en su sección distal, asegurando una fricción ultra baja y un deslizamiento continuo durante todo el cruce anatómico.</p>\n</li>\n<li>\n<p><b>Transmisión de Torque 1:1:</b> A pesar de la extrema suavidad de su extremo distal, el diseño de su núcleo de alta tensión permite mantener una excelente capacidad de respuesta rotacional y un control direccional preciso.</p>\n</li>\n<li>\n<p><b>Especificaciones Modulares:</b> Disponible en el diámetro estándar de 0.014″ y en longitudes de 190 cm y 300 cm. El operador puede seleccionar entre una punta recta (Straight) o pre-formada (Pre-shape) según la anatomía del paciente.</p>\n</li>\n</ul>\n", "image": "assets/71136ccf137c2199.webp", "pdfs": [{"url": "https://medical.asahi-intecc.com/sites/default/files/2026-04/PCI%2BGuide%2BWire%2BSION%2Bseries%2B%2BAMK-DT768%2BVer.2.00.pdf", "path": "assets/documento-5fa57c259069.pdf", "name": "IFU serie SION y SUOH 03 · multilingüe", "label": "IFU serie SION y SUOH 03 · multilingüe"}], "source": "https://academiayumyeong.com/alfacor/product/suoh-03/", "quickType": "Guía para anatomías tortuosas y colaterales", "quickSpecs": [["Carga de punta", "0.3 gf"], ["Diámetro", "0.014″"], ["Longitudes", "190 / 300 cm"], ["Recubrimiento", "Hidrofílico, 52 cm"]], "tipLoad": 0.3, "useCase": "Navegación por trayectos muy tortuosos y colaterales, cuando se requiere una punta de gran flexibilidad.", "officialSource": "https://medical.asahi-intecc.com/en/products-coronary/suoh-03.html", "asahiGroup": "guides", "guideGroup": "retrograde"}, {"id": 633, "slug": "gaia-next-3", "name": "Gaia Next 3", "specialty": "cardio-intervencion", "categories": [{"slug": "coronario", "name": "Coronario"}, {"slug": "cto", "name": "CTO"}, {"slug": "guias", "name": "Guías"}, {"slug": "asahi-guides", "name": "Guías Asahi"}], "category": "CTO", "brand": "Asahi Intecc", "summary": "Alambre guía coronario de alta especialidad diseñado para el tratamiento de Oclusiones Totales Crónicas (CTO) severas. Como el modelo de mayor penetración de la serie, cuenta con una carga de punta firme y tecnología de bobina XTRAND para lograr un avance seguro y controlado en lesiones altamente calcificadas.", "content": "<p>La guía ASAHI Gaia Next 3 es la culminación tecnológica de Asahi Intecc para el «cableado intencional» (intentional wiring) en intervenciones coronarias de máxima complejidad. Este dispositivo está estructurado específicamente para enfrentar Oclusiones Totales Crónicas (CTO) donde la resistencia del tejido exige el más alto nivel de fuerza y soporte proximal, superando las capacidades de los modelos Next 1 y Next 2.</p>\n<p>El núcleo de su eficacia radica en la integración de la bobina hueca de múltiples hilos XTRAND y la tecnología ACT ONE. Esta sinergia otorga a la guía una maniobrabilidad excepcional y un torque de 1:1, permitiendo una transmisión de fuerza directa desde las manos del cardiólogo hasta la punta. Además, su diseño maximiza el poder anti-atrapamiento (anti-trapping), reduciendo drásticamente el riesgo de fracturas o daños estructurales en el alambre, incluso al enfrentarse a lesiones severas y complejas.</p>\n<h3>Beneficios y Características:</h3>\n<ul>\n<li>\n<p><b>Máxima Fuerza de Penetración:</b> Es el modelo de la serie con la mayor carga de punta (6.0gf), proporcionando el empuje y la firmeza necesarios para penetrar las capas de tejido ocluido más densas y calcificadas.</p>\n</li>\n<li>\n<p><b>Tecnología XTRAND Anti-Atrapamiento:</b> Su innovadora bobina trenzada aumenta significativamente la flexibilidad transversal y la resistencia, evitando roturas o elongaciones si la punta queda atrapada en la lesión.</p>\n</li>\n<li>\n<p><b>Control de Torque Definitivo:</b> El núcleo avanzado ACT ONE asegura que la maniobrabilidad se mantenga intacta, logrando un control direccional absoluto y preciso en el cuerpo de la oclusión.</p>\n</li>\n<li>\n<p><b>Punta Pre-formada (Pre-shape):</b> Su extremo distal cuenta con un diseño de micro-cono pre-formado de 1 mm, el cual optimiza la selectividad y facilita el ingreso a microcanales o tractos anatómicos desafiantes.</p>\n</li>\n<li>\n<p><b>Deslizamiento Estratégico:</b> Posee un recubrimiento hidrofílico (SLIP-COAT) a lo largo de 40 cm para minimizar la fricción en el vaso, manteniendo la punta distal sin recubrir para preservar la retroalimentación táctil directa.</p>\n</li>\n</ul>\n", "image": "assets/0bc562991e9dba1b.webp", "pdfs": [{"url": "https://medical.asahi-intecc.com/sites/default/files/2024-08/ASAHI%2BGaia%2BNext%2BPCI%2BGuide%2BWire%2BAMK-DT544%2BVer.2.00.pdf", "path": "assets/documento-90db415aca2d.pdf", "name": "IFU Gaia Next · multilingüe", "label": "IFU Gaia Next · multilingüe"}], "source": "https://academiayumyeong.com/alfacor/product/gaia-next-3/", "quickType": "Guía coronaria CTO direccional", "quickSpecs": [["Carga de punta", "6 gf"], ["Punta", "Preformada, 1 mm"], ["Tecnología", "ACT ONE + XTRAND"], ["Recubrimiento", "Hidrofílico, 40 cm; extremo sin recubrir"]], "tipLoad": 6, "useCase": "CTO coronarias que requieren control direccional y mayor carga de punta dentro de la serie Gaia Next.", "officialSource": "https://medical.asahi-intecc.com/latam-es/products-coronary/asahi-gaia-next.html", "asahiGroup": "guides", "guideGroup": "cto"}, {"id": 632, "slug": "gaia-next-1", "name": "Gaia Next 1", "specialty": "cardio-intervencion", "categories": [{"slug": "coronario", "name": "Coronario"}, {"slug": "cto", "name": "CTO"}, {"slug": "guias", "name": "Guías"}, {"slug": "asahi-guides", "name": "Guías Asahi"}], "category": "CTO", "brand": "Asahi Intecc", "summary": "Alambre guía coronario de alta especialidad diseñado para Oclusiones Totales Crónicas (CTO) mediante la técnica de cableado intencional (intentional wiring). Como el modelo de entrada de su familia, combina una carga de punta suave de 2.0gf con las tecnologías XTRAND y ACT ONE, garantizando un control direccional excepcional y una inserción segura.", "content": "<p>La guía ASAHI Gaia Next 1 es el primer escalón dentro de la serie más avanzada de Asahi Intecc para intervenciones en Oclusiones Totales Crónicas (CTO). Está estructurada bajo el concepto de «cableado intencional», otorgando al cardiólogo intervencionista la capacidad de dirigir y navegar activamente a través del cuerpo de la oclusión en lugar de depender únicamente del avance pasivo.</p>\n<p>Este modelo se caracteriza por tener la carga de punta más suave de la serie (2.0gf) y el perfil distal más fino (0.011″). Esto lo convierte en la herramienta ideal para iniciar el abordaje de la placa ocluyente con un alto grado de sensibilidad y seguridad táctil. Al igual que sus versiones de mayor soporte, integra el núcleo ACT ONE para una transmisión de torque exacta de 1:1 y la innovadora bobina trenzada XTRAND, que proporciona un poder anti-atrapamiento superior y protege el dispositivo frente a fracturas en lesiones calcificadas.</p>\n<h3>Beneficios y Características:</h3>\n<ul>\n<li>\n<p><b>El Perfil Más Fino de la Serie:</b> Cuenta con una punta pre-formada en micro-cono que se reduce a 0.011″ (0.27 mm) en su extremo distal, facilitando el ingreso inicial en la lesión con una flexibilidad superior al resto de la familia.</p>\n</li>\n<li>\n<p><b>Carga de Punta de 2.0gf:</b> Proporciona un soporte de penetración inicial de 2.0gf, el nivel exacto para un primer acercamiento a la Oclusión Total Crónica con el mínimo trauma vascular.</p>\n</li>\n<li>\n<p><b>Tecnología XTRAND Anti-Atrapamiento:</b> Su estructura de bobina de múltiples hilos maximiza la resistencia a la elongación y al daño estructural, evitando de forma proactiva que la punta quede atrapada en el tejido duro.</p>\n</li>\n<li>\n<p><b>Control Direccional 1:1:</b> Gracias a la tecnología de núcleo ACT ONE, el operador experimenta una respuesta de torque inmediata y directa para manipular la dirección de la guía con total precisión milimétrica.</p>\n</li>\n<li>\n<p><b>Sensación Táctil Optimizada:</b> Incorpora 40 cm de recubrimiento hidrofílico para reducir la fricción en el vaso, pero mantiene la punta distal intencionalmente libre de recubrimiento (uncoated) para preservar al 100% la retroalimentación táctil directa.</p>\n</li>\n</ul>\n", "image": "assets/0bc562991e9dba1b.webp", "pdfs": [{"url": "https://medical.asahi-intecc.com/sites/default/files/2024-08/ASAHI%2BGaia%2BNext%2BPCI%2BGuide%2BWire%2BAMK-DT544%2BVer.2.00.pdf", "path": "assets/documento-90db415aca2d.pdf", "name": "IFU Gaia Next · multilingüe", "label": "IFU Gaia Next · multilingüe"}], "source": "https://academiayumyeong.com/alfacor/product/gaia-next-1/", "quickType": "Guía coronaria CTO direccional", "quickSpecs": [["Carga de punta", "2 gf"], ["Punta distal", "0.011″, preformada"], ["Tecnología", "ACT ONE + XTRAND"], ["Recubrimiento", "Hidrofílico, 40 cm; extremo sin recubrir"]], "tipLoad": 2, "useCase": "CTO coronarias que requieren control direccional con la punta más fina y menor carga de la serie Gaia Next.", "officialSource": "https://medical.asahi-intecc.com/latam-es/products-coronary/asahi-gaia-next.html", "asahiGroup": "guides", "guideGroup": "cto"}, {"id": 630, "slug": "gaia-next-2", "name": "Gaia Next 2", "specialty": "cardio-intervencion", "categories": [{"slug": "coronario", "name": "Coronario"}, {"slug": "cto", "name": "CTO"}, {"slug": "guias", "name": "Guías"}, {"slug": "asahi-guides", "name": "Guías Asahi"}], "category": "CTO", "brand": "Asahi Intecc", "summary": "Alambre guía coronario de alta especialidad diseñado para el tratamiento de Oclusiones Totales Crónicas (CTO) mediante técnicas de cableado intencional (intentional wiring).   Incorpora una punta de micro-cono y la innovadora bobina XTRAND para maximizar el control direccional y el poder anti-atrapamiento en lesiones complejas.", "content": "<p>La guía ASAHI Gaia Next 2 representa una evolución significativa en las intervenciones coronarias percutáneas complejas. Este dispositivo está diseñado específicamente para otorgar al cardiólogo intervencionista un control direccional superior dentro del cuerpo de la oclusión. Su arquitectura interna se basa en la tecnología ACT ONE, la cual garantiza una respuesta de torque exacta de 1:1, permitiendo manipular la punta con precisión milimétrica durante el procedimiento.</p>\n<p>El avance más destacado de esta serie es la incorporación de la bobina XTRAND. Esta estructura de múltiples hilos trenzados aumenta drásticamente la resistencia a la tensión y otorga una alta flexibilidad transversal. Esto se traduce en un mayor poder anti-atrapamiento (anti-trapping), evitando fracturas o daños en la guía incluso cuando la punta queda atrapada en tejido endovascular altamente calcificado. El modelo Next 2 ofrece un equilibrio ideal de fuerza con una carga de punta calibrada a 4.0gf.</p>\n<h3>Beneficios y Características:</h3>\n<ul>\n<li>\n<p><b>Navegación Intencional en CTO:</b> Su diseño está optimizado para el «cableado intencional», brindando al operador la capacidad de dirigir activamente la guía a través de las oclusiones totales crónicas.</p>\n</li>\n<li>\n<p><b>Bobina XTRAND Anti-Atrapamiento:</b> Integra una bobina hueca formada por múltiples hilos que previene la elongación longitudinal, evita fracturas y aumenta significativamente el poder anti-atrapamiento en lesiones duras.</p>\n</li>\n<li>\n<p><b>Control de Torque 1:1 (ACT ONE):</b> El uso de la tecnología de núcleo ACT ONE asegura que la transmisión del torque sea directa e inmediata, logrando un control táctil excepcional.</p>\n</li>\n<li>\n<p><b>Punta de Micro-Cono Pre-formada:</b> Cuenta con una punta en forma de micro-cono (con un diámetro que va de 0.012″ a 0.014″) y un diseño pre-formado (Pre-shape), lo que mejora considerablemente la selectividad y la penetrabilidad en el tejido.</p>\n</li>\n<li>\n<p><b>Fuerza y Lubricidad Estratégica:</b> Ofrece una firme carga de punta de 4.0gf. Además, cuenta con un recubrimiento hidrofílico de 40 cm de longitud, dejando intencionalmente la punta distal sin recubrimiento para mantener la máxima sensación táctil.</p>\n\n<p> </li>\n</ul>\n", "image": "assets/0bc562991e9dba1b.webp", "pdfs": [{"url": "https://medical.asahi-intecc.com/sites/default/files/2024-08/ASAHI%2BGaia%2BNext%2BPCI%2BGuide%2BWire%2BAMK-DT544%2BVer.2.00.pdf", "path": "assets/documento-90db415aca2d.pdf", "name": "IFU Gaia Next · multilingüe", "label": "IFU Gaia Next · multilingüe"}], "source": "https://academiayumyeong.com/alfacor/product/gaia-next-2/", "quickType": "Guía coronaria CTO direccional", "quickSpecs": [["Carga de punta", "4 gf"], ["Diámetro", "0.014″; punta de 0.012″"], ["Tecnología", "ACT ONE + XTRAND"], ["Recubrimiento", "Hidrofílico, 40 cm; extremo sin recubrir"]], "tipLoad": 4, "useCase": "CTO coronarias donde se busca control direccional con una carga intermedia dentro de la serie Gaia Next.", "officialSource": "https://medical.asahi-intecc.com/latam-es/products-coronary/asahi-gaia-next.html", "asahiGroup": "guides", "guideGroup": "cto"}, {"id": 629, "slug": "fielder-xt-r", "name": "Fielder XT-R", "specialty": "cardio-intervencion", "categories": [{"slug": "coronario", "name": "Coronario"}, {"slug": "cto", "name": "CTO"}, {"slug": "guias", "name": "Guías"}, {"slug": "asahi-guides", "name": "Guías Asahi"}], "category": "CTO", "brand": "Asahi Intecc", "summary": "Alambre guía coronario especializado (Purpose Built), diseñado para el tratamiento de Oclusiones Totales Crónicas (CTO). Su estructura combina una punta cónica de bajo perfil, una carga de punta suave y un recubrimiento altamente lubricante, haciéndola la opción ideal para el seguimiento y navegación a través de microcanales complejos.", "content": "<p>La guía Fielder XT-R de Asahi Intecc es una herramienta coronaria diseñada con un propósito específico (Purpose Built Guidewire) dentro de las intervenciones de alta complejidad. Su campo de acción principal se encuentra en los procedimientos de recanalización de Oclusiones Totales Crónicas (CTO), donde el seguimiento de pequeños tractos vasculares es esencial.</p>\n<p>Este dispositivo está estructurado para maximizar la navegación en microcanales. Para lograr esto, combina un perfil distal cónico (tapered) que reduce su diámetro a 0.010″, con una carga de punta considerablemente baja. Esta sinergia, apoyada por una envoltura de polímero y un recubrimiento hidrofílico, permite que la guía encuentre y siga la ruta de menor resistencia dentro de la oclusión, minimizando el riesgo de disecciones y optimizando el cruce atraumático de la lesión.</p>\n<h3>Beneficios y Características:</h3>\n<ul>\n<li>\n<p><b>Seguimiento de Microcanales:</b> Es la guía de elección (Good choice) para el seguimiento de microcanales dentro de las oclusiones, gracias a la combinación precisa de su punta cónica, su baja carga y su extrema lubricidad.</p>\n</li>\n<li>\n<p><b>Punta Cónica de 0.010″:</b> Su diseño distal se afina hasta los 0.010″ (0.26 mm), lo que facilita el ingreso y la navegación por tractos intralesionales extremadamente estrechos.</p>\n</li>\n<li>\n<p><b>Recubrimiento Híbrido Avanzado:</b> Incorpora una cubierta de polímero (Polymer Jacket) combinada con un recubrimiento hidrofílico (Hydrophilic coating) que se extiende por los 17 cm más distales, garantizando una fricción mínima durante el avance.</p>\n</li>\n<li>\n<p><b>Radiopacidad Extendida:</b> Cuenta con un segmento radiopaco de 16 cm de longitud, lo que permite al cardiólogo intervencionista mantener una visualización constante y clara del comportamiento de la guía bajo fluoroscopia.</p>\n</li>\n<li>\n<p><b>Configuraciones de Longitud:</b> Está disponible en la longitud estándar de 190 cm y en una versión extendida de 300 cm, adaptándose a diversas técnicas operativas y necesidades de intercambio de dispositivos.</p>\n</li>\n</ul>\n", "image": "assets/13b36e80dc80a80b.webp", "pdfs": [{"url": "https://asahi-inteccusa-medical.com/wp-content/uploads/2021/01/Asahi-14254-PTCA-GuideWiresBrochure-Trifold-FINAL-web.pdf", "path": "assets/documento-2e93d9406b11.pdf", "name": "Catálogo de guías coronarias Asahi · inglés", "label": "Catálogo de guías coronarias Asahi · inglés"}], "source": "https://academiayumyeong.com/alfacor/product/fielder-xt-r/", "quickType": "Guía CTO para seguimiento de microcanales", "quickSpecs": [["Carga de punta", "0.6 gf"], ["Punta distal", "0.010″"], ["Longitudes", "190 / 300 cm"], ["Recubrimiento", "Polímero + hidrofílico, 17 cm"], ["Radiopacidad", "16 cm"]], "tipLoad": 0.6, "useCase": "Seguimiento de microcanales en CTO; punta cónica suave con polímero para avanzar por trayectos estrechos.", "officialSource": "https://medical.asahi-intecc.com/latam-es/products-coronary/fielder-xt-axt-r.html", "asahiGroup": "guides", "guideGroup": "cto"}, {"id": 626, "slug": "fielder-xt-a", "name": "Fielder XT-A", "specialty": "cardio-intervencion", "categories": [{"slug": "coronario", "name": "Coronario"}, {"slug": "cto", "name": "CTO"}, {"slug": "guias", "name": "Guías"}, {"slug": "asahi-guides", "name": "Guías Asahi"}], "category": "CTO", "brand": "Asahi Intecc", "summary": "Alambre guía coronario de alta especialidad diseñado para el tratamiento de Oclusiones Totales Crónicas (CTO). Gracias a la combinación de su punta cónica (tapered) y su flexibilidad estructurada, es la opción ideal para lograr una penetración controlada en capas proximales ocluidas.", "content": "<p>El alambre guía Fielder XT-A de Asahi Intecc es una herramienta avanzada indispensable para procedimientos de recanalización en Oclusiones Totales Crónicas (CTO). Diseñado para superar estenosis severas donde las guías de primera línea no pueden avanzar, este dispositivo basa su éxito en un perfil de cruce ultra bajo y una estructura de alta respuesta.</p>\n<p>El núcleo de su diseño radica en su punta cónica, que se reduce hasta un diámetro de 0.010″, permitiendo al cardiólogo intervencionista encontrar microcanales e ingresar a la lesión con extrema precisión. A su vez, el cuerpo de la guía se encuentra recubierto por una envoltura de polímero y un revestimiento hidrofílico de alto rendimiento, lo que garantiza una disminución casi total de la fricción. El equilibrio exacto entre su carga de punta y su transmisión de torque permite mejorar la cruzabilidad (crossability) incluso en aquellas lesiones ocluidas que carecen de un muñón (stump) evidente.</p>\n<h3>Beneficios y Características:</h3>\n<ul>\n<li>\n<p><b>Diseño de Punta Cónica:</b> Cuenta con un perfil cónico (tapered) que reduce el diámetro distal a 0.010″, optimizando su capacidad para navegar canales estrechos y penetrar lesiones ocluidas con alta efectividad.</p>\n</li>\n<li>\n<p><b>Carga de Punta de 1.0gf:</b> Presenta una carga de punta (Tip Load) controlada de 1.0gf, la cual proporciona la fuerza de penetración exacta para cruzar el tejido fibroso de las Oclusiones Totales Crónicas sin sacrificar seguridad.</p>\n</li>\n<li>\n<p><b>Recubrimiento de Alta Lubricidad:</b> Integra una envoltura de polímero junto con un tratamiento hidrofílico (Polymer + Hydrophilic) que se extiende por los 17 cm más distales, facilitando un deslizamiento superior a través del vaso.</p>\n</li>\n<li>\n<p><b>Visibilidad Radiopaca Extendida:</b> Posee un segmento radiopaco excepcionalmente largo de 16 cm, proporcionando un contraste visual profundo y continuo bajo fluoroscopia para asegurar el avance seguro del dispositivo.</p>\n</li>\n<li>\n<p><b>Transmisión de Torque y Control:</b> Su arquitectura interna está diseñada para otorgar una maniobrabilidad excepcional, permitiendo que el torque y el control mejoren sustancialmente el cruce en lesiones extremadamente complejas.</p>\n</li>\n</ul>\n", "image": "assets/13b36e80dc80a80b.webp", "pdfs": [{"url": "https://asahi-inteccusa-medical.com/wp-content/uploads/2021/01/Asahi-14254-PTCA-GuideWiresBrochure-Trifold-FINAL-web.pdf", "path": "assets/documento-2e93d9406b11.pdf", "name": "Catálogo de guías coronarias Asahi · inglés", "label": "Catálogo de guías coronarias Asahi · inglés"}], "source": "https://academiayumyeong.com/alfacor/product/fielder-xt-a/", "quickType": "Guía CTO con polímero", "quickSpecs": [["Carga de punta", "1 gf"], ["Punta distal", "0.010″"], ["Recubrimiento", "Polímero + hidrofílico, 17 cm"], ["Radiopacidad", "16 cm"]], "tipLoad": 1, "useCase": "Cruce de CTO y seguimiento de microcanales, con mayor carga de punta que XT-R.", "officialSource": "https://medical.asahi-intecc.com/latam-es/products-coronary/fielder-xt-axt-r.html", "asahiGroup": "guides", "guideGroup": "cto"}, {"id": 624, "slug": "fielder", "name": "Fielder", "specialty": "cardio-intervencion", "categories": [{"slug": "caballito-batalla", "name": "Caballito Batalla"}, {"slug": "coronario", "name": "Coronario"}, {"slug": "guias", "name": "Guías"}, {"slug": "asahi-guides", "name": "Guías Asahi"}], "category": "Caballito Batalla", "brand": "Asahi Intecc", "summary": "Alambre guía coronario de primera línea (frontline) equipado con envoltura de polímero. Su diseño avanzado está estructurado para proporcionar un deslizamiento excepcional y una alta capacidad de seguimiento (trackability) durante el cruce de lesiones coronarias.", "content": "<p>La guía coronaria Fielder de Asahi Intecc es una herramienta de primera línea reconocida por su notable capacidad de navegación en intervenciones percutáneas. Su arquitectura se centra en reducir drásticamente la resistencia y la fricción dentro del lecho vascular, logrando esto a través de una avanzada envoltura de polímero combinada con un recubrimiento hidrofílico de alto rendimiento.</p>\n<p>Con un diámetro exterior estándar de 0.014″, esta guía ofrece al cardiólogo intervencionista una respuesta táctil equilibrada y un avance fluido. Su estructura permite que el dispositivo se adapte suavemente a la tortuosidad anatómica, asegurando que el especialista mantenga el control direccional mientras cruza estenosis desafiantes con el mínimo trauma para la pared arterial.</p>\n<h3>Beneficios y Características:</h3>\n<ul>\n<li>\n<p><b>Deslizamiento Superior:</b> Integra una envoltura de polímero junto con un recubrimiento hidrofílico (Polymer + Hydrophilic), lo que garantiza un rendimiento avanzado y una fricción ultra baja al contacto con la sangre.</p>\n</li>\n<li>\n<p><b>Recubrimiento Distal Estratégico:</b> El tratamiento hidrofílico y polimérico cubre exactamente los 22 cm más distales de la guía, optimizando la capacidad de cruce en el segmento más crítico de la intervención.</p>\n</li>\n<li>\n<p><b>Capacidad de Seguimiento (Trackability):</b> Su diseño interno está calibrado para adaptarse fácilmente a las curvas del vaso, asegurando un avance rápido y seguro hasta el sitio de la lesión.</p>\n</li>\n<li>\n<p><b>Fuerza de Penetración Equilibrada:</b> Cuenta con una carga de punta (Tip Load) de 1gf y una longitud de bobina (Coil Length) de 12 cm, proporcionando el balance ideal entre seguridad atraumática y firmeza para cruzar obstrucciones.</p>\n</li>\n<li>\n<p><b>Versatilidad de Configuraciones:</b> Está disponible en longitudes de 180 cm y 300 cm, ofreciendo además opciones de configuración de punta recta (Straight) y pre-formada en J (J-shape) para ajustarse a las preferencias del operador.</p>\n</li>\n</ul>\n", "image": "assets/d4d22eabf598f535.webp", "pdfs": [{"url": "https://asahi-inteccusa-medical.com/wp-content/uploads/2021/01/Asahi-14254-PTCA-GuideWiresBrochure-Trifold-FINAL-web.pdf", "path": "assets/documento-2e93d9406b11.pdf", "name": "Catálogo de guías coronarias Asahi · inglés", "label": "Catálogo de guías coronarias Asahi · inglés"}], "source": "https://academiayumyeong.com/alfacor/product/fielder/", "quickType": "Guía coronaria con polímero", "quickSpecs": [["Carga de punta", "1 gf"], ["Diámetro", "0.014″"], ["Longitudes", "180 / 300 cm"], ["Recubrimiento", "Polímero + hidrofílico, 22 cm"], ["Puntas", "Recta / J"]], "tipLoad": 1, "useCase": "Navegación y cruce coronario cuando se busca lubricidad en lesiones estrechas o trayectos tortuosos.", "officialSource": "https://medical.asahi-intecc.com/latam-es/products-coronary/fielder.html", "asahiGroup": "guides", "guideGroup": "frontline"}, {"id": 622, "slug": "grand-slam", "name": "Grand Slam", "specialty": "cardio-intervencion", "categories": [{"slug": "caballito-batalla", "name": "Caballito Batalla"}, {"slug": "coronario", "name": "Coronario"}, {"slug": "guias", "name": "Guías"}, {"slug": "asahi-guides", "name": "Guías Asahi"}], "category": "Caballito Batalla", "brand": "Asahi Intecc", "summary": "Alambre guía coronario de especialidad (#Specialty Guidewire) diseñado con un eje excepcionalmente rígido. Su estructura proporciona un apoyo adicional indispensable para facilitar el suministro seguro de dispositivos de intervención en los casos clínicos y anatómicos más extremos.", "content": "<p>La guía coronaria Grand Slam de Asahi Intecc está concebida para superar las limitaciones de soporte en el laboratorio de hemodinamia. A diferencia de los alambres de primera línea estándar, este modelo está clasificado como una herramienta de especialidad, orientada a intervenciones de alta complejidad donde el respaldo del sistema es el factor más crítico. Su diseño se centra en un eje de alambre notablemente rígido que otorga un anclaje superior.</p>\n<p>Esta rigidez estructural asegura que, al avanzar dispositivos voluminosos (como balones, stents largos o sistemas de aterectomía) a través de vasos calcificados o tortuosos, el catéter guía se mantenga estabilizado. Para contrarrestar esta firmeza y mantener la seguridad del vaso, la guía incorpora un recubrimiento de silicona a lo largo de 41 cm de su longitud y una carga de punta suave de 0.7gf, garantizando un control táctil óptimo y una interacción segura con la lesión.</p>\n<h3>Beneficios y Características:</h3>\n<ul>\n<li>\n<p><b>Soporte Estructural Extremo:</b> Su eje de alambre rígido está específicamente diseñado para otorgar un apoyo adicional inigualable durante el suministro de dispositivos en casos extremos.</p>\n</li>\n<li>\n<p><b>Control Táctil Avanzado:</b> Incorpora un recubrimiento de silicona (Silicone Coating) con una longitud de 41 cm, lo que elimina el deslizamiento excesivo y asegura una respuesta táctil precisa para el cardiólogo intervencionista.</p>\n</li>\n<li>\n<p><b>Visibilidad Radiopaca Extendida:</b> Cuenta con una longitud radiopaca de 4 cm (1 cm más que el estándar de la línea SION), permitiendo un seguimiento visual claro y preciso de la punta bajo fluoroscopia.</p>\n</li>\n<li>\n<p><b>Seguridad en la Punta:</b> A pesar de su cuerpo rígido, mantiene un perfil atraumático con una carga de punta (Tip Load) controlada de 0.7gf, logrando un equilibrio perfecto entre soporte proximal y seguridad distal.</p>\n</li>\n<li>\n<p><b>Opciones de Configuración:</b> Está disponible en longitudes utilizables de 180 cm y 300 cm, y el operador puede seleccionar una configuración de punta recta (Straight) o pre-formada en J (J-shape) según la necesidad del acceso.</p>\n</li>\n</ul>\n", "image": "assets/87cc885f0215a525.webp", "pdfs": [{"url": "https://medical.asahi-intecc.com/sites/default/files/2024-11/ASAHI%2BMiracle_MIRACLEbros%2Bseries_Grand%2BSlam%2BVer.1.00%20%282%29.pdf", "path": "assets/documento-71a5b2b2584a.pdf", "name": "IFU Grand Slam / Miracle · multilingüe", "label": "IFU Grand Slam / Miracle · multilingüe"}], "source": "https://academiayumyeong.com/alfacor/product/grand-slam/", "quickType": "Guía coronaria de soporte", "quickSpecs": [["Carga de punta", "0.7 gf"], ["Longitudes", "180 / 300 cm"], ["Recubrimiento", "Silicona, 41 cm"], ["Radiopacidad", "4 cm"], ["Puntas", "Recta / J"]], "tipLoad": 0.7, "useCase": "Soporte para entregar balones o stents en anatomías tortuosas; se prioriza el soporte del cuerpo de la guía.", "officialSource": "https://medical.asahi-intecc.com/latam-es/products-coronary/grand-slam.html", "asahiGroup": "guides", "guideGroup": "frontline"}, {"id": 620, "slug": "sion-black", "name": "SION black", "specialty": "cardio-intervencion", "categories": [{"slug": "caballito-batalla", "name": "Caballito Batalla"}, {"slug": "coronario", "name": "Coronario"}, {"slug": "guias", "name": "Guías"}, {"slug": "asahi-guides", "name": "Guías Asahi"}], "category": "Caballito Batalla", "brand": "Asahi Intecc", "summary": "Alambre guía coronario de vanguardia (frontline) equipado con una envoltura de polímero, diseñado específicamente para optimizar el rendimiento en casos complejos. Ofrece una lubricidad excepcional y una capacidad de seguimiento suave, permitiendo una entrada y un cruce precisos en lesiones desafiantes.", "content": "<p>La guía ASAHI SION black de Asahi Intecc representa una fusión avanzada entre la tecnología de envoltura de polímero y la reconocida durabilidad de la familia SION. Este dispositivo está diseñado para superar escenarios clínicos donde la resistencia a la fricción y la tortuosidad anatómica son extremas. Su recubrimiento especializado maximiza la lubricidad, facilitando una penetración y un cruce de lesiones notablemente más fluidos en comparación con las guías convencionales.</p>\n<p>A diferencia de otros alambres recubiertos de polímero en el mercado, la ASAHI SION black destaca por su excepcional flexibilidad lateral. Esta característica permite que la punta se adapte y siga el trayecto del vaso con gran precisión, aumentando significativamente la capacidad de seguimiento (trackability) en redes arteriales altamente tortuosas. Combinada con la tecnología de núcleo ACT ONE, esta guía mantiene su integridad estructural y operabilidad, resistiendo la deformación por flexión prolongada.</p>\n<h3>Beneficios y Características:</h3>\n<ul>\n<li>\n<p><b>Lubricidad Superior:</b> Las propiedades inherentes de su envoltura de polímero, combinadas con un recubrimiento hidrofílico distal de 40 cm, permiten una entrada y un cruce extremadamente suaves en la lesión coronaria.</p>\n</li>\n<li>\n<p><b>Alta Flexibilidad Lateral:</b> A diferencia de los alambres con envoltura de polímero convencionales, este modelo es altamente flexible lateralmente, lo que incrementa de manera directa la capacidad de seguimiento en anatomías muy tortuosas.</p>\n</li>\n<li>\n<p><b>Durabilidad Protegida (ACT ONE):</b> Gracias a la tecnología de bobina multifilar ACT ONE en su núcleo, la guía apenas se ve afectada por las curvas cerradas, manteniendo la operabilidad y la transmisión de torque intactas.</p>\n</li>\n<li>\n<p><b>Carga de Punta Versátil:</b> Presenta una carga de punta (tip load) de 0.8gf, proporcionando el equilibrio ideal entre fuerza de avance y seguridad atraumática.</p>\n</li>\n<li>\n<p><b>Configuraciones de Punta Múltiples:</b> Para adaptarse a diversas técnicas de cateterismo, está disponible con opciones de punta recta (Straight), pre-formada (Pre-shape) y en forma de J (J-shape).</p>\n</li>\n</ul>\n", "image": "assets/d7de87b67c0fb73f.webp", "pdfs": [{"url": "https://medical.asahi-intecc.com/sites/default/files/2026-04/PCI%2BGuide%2BWire%2BSION%2Bseries%2B%2BAMK-DT768%2BVer.2.00.pdf", "path": "assets/documento-5fa57c259069.pdf", "name": "IFU serie SION y SUOH 03 · multilingüe", "label": "IFU serie SION y SUOH 03 · multilingüe"}], "source": "https://academiayumyeong.com/alfacor/product/sion-black/", "quickType": "Guía coronaria con polímero", "quickSpecs": [["Carga de punta", "0.8 gf"], ["Recubrimiento", "Polímero + hidrofílico, 40 cm"], ["Tecnología", "ACT ONE"], ["Puntas", "Múltiples configuraciones"]], "tipLoad": 0.8, "useCase": "Navegación coronaria tortuosa o distal cuando se necesita la lubricidad adicional de una cubierta polimérica.", "officialSource": "https://medical.asahi-intecc.com/en/products-coronary/sion-black.html", "asahiGroup": "guides", "guideGroup": "frontline"}, {"id": 617, "slug": "sion-blue-es", "name": "SION blue ES", "specialty": "cardio-intervencion", "categories": [{"slug": "caballito-batalla", "name": "Caballito Batalla"}, {"slug": "coronario", "name": "Coronario"}, {"slug": "guias", "name": "Guías"}, {"slug": "asahi-guides", "name": "Guías Asahi"}], "category": "Caballito Batalla", "brand": "Asahi Intecc", "summary": "Alambre guía coronario de vanguardia (frontline) diseñado con un nivel de soporte adicional (Extra Support). Esta guía estabiliza de forma excepcional el catéter guía, garantizando un suministro de dispositivos libre de estrés, al mismo tiempo que mantiene la sobresaliente capacidad de dirección y maniobrabilidad que caracteriza a toda la familia SION.", "content": "<p>La guía ASAHI SION blue ES de Asahi Intecc representa la solución ideal para intervenciones coronarias percutáneas que exigen un delicado equilibrio entre flexibilidad distal y un fuerte soporte proximal. Su diseño de núcleo equilibrado y compuesto proporciona la firmeza necesaria para estabilizar el sistema de cateterismo en procedimientos complejos, reduciendo drásticamente el estrés operativo del especialista durante la entrega del dispositivo.</p>\n<p>A pesar de su mayor rigidez estructural (backup support), la SION blue ES no sacrifica el control. Gracias a que sus 5 cm más distales conservan la misma flexibilidad ultrasuave de la serie SION original, el operador puede seleccionar ramas laterales con total precisión y navegar a través de vasos altamente tortuosos con una mínima pérdida de la capacidad de dirección. Es la herramienta definitiva para lograr un enderezamiento vascular seguro que facilite el seguimiento de stents y balones.</p>\n<h3>Beneficios y Características:</h3>\n<ul>\n<li>\n<p><b>Soporte de Respaldo Superior (Extra Support):</b> Su estructura proporciona un fuerte nivel de apoyo (backup) que estabiliza activamente el catéter guía, evitando su desplazamiento o prolapso durante el avance de dispositivos voluminosos.</p>\n</li>\n<li>\n<p><b>Capacidad de Dirección Optimizada:</b> Integrando un núcleo compuesto con un diseño de alambre equilibrado, la guía permite un control preciso y una fácil selección de ramas, mitigando la pérdida de maniobrabilidad incluso en las anatomías más desafiantes.</p>\n</li>\n<li>\n<p><b>Flexibilidad Distal Preservada:</b> Los últimos 5 cm de la punta mantienen la flexibilidad atraumática característica de la línea SION, con una carga suave de 0.5gf, asegurando un acceso seguro en todo momento.</p>\n</li>\n<li>\n<p><b>Enderezamiento Anatómico Seguro:</b> Su perfil de rigidez controlada facilita el enderezamiento temporal del vaso tortuoso, lo que se traduce en un seguimiento (tracking) del dispositivo mucho más rápido, fluido y libre de complicaciones.</p>\n</li>\n<li>\n<p><b>Recubrimiento Híbrido Extendido:</b> Cuenta con una combinación de silicona y recubrimiento hidrofílico que se extiende a lo largo de 42 cm en su sección distal, brindando un balance perfecto entre deslizamiento fluido y control táctil superior.</p>\n</li>\n</ul>\n", "image": "assets/0e9642f692e5755c.webp", "pdfs": [{"url": "https://medical.asahi-intecc.com/sites/default/files/2026-04/PCI%2BGuide%2BWire%2BSION%2Bseries%2B%2BAMK-DT768%2BVer.2.00.pdf", "path": "assets/documento-5fa57c259069.pdf", "name": "IFU serie SION y SUOH 03 · multilingüe", "label": "IFU serie SION y SUOH 03 · multilingüe"}], "source": "https://academiayumyeong.com/alfacor/product/sion-blue-es/", "quickType": "Guía coronaria de extra soporte", "quickSpecs": [["Carga de punta", "0.5 gf"], ["Soporte", "Extra Support (ES)"], ["Recubrimiento", "Silicona + hidrofílico, 42 cm"], ["Segmento flexible", "5 cm distales"]], "tipLoad": 0.5, "useCase": "Intervenciones coronarias que requieren más soporte para entregar dispositivos, conservando una punta suave.", "officialSource": "https://medical.asahi-intecc.com/en/products-coronary/sion-blue-es.html", "asahiGroup": "guides", "guideGroup": "frontline"}, {"id": 615, "slug": "sion-blue", "name": "SION blue", "specialty": "cardio-intervencion", "categories": [{"slug": "caballito-batalla", "name": "Caballito Batalla"}, {"slug": "coronario", "name": "Coronario"}, {"slug": "guias", "name": "Guías"}, {"slug": "asahi-guides", "name": "Guías Asahi"}], "category": "Caballito Batalla", "brand": "Asahi Intecc", "summary": "Alambre guía coronario de vanguardia (frontline) diseñado para satisfacer una amplia gama de necesidades clínicas en anatomías tortuosas. Mantiene el alto rendimiento estructural de la familia SION, incorporando un diseño de punta más suave y un control de recubrimiento que otorgan al médico una manipulación precisa, segura y predecible.", "content": "<p>La guía ASAHI SION blue de Asahi Intecc está meticulosamente diseñada para ofrecer a los cardiólogos intervencionistas una herramienta de primera línea que garantice facilidad de uso y máxima seguridad del paciente. Su arquitectura estructural hereda la excelente navegabilidad y retención de forma de la serie SION, pero se ajusta con especificaciones únicas para optimizar el soporte y la respuesta táctil durante las intervenciones coronarias complejas.</p>\n<p>Este dispositivo destaca en situaciones de bifurcaciones y vasos altamente tortuosos. Su punta cuenta con una configuración extremadamente flexible que minimiza el riesgo de traumatismos vasculares, permitiendo una liberación de la tensión de manera horizontal en caso de encontrar resistencia anatómica. Además, su distintivo eje de color azul representa una ventaja técnica crítica en el laboratorio de hemodinamia, permitiendo una rápida identificación visual cuando el especialista necesita trabajar con múltiples guías de forma simultánea.</p>\n<h3>Beneficios y Características:</h3>\n<ul>\n<li>\n<p><b>Punta de Máxima Seguridad:</b> A diferencia de otros modelos de la línea, la punta carece de la tecnología ACT ONE en su segmento más distal, haciéndola excepcionalmente flexible. Al enfrentarse a bifurcaciones complejas, cualquier tensión generada se libera horizontalmente, previniendo daños en la pared arterial.</p>\n</li>\n<li>\n<p><b>Carga de Punta Ultra Suave:</b> Cuenta con una carga en la punta (tip load) de tan solo 0.5gf, siendo aún menor que la versión SION estándar. Esto garantiza un perfil de navegación altamente atraumático en anatomías delicadas.</p>\n</li>\n<li>\n<p><b>Soporte Superior en Vasos Tortuosos:</b> Su estructura optimizada ofrece una plataforma de soporte robusta, lo que resulta en una clara superioridad al momento de avanzar y desplegar dispositivos voluminosos, como stents de gran longitud, a través de curvas cerradas.</p>\n</li>\n<li>\n<p><b>Identificación Visual Inmediata:</b> El color azul del eje permite diferenciar rápidamente los alambres al realizar intervenciones complejas que exigen el uso de dos o más guías, tales como la «Kissing Balloon Technique» o diversas técnicas de anclaje.</p>\n</li>\n<li>\n<p><b>Recubrimiento de Control Táctil:</b> Integra una combinación de recubrimiento hidrofílico y de silicona en los 20 cm distales. Esta modificación reduce ligeramente la lubricidad extrema en favor de brindarle al operador una respuesta táctil superior y un alambre mucho más seguro de controlar.</p>\n</li>\n</ul>\n", "image": "assets/cf9c6a6e13dc12ea.webp", "pdfs": [{"url": "https://medical.asahi-intecc.com/sites/default/files/2026-04/PCI%2BGuide%2BWire%2BSION%2Bseries%2B%2BAMK-DT768%2BVer.2.00.pdf", "path": "assets/documento-5fa57c259069.pdf", "name": "IFU serie SION y SUOH 03 · multilingüe", "label": "IFU serie SION y SUOH 03 · multilingüe"}], "source": "https://academiayumyeong.com/alfacor/product/sion-blue/", "quickType": "Guía coronaria de trabajo", "quickSpecs": [["Carga de punta", "0.5 gf"], ["Recubrimiento", "Hidrofílico + silicona, 20 cm distales"], ["Identificación", "Eje azul"], ["Función", "Navegación y soporte de dispositivos"]], "tipLoad": 0.5, "useCase": "Guía de trabajo para navegación coronaria y entrega de dispositivos, con equilibrio entre deslizamiento y control.", "officialSource": "https://medical.asahi-intecc.com/en/products-coronary/sion-blue.html", "asahiGroup": "guides", "guideGroup": "frontline"}, {"id": 613, "slug": "sion", "name": "Sion", "specialty": "cardio-intervencion", "categories": [{"slug": "caballito-batalla", "name": "Caballito Batalla"}, {"slug": "coronario", "name": "Coronario"}, {"slug": "guias", "name": "Guías"}, {"slug": "asahi-guides", "name": "Guías Asahi"}], "category": "Caballito Batalla", "brand": "Asahi Intecc", "summary": "Guía coronaria hidrofílica de primera línea (frontline) que ofrece una excelente navegabilidad (trackability) en vasos tortuosos. Su diseño avanzado de núcleo compuesto permite a los cardiólogos intervencionistas completar los procedimientos de principio a fin utilizando una única guía.", "content": "<p>La guía ASAHI SION de Asahi Intecc es una herramienta fundamental en el laboratorio de cateterismo, diseñada para superar los desafíos de las anatomías coronarias complejas. Su estructura principal se basa en un diseño de núcleo compuesto (Composite Core) que revoluciona la forma en que la guía responde a los movimientos del operador, mejorando significativamente la respuesta direccional y la retención de la forma de la punta.</p>\n<p>Este dispositivo integra la tecnología patentada ACT ONE, la cual optimiza el equilibrio perfecto entre la fuerza del torque, la durabilidad y la rigidez. Su excepcional flexibilidad en la punta facilita un seguimiento suave a través de las curvas del vaso, permitiendo una colocación distal profunda y segura. Al combinar estas propiedades, la ASAHI SION se convierte en una guía altamente versátil que minimiza la necesidad de intercambiar dispositivos durante el caso, optimizando así el tiempo y los resultados clínicos.</p>\n<h3>Beneficios y Características:</h3>\n<ul>\n<li>\n<p><b>Estructura de Núcleo Compuesto:</b> Mejora drásticamente la transmisión del torque desde el extremo proximal hasta el distal, al mismo tiempo que garantiza una excelente retención de la forma de la punta durante toda la intervención.</p>\n</li>\n<li>\n<p><b>Tecnología Patentada ACT ONE:</b> Utiliza un diseño de bobina de múltiples hilos que optimiza la durabilidad de la guía, asegurando la protección de su forma y una transmisión de rotación sumamente precisa.</p>\n</li>\n<li>\n<p><b>Núcleo Trenzado (Twist Core):</b> Proporciona mayor fuerza estructural a la punta y elimina el efecto látigo («whipping»), garantizando un avance suave y totalmente predecible dentro de la arteria.</p>\n</li>\n<li>\n<p><b>Navegabilidad Distal (Trackability):</b> Su excepcional flexibilidad, combinada con una carga de punta (tip load) suave de 0.7gf, permite un acceso fluido hacia las ubicaciones distales más profundas y tortuosas.</p>\n</li>\n<li>\n<p><b>Recubrimiento SLIP-COAT:</b> Cuenta con un recubrimiento hidrofílico de alto rendimiento que recubre los 280 mm distales de la guía, lo que reduce la fricción al mínimo y asegura un deslizamiento atraumático.</p>\n</li>\n</ul>\n", "image": "assets/88c3fe93d46328e9.webp", "pdfs": [{"url": "https://medical.asahi-intecc.com/sites/default/files/2026-04/PCI%2BGuide%2BWire%2BSION%2Bseries%2B%2BAMK-DT768%2BVer.2.00.pdf", "path": "assets/documento-5fa57c259069.pdf", "name": "IFU serie SION y SUOH 03 · multilingüe", "label": "IFU serie SION y SUOH 03 · multilingüe"}], "source": "https://academiayumyeong.com/alfacor/product/sion/", "quickType": "Guía coronaria de trabajo", "quickSpecs": [["Carga de punta", "0.7 gf"], ["Tecnología", "ACT ONE + Twist Core"], ["Recubrimiento", "SLIP-COAT, 28 cm distales"], ["Núcleo", "Compuesto"]], "tipLoad": 0.7, "useCase": "Guía de trabajo para navegación coronaria, especialmente en anatomías tortuosas que requieren seguimiento y torque.", "officialSource": "https://medical.asahi-intecc.com/latam-es/products-coronary/asahi-sion.html", "asahiGroup": "guides", "guideGroup": "frontline"}, {"id": 608, "slug": "biofreedom", "name": "BioFreedom™ Ultra", "specialty": "cardio-intervencion", "categories": [{"slug": "coronario", "name": "Coronario"}, {"slug": "stent", "name": "Stent"}], "category": "Stent", "brand": "Biosensors International", "summary": "BioFreedom™ Ultra es un stent recubierto de droga Biolimus A9 (BA9™) en su parte abluminal, sin polímero y sobre una plataforma de cromo cobalto, lo cual lo convierte en un novedoso stent apto para pacientes con enfermedad coronaria compleja como síndrome coronario agudo y para pacientes con alto riesgo de sangrado/hemorragia (HBR) los cuales se pueden tratar con DAPT \nde un mes.", "content": "<p>La combinación de una superficie abluminal selectivamente microestructurada (SMS) patentada por Biosensors International Group, Ltda, junto con el recubrimiento de Biolimus A9™ (BA9™) confiere al Biofreedom™ Ultra un diseño diferenciado dentro de los stents coronarios, al ser liberador de fármaco libre de polímero.</p>\n<p>Se estima que una proporción importante de los pacientes sometidos a intervención coronaria percutánea (PCI) presentan alto riesgo de sangrado (HBR) y requieren una estrategia terapéutica individualizada; en este contexto Biofreedom™ Ultra representa una alternativa terapéutica respaldada por la rápida transferencia de BA9™ a la arteria coronaria (aproximadamente 28 días), junto con una reendotelización temprana del vaso tratado, lo que permite utilizar un esquema abreviado de terapia antiplaquetaria dual (DAPT).</p>\n<p>La rápida transferencia de BA9™ a la arteria coronaria en 28 días y la rápida reendotelización del vaso con el stent hacen de BioFreedom™ Ultra la opción de stent más relevante para pacientes<br>\ncon alto riesgo de sangrado (HBR) que no pueden tolerar la terapia antiplaquetaria dual (DAPT) prolongada.</p>\n<p><strong>Su diseño y plataforma posee las siguientes características: </strong></p>\n<ul>\n<li>\n<p>Alta apertura de celdas para fácil acceso de ramas laterales.</p>\n</li>\n<li>\n<p>Baja susceptibilidad a compresión longitudinal, favoreciendo el recruce del stent cuando sea requerido.</p>\n</li>\n<li>\n<p>Bajo nivel de recoil, contribuyendo al mantenimiento del diámetro del stent y reduciendo el riesgo de mala aposición del mismo. </p>\n</li>\n</ul>\n<p><strong>BA9™ diseñado específicamente para la aplicación de stent coronario:</strong></p>\n<ul>\n<li>\n<p>Molécula exclusiva desarrollada por Biosensors International Group, Ltda.</p>\n</li>\n<li>\n<p>Diseñado para favorecer procesos asociados a la cicatrización vascular y reendotelización.</p>\n</li>\n<li>Presenta lipofilicidad hasta 10 veces mayor en comparación con otros compuestos tipo Limus, favoreciendo una alta biodisponibilidad del fármaco y una mínima exposición sistémica.</li>\n</ul>\n<p> </p>\n<p> </p>\n", "image": "assets/143d062631a954cd.webp", "pdfs": [{"url": "https://cpc1.com.vn/Files/Uploads/2023/05/31/15/05/HDSD%20BioFreedom%20Ultra.pdf", "path": "assets/ultra-ifu.pdf", "name": "Instrucciones de uso · BioFreedom™ Ultra"}], "source": "https://academiayumyeong.com/alfacor/product/biofreedom/", "quickType": "Stent coronario liberador de fármaco", "quickSpecs": [["Fármaco", "Biolimus A9 (BA9)"], ["Polímero", "Sin polímero"], ["Superficie", "Abluminal microestructurada (SMS)"], ["Transferencia de fármaco", "Aproximadamente 28 días"]], "officialSource": "https://www.biosensors.com/intl/biofreedom-ultra", "pressureInfo": {"rows": [["2,25", "14, 19, 24, 29", "8", "16"], ["2,50", "14, 19, 24, 29, 33, 36", "8", "16"], ["2,75", "14, 19, 24, 29, 33, 36", "8", "16"], ["3,00", "14, 19, 24, 29, 33, 36", "8", "16"], ["3,50", "14, 19, 24, 29, 33, 36", "8", "14"], ["4,00", "14, 19, 24, 29", "8", "14"]], "sourceLabel": "11677-000 Rev.03 · tabla 1, p. 3 (p. 9 del PDF)", "sourcePath": "assets/ultra-ifu.pdf#page=9"}, "expansionInfo": {"rows": [{"diameters": "2,25–3,00", "maximum": "4,76", "sample": "3,0 × 19", "balloon": "5,0"}, {"diameters": "3,50–4,00", "maximum": "5,95", "sample": "4,0 × 19", "balloon": "6,0"}]}, "compliance": {"short": [[8, 2.25, 2.5, 2.75, 3, 3.5, 4], [9, 2.28, 2.54, 2.79, 3.05, 3.56, 4.07], [10, 2.31, 2.58, 2.83, 3.1, 3.62, 4.14], [11, 2.34, 2.62, 2.87, 3.15, 3.68, 4.21], [12, 2.37, 2.66, 2.91, 3.2, 3.74, 4.28], [13, 2.4, 2.7, 2.95, 3.25, 3.8, 4.35], [14, 2.43, 2.74, 2.99, 3.3, 3.86, 4.42], [15, 2.46, 2.78, 3.03, 3.35, null, null], [16, 2.49, 2.82, 3.07, 3.4, null, null]], "long": [[8, 2.5, 2.75, 3, 3.5], [9, 2.56, 2.83, 3.08, 3.59], [10, 2.62, 2.91, 3.16, 3.67], [11, 2.68, 2.98, 3.23, 3.75], [12, 2.74, 3.04, 3.29, 3.83], [13, 2.8, 3.09, 3.35, 3.91], [14, 2.85, 3.14, 3.4, 3.98], [15, 2.9, 3.19, 3.45, null], [16, 2.95, 3.24, 3.5, null]]}}, {"id": 606, "slug": "biomatrix-alpha", "name": "BioMatrix™ Alpha", "specialty": "cardio-intervencion", "categories": [{"slug": "coronario", "name": "Coronario"}, {"slug": "stent", "name": "Stent"}], "category": "Stent", "brand": "Biosensors International", "summary": "Biomatrix ™ Alpha consiste en un stent coronario liberador de fármaco (DES) que incorpora una plataforma optimizada dentro de su categoría, combinada con un revestimiento abluminal biodegradable diseñado para favorecer la respuesta vascular y promover una adecuada cicatrización del vaso tratado.", "content": "<p>Biomatrix™ Alpha combina la seguridad clínica de un stent liberador de fármaco con un recubrimiento abluminal biodegradable y la eficacia de Biolimus A9™ (BA9™), integrados sobre una plataforma de cromo-cobalto diseñada para optimizar el desempeño mecánico y la liberación localizada del fármaco.</p>\n<p><strong>Su diseño y plataforma posee las siguientes características: </strong></p>\n<ul>\n<li>\n<p>Alta apertura de celdas para fácil acceso de ramas laterales.</p>\n</li>\n<li>\n<p>Muy bajo porcentaje de compresión longitudinal, lo que genera mayor posibilidad de recruzar el stent.</p>\n</li>\n<li>\n<p>Bajo porcentaje de recoil, por lo que su diámetro se mantiene para evitar mal aposición del stent.</p>\n</li>\n</ul>\n<p><strong>Polímero biodegrabable: </strong></p>\n<ul>\n<li>\n<p>Polímero de ácido poliláctico (PLA) patentado.</p>\n</li>\n<li>\n<p>Liberación del fármaco dirigida con absorción sincrónica del polímero.</p>\n</li>\n<li>\n<p>Duración de absorción entre 6-9 meses.</p>\n</li>\n</ul>\n<p><strong>BA9™ diseñado específicamente para la aplicación de stent coronario: </strong></p>\n<ul>\n<li>\n<p>Molécula exclusiva desarrollada por Biosensors International Group, Ltda.</p>\n</li>\n<li>\n<p>Diseñado para favorecer procesos asociados a la cicatrización vascular y reendotelización.</p>\n</li>\n<li>\n<p>Presenta lipofilicidad hasta 10 veces mayor en comparación con otros compuestos tipo Limus, favoreciendo una alta biodisponibilidad del fármaco y una mínima exposición sistémica.</p>\n</li>\n</ul>\n", "image": "assets/4f0bfb84c3859e2d.webp", "pdfs": [{"url": "https://cpc1.com.vn/Files/Uploads/2023/05/31/15/18/HDSD%20BioMatrix%20Alpha.pdf", "path": "assets/alpha-ifu.pdf", "name": "Instrucciones de uso · BioMatrix™ Alpha"}], "source": "https://academiayumyeong.com/alfacor/product/biomatrix-alpha/", "quickType": "Stent coronario liberador de fármaco", "quickSpecs": [["Plataforma", "Cromo-cobalto"], ["Fármaco", "Biolimus A9 (BA9)"], ["Polímero", "PLA biodegradable, abluminal"], ["Absorción del polímero", "6–9 meses"]], "officialSource": "https://www.biosensors.com/intl/product-biomatrix-alpha", "pressureInfo": {"rows": [["2,25", "14, 19, 24, 29", "8", "16"], ["2,50", "14, 19, 24, 29, 33, 36", "8", "16"], ["2,75", "14, 19, 24, 29, 33, 36", "8", "16"], ["3,00", "14, 19, 24, 29, 33, 36", "8", "16"], ["3,50", "14, 19, 24, 29, 33, 36", "8", "14"], ["4,00", "14, 19, 24, 29", "8", "14"]], "sourceLabel": "11265-000 Rev.03 · tabla 1, p. 3 (p. 9 del PDF)", "sourcePath": "assets/alpha-ifu.pdf#page=9"}, "expansionInfo": {"rows": [{"diameters": "2,25–3,00", "maximum": "4,76", "sample": "3,0 × 19", "balloon": "5,0"}, {"diameters": "3,50–4,00", "maximum": "5,95", "sample": "4,0 × 19", "balloon": "6,0"}]}}, {"id": 444, "slug": "eclipse-2l", "name": "Eclipse 2L", "specialty": "neuro-intervencion", "categories": [{"slug": "balones-neuro", "name": "Balones"}], "category": "Balones", "brand": "Balt", "summary": "Catéter balón de doble lumen diseñado para oclusión temporal selectiva y embolización asistida en procedimientos neurovasculares y periféricos. Su arquitectura exclusiva de catéter plano con lúmenes independientes facilita la navegación, el control del flujo y la administración simultánea de terapias.", "content": "<p><strong>Beneficios Clínicos Clave:</strong></p>\n<ul>\n<li><strong>Diseño Exclusivo de Catéter Plano de Doble Lumen: </strong>Integra dos lúmenes completamente independientes para inflado del balón e infusión terapéutica, permitiendo mantener la vía de trabajo durante todo el procedimiento.</li>\n</ul>\n<p> </p>\n<ul>\n<li><strong>Compatibilidad Terapéutica Avanzada (DMSO): </strong>Diseñado para la administración segura de medios de contraste, coils de embolización y agentes embólicos líquidos compatibles con DMSO.</li>\n</ul>\n<p> </p>\n<ul>\n<li><strong>Versatilidad de Punta Distal: </strong>Disponible en diferentes configuraciones de punta distal para adaptarse a diversos escenarios anatómicos y estrategias de tratamiento.</li>\n</ul>\n<p> </p>\n<ul>\n<li><strong>Versión de Punta Corta con Marcador: </strong>Incorpora un marcador radiopaco específico que facilita la liberación precisa durante procedimientos de coiling asistido por balón.</li>\n</ul>\n<p> </p>\n<ul>\n<li><strong>Visibilidad Fluoroscópica Optimizada: </strong>Proporciona excelente visualización bajo fluoroscopia para un posicionamiento preciso y un control seguro durante la oclusión temporal.</li>\n</ul>\n<p> </p>\n", "image": "assets/54107cff9f9265a8.webp", "pdfs": [{"url": "https://academiayumyeong.com/alfacor/wp-content/uploads/2026/02/ET-Balon-Eclipse-Copernic-linea-104.pdf", "path": "assets/929a6cc14afe1285.pdf", "name": "ET-Balon-Eclipse-Copernic-linea-104.pdf"}], "source": "https://academiayumyeong.com/alfacor/product/eclipse-2l/", "quickType": "Balón neurovascular de doble lumen", "quickSpecs": [["Lúmenes", "Inflado e infusión independientes"], ["Compatibilidad", "DMSO, según documentación"], ["Puntas", "Varias configuraciones"], ["Visibilidad", "Marcador radiopaco distal"]]}, {"id": 442, "slug": "copernic-rc", "name": "Copernic RC", "specialty": "neuro-intervencion", "categories": [{"slug": "balones-neuro", "name": "Balones"}], "category": "Balones", "brand": "Balt", "summary": "Catéter balón de doble lumen diseñado para remodelación venosa y oclusión temporal en procedimientos neurovasculares complejos. Su alta conformabilidad, perfil ultrabajo y excelente navegabilidad permiten una embolización más controlada y precisa en anatomías venosas desafiantes.", "content": "<p><b>Beneficios Clínicos Clave:</b></p>\n<ul>\n<li><strong>Alta Conformabilidad Venosa: </strong>Su material de balón altamente flexible se adapta a la geometría asimétrica e irregular de las venas y senos durales, favoreciendo una oclusión temporal segura con mínimo trauma vascular</li>\n</ul>\n<ul>\n<li>\n<p><b>Perfil de Cruce Ultrabajo:</b> Diseñado para una navegación suave y atraumática a través de anatomías complejas, facilitando el acceso a territorios distales y lesiones de difícil abordaje.</p>\n</li>\n<li>\n<p><b>Doble Lumen Integrado:</b> Permite el inflado y desinflado controlado del balón mientras mantiene el espacio de trabajo necesario para la microguía durante el procedimiento.</p>\n</li>\n<li>\n<p><strong>Soporte Dinámico para Embolización</strong><b>:</b> Proporciona una barrera temporal que favorece el empaquetamiento de coils y mejora el control durante la inyección de agentes embólicos líquidos.</p>\n</li>\n<li>\n<p><b>Radiopacidad Estratégica:</b> Equipado con marcadores radiopacos que facilitan la visualización y el posicionamiento preciso del balón bajo fluoroscopia.</p>\n</li>\n</ul>\n", "image": "assets/f61045d5875e9c66.webp", "pdfs": [{"url": "https://academiayumyeong.com/alfacor/wp-content/uploads/2026/02/ET-Balon-Eclipse-Copernic-linea-104.pdf", "path": "assets/929a6cc14afe1285.pdf", "name": "ET-Balon-Eclipse-Copernic-linea-104.pdf"}], "source": "https://academiayumyeong.com/alfacor/product/copernic-rc/", "quickType": "Balón neurovascular de remodelación", "quickSpecs": [["Diseño", "Doble lumen"], ["Balón", "Conformable"], ["Perfil", "Bajo perfil de cruce"], ["Visibilidad", "Marcadores radiopacos"]]}, {"id": 439, "slug": "squid", "name": "Squid", "specialty": "neuro-intervencion", "categories": [{"slug": "liquido-embolico", "name": "Líquido Embólico"}], "category": "Líquido Embólico", "brand": "Balt", "summary": "Agente embólico líquido no adhesivo a base de EVOH diseñado para la embolización controlada de malformaciones arteriovenosas, fístulas arteriovenosas durales y tumores hipervasculares. Su tecnología de micronización avanzada del tantalio y su amplia variedad de formulaciones permiten una excelente visibilidad radiológica y una penetración distal optimizada.", "content": "<p><strong>Beneficios Clínicos:</strong></p>\n<p> </p>\n<ul>\n<li> <strong>Micronización Avanzada del Tantalio: </strong>El tamaño ultrafino de las partículas de tantalio favorece una suspensión más homogénea, mejorando la estabilidad radiopaca durante inyecciones prolongadas.</li>\n</ul>\n<p> </p>\n<ul>\n<li> <strong>Visibilidad Radiológica Consistente: </strong>Proporciona una visualización uniforme del agente embólico durante todo el procedimiento, facilitando un mayor control de la embolización.</li>\n</ul>\n<p> </p>\n<ul>\n<li> <strong>Penetración Distal Optimizada: </strong>La formulación de baja viscosidad Squid 12 permite alcanzar microvasos distales y lograr una embolización más profunda en anatomías complejas.</li>\n</ul>\n<p> </p>\n<ul>\n<li> <strong>Opciones de Baja Densidad: </strong>Las versiones LD contienen menor concentración de tantalio, reduciendo artefactos de imagen y mejorando la evaluación radiológica posterior al tratamiento.</li>\n</ul>\n<p> </p>\n<ul>\n<li> <strong>Amplia Versatilidad Clínica: </strong>Disponible en múltiples formulaciones para adaptarse a diferentes estrategias de embolización en MAVs, FAVDs, tumores hipervasculares y otras patologías neurovasculares.</li>\n</ul>\n<p>\n", "image": "assets/c5a569293ad0dff3.webp", "pdfs": [{"url": "https://academiayumyeong.com/alfacor/wp-content/uploads/2026/02/ET-Squid-linea-105.pdf", "path": "assets/04491c969e02e5df.pdf", "name": "ET-Squid-linea-105.pdf"}], "source": "https://academiayumyeong.com/alfacor/product/squid/", "quickType": "Agente embólico líquido", "quickSpecs": [["Radiopacidad", "Tantalio micronizado"], ["Squid 12", "Formulación de baja viscosidad"], ["Versiones LD", "Menor concentración de tantalio"], ["Presentaciones", "Múltiples formulaciones"]]}, {"id": 436, "slug": "optima-optimax-optiblock", "name": "Optima / OptiMAX / Optiblock", "specialty": "neuro-intervencion", "categories": [{"slug": "coils", "name": "Coils"}], "category": "Coils", "brand": "Balt", "summary": "Familia de coils desprendibles para la embolización de aneurismas intracraneales, malformaciones arteriovenosas y fístulas arteriovenosas. Cada sistema está diseñado para responder a necesidades específicas de embolización, desde el tratamiento estándar hasta lesiones complejas y de alto flujo.", "content": "<p><strong>Beneficios Clínicos:</strong></p>\n<ul>\n<li><strong>Optima: Versatilidad para Casos Generales: </strong>Coil diseñado para framing, filling y finishing, con una amplia variedad de configuraciones que permiten adaptarse a diferentes morfologías aneurismáticas.</li>\n<li><strong>OptiMAX: Mayor Volumen con Menos Coils: </strong>Diseñado para proporcionar una mayor densidad de empaquetamiento, permitiendo rellenar aneurismas grandes de forma más eficiente utilizando menos implantes.</li>\n<li><strong>Optiblock: Anclaje Seguro en Lesiones Complejas: </strong>Su arquitectura de tres segmentos facilita el anclaje inicial, la formación de cesta y el empaquetamiento estable en situaciones de alto flujo.</li>\n<li><strong>Amplia Gama de Configuraciones: </strong>Disponible en versiones Standard, Soft y Super Soft, así como en diseños helicoidales y complejos para adaptarse a diferentes estrategias de tratamiento.</li>\n<li><strong>Liberación Instantánea y Control Preciso: </strong>El sistema de desprendimiento rápido permite reposicionar y liberar el coil con precisión, optimizando la seguridad y eficiencia del procedimiento.</li>\n</ul>\n", "image": "assets/9a383564d458cdde.webp", "pdfs": [{"url": "https://academiayumyeong.com/alfacor/wp-content/uploads/2026/02/ET-Coil-Optima-linea-107.pdf", "path": "assets/a9e20a137cf8a271.pdf", "name": "ET-Coil-Optima-linea-107.pdf"}], "source": "https://academiayumyeong.com/alfacor/product/optima-optimax-optiblock/", "quickType": "Familia de coils de embolización", "quickSpecs": [["Optima", "Framing / filling / finishing"], ["OptiMAX", "Mayor volumen de relleno"], ["Optiblock", "Diseño de tres segmentos"], ["Configuraciones", "Helicoidales / complejas"], ["Suavidad", "Standard / Soft / Super Soft"]]}, {"id": 433, "slug": "silk-vista-silk-vista-baby", "name": "Silk Vista / Silk Vista Baby", "specialty": "neuro-intervencion", "categories": [{"slug": "diversor-de-flujo", "name": "Diversor de Flujo"}], "category": "Diversor de Flujo", "brand": "Balt", "summary": "Familia de diversores de flujo intracraneales autoexpandibles diseñada para el tratamiento de aneurismas complejos y de cuello ancho. Gracias a su tecnología de radiopacidad total (DFT), perfil de entrega ultrabajo y excelente adaptabilidad vascular, permite una reconstrucción endovascular segura incluso en vasos distales y de pequeño calibre.", "content": "<p><strong>Beneficios Clínicos:</strong></p>\n<ul>\n<li><strong>Silk Vista: Tratamiento de Vasos de Mayor Calibre. </strong>Compatible con microcatéteres de 0.021″, permitiendo el tratamiento de vasos intracraneales de hasta 5.0 mm con excelente estabilidad y control durante la implantación.</li>\n<li><strong>Silk Vista Baby: Acceso a Vasos Distales. </strong>Diseñado para ser implantado mediante microcatéteres de 0.017″, facilitando el tratamiento de aneurismas localizados en arterias distales y de pequeño diámetro.</li>\n<li><strong>Visibilidad Fluoroscópica Total: </strong>La tecnología DFT incorpora 48 hilos de nitinol con núcleo de platino, proporcionando una visualización completa del dispositivo durante todo el procedimiento.</li>\n<li><strong>Apertura Suave y Excelente Aposición: </strong>Su diseño de malla homogénea y extremos acampanados favorece una expansión controlada y una óptima adaptación a la pared vascular.</li>\n<li><strong>Alta Eficiencia en Desviación de Flujo: </strong>La arquitectura de 48 hilos trenzados aumenta la cobertura metálica y promueve la redirección del flujo sanguíneo fuera del aneurisma, favoreciendo la neoendotelización del vaso.</li>\n</ul>\n", "image": "assets/d14cf5d101e60965.webp", "pdfs": [{"url": "https://academiayumyeong.com/alfacor/wp-content/uploads/2026/02/ET-Silk-Vista-linea-122.pdf", "path": "assets/7e5c0ebbc64b3bbe.pdf", "name": "ET-Silk-Vista-linea-122.pdf"}], "source": "https://academiayumyeong.com/alfacor/product/silk-vista-silk-vista-baby/", "quickType": "Familia de diversores de flujo", "quickSpecs": [["Silk Vista", "Microcatéter de 0.021″"], ["Silk Vista Baby", "Microcatéter de 0.017″"], ["Estructura", "48 hilos de nitinol con núcleo de platino"], ["Visibilidad", "Radiopaco en toda su longitud"]]}, {"id": 430, "slug": "magic", "name": "MAGIC", "specialty": "neuro-intervencion", "categories": [{"slug": "microcateter-neuro", "name": "Microcatéter"}], "category": "Microcatéter", "brand": "Balt", "summary": "Microguía neurovascular de acceso avanzado diseñada para proporcionar un equilibrio excepcional entre soporte proximal, transmisión de torque y flexibilidad distal. Su arquitectura bimetálica exclusiva combina acero inoxidable y nitinol para facilitar la navegación segura en anatomías complejas y altamente tortuosas.", "content": "<p>El microcatéter <b>MAGIC</b> de Balt revolucionó el intervencionismo neurovascular al introducir el concepto de navegación dependiente de flujo. A diferencia de los catéteres convencionales guiados por guía, el MAGIC está diseñado para ser arrastrado suavemente por el torrente sanguíneo, permitiendo el acceso a lechos vasculares cerebrales y periféricos increíblemente distales, tortuosos y de pequeño calibre (incluso menores a 1 mm de diámetro).</p>\n\n<p>Su secreto radica en la formulación exclusiva de sus materiales: una combinación de aleaciones poliméricas que otorgan resistencia en su segmento proximal y una flexibilidad sin precedentes en su porción distal. Es la herramienta indispensable y definitiva para el tratamiento de patologías complejas de alto flujo, como Malformaciones Arteriovenosas (MAVs) y malformaciones de la Vena de Galeno, ofreciendo compatibilidad total con agentes embólicos a base de cianoacrilato.</p>\n<p><b>5 Características y Beneficios Clínicos:</b></p>\n<ul>\n<li>\n<p><b>Navegación Dependiente de Flujo (Flow-Directed):</b> Su extrema flexibilidad permite que la punta del microcatéter sea propulsada por la propia corriente sanguínea, facilitando una navegación rápida, atraumática y sin esfuerzo a través de anatomías donde los catéteres sobre guía no pueden llegar.</p>\n</li>\n<li>\n<p><b>Aleaciones Exclusivas PURSIL y TORVER:</b> Fabricado con una mezcla única de poliuretano y silicona (PURSIL) en su porción distal para máxima flexibilidad, combinada con TORVER en la sección proximal, garantizando la resistencia mecánica y el control necesarios desde el acceso.</p>\n</li>\n<li>\n<p><b>Perfil Ultrabajo (Hasta 1.2F):</b> Disponible en calibres extremadamente finos (1.2F, 1.5F y 1.8F), lo que permite la cateterización hiperselectiva de los pedículos más pequeños (vasos de menos de 1 mm) sin ocluir el flujo sanguíneo necesario para su propia propulsión.</p>\n</li>\n<li>\n<p><b>Tratamiento Optimizado de MAVs y Fístulas:</b> Es el dispositivo de elección a nivel mundial para la inyección controlada de pegamentos quirúrgicos (cianoacrilatos como Magic Glue o n-BCA), asegurando una polimerización segura en el nido de la malformación (Nota: Contraindicado para uso con DMSO).</p>\n</li>\n<li>\n<p><b>Flexibilidad Progresiva y Configuraciones «Oliva»:</b> Cuenta con zonas de transición de suavidad y opciones de punta en forma de «oliva», diseñadas específicamente para maximizar el arrastre del flujo sanguíneo y mejorar el rendimiento de la navegación en anatomías complejas de alto flujo.</p>\n</li>\n</ul>\n", "image": "assets/9e591ced1f130389.webp", "pdfs": [{"url": "https://academiayumyeong.com/alfacor/wp-content/uploads/2026/02/ET-Microcateter-Magic-Linea-98.pdf", "path": "assets/b3861a050d1f5483.pdf", "name": "ET-Microcateter-Magic-Linea-98.pdf"}], "source": "https://academiayumyeong.com/alfacor/product/magic/", "quickType": "Microcatéter dirigido por flujo", "quickSpecs": [["Calibres", "1.2 / 1.5 / 1.8 Fr"], ["Materiales", "PURSIL / TORVER"], ["Agentes", "Cianoacrilatos"], ["DMSO", "No compatible"]]}, {"id": 426, "slug": "gama-gama-17", "name": "Gama+ / Gama-17", "specialty": "neuro-intervencion", "categories": [{"slug": "microcateter-neuro", "name": "Microcatéter"}], "category": "Microcatéter", "brand": "Balt", "summary": "Familia de microcatéteres neurovasculares de bajo perfil diseñada para facilitar el acceso distal y la entrega precisa de dispositivos terapéuticos complejos. Su arquitectura híbrida con refuerzo de nitinol y zonas de flexibilidad progresiva proporciona una excelente navegabilidad, soporte y estabilidad en anatomías tortuosas.", "content": "<p><strong>Beneficios Clínicos:</strong></p>\n<p> </p>\n<ul>\n<li><strong>Gama+: Mayor Soporte para Dispositivos Neurovasculares. </strong>Diseñado para proporcionar un respaldo excepcional durante la navegación y liberación de stents, diversores de flujo y otros dispositivos complejos, manteniendo una excelente estabilidad del sistema.</li>\n</ul>\n<p> </p>\n<ul>\n<li> <strong>Gama-17: Acceso Distal de Bajo Perfil. </strong>Compatible con dispositivos de menor perfil y diseñado para alcanzar vasos intracraneales pequeños y distales, facilitando procedimientos en anatomías altamente desafiantes.</li>\n</ul>\n<p> </p>\n<ul>\n<li> <strong>Navegabilidad Suave y Progresiva: </strong>Las zonas de transición de flexibilidad y el recubrimiento hidrofílico favorecen un avance controlado a través de trayectos vasculares complejos.</li>\n</ul>\n<p> </p>\n<ul>\n<li> <strong>Resistencia Superior al Colapso: </strong>Su estructura reforzada con espiral y filamentos de nitinol ayuda a preservar la integridad del lumen incluso en curvas pronunciadas.</li>\n</ul>\n<p> </p>\n<ul>\n<li><strong>Entrega Precisa y Segura de Dispositivos: </strong>El recubrimiento interno de PTFE y los marcadores radiopacos optimizan el control, la visualización y la liberación de dispositivos terapéuticos.</li>\n</ul>\n", "image": "assets/5564a0ba7ee4a7a9.webp", "pdfs": [{"url": "https://academiayumyeong.com/alfacor/wp-content/uploads/2026/02/ET-Microcateter-Gama-17-linea-98.pdf", "path": "assets/04bdaebfa7b3a561.pdf", "name": "ET-Microcateter-Gama-17-linea-98.pdf"}], "source": "https://academiayumyeong.com/alfacor/product/gama-gama-17/", "quickType": "Microcatéteres neurovasculares", "quickSpecs": [["Gama+", "Soporte para entrega de dispositivos"], ["Gama-17", "Bajo perfil para acceso distal"], ["Refuerzo", "Espiral y filamentos de nitinol"], ["Lumen interno", "PTFE"], ["Recubrimiento", "Hidrofílico"]]}, {"id": 424, "slug": "vasco", "name": "VASCO+", "specialty": "neuro-intervencion", "categories": [{"slug": "microcateter-neuro", "name": "Microcatéter"}], "category": "Microcatéter", "brand": "Balt", "summary": "Microcatéter reforzado con tecnología de trenzado progresivo, diseñado para brindar acceso, control y soporte superior en intervenciones neurovasculares complejas. Su arquitectura avanzada facilita la navegación atraumática y la entrega precisa de dispositivos terapéuticos como coils, stents autoexpandibles y sistemas de tromboembolectomía.", "content": "<p>El <b>VASCO+</b> de Balt es un microcatéter armado de alto rendimiento diseñado meticulosamente para superar los retos de la anatomía neurovascular más tortuosa. Gracias a su tecnología exclusiva de trenzado, este dispositivo ofrece un equilibrio perfecto entre soporte proximal (backup) robusto y una extrema flexibilidad distal.</p>\n<p>Su diseño reforzado y variadas opciones de diámetro lo convierten en la herramienta ideal para la navegación precisa y la liberación segura de múltiples agentes terapéuticos, garantizando la estabilidad absoluta que el especialista requiere durante procedimientos críticos de embolización y revascularización cerebral.</p>\n<p><b>Características y Beneficios Clínicos:</b></p>\n<ul>\n<li>\n<p><b>Soporte Superior de Coils:</b> Su diseño trenzado proporciona una alta fuerza radial que retiene eficazmente la masa de coils, promoviendo la endotelización del cuello del aneurisma y previniendo la protrusión hacia la arteria principal.</p>\n</li>\n<li>\n<p><b>Trenzado de Paso Progresivo:</b> Su arquitectura de malla metálica varía a lo largo del microcatéter, brindando excelente estabilidad proximal y alta resistencia al colapso (kinking), mientras mantiene una transición suave hacia una punta altamente flexible.</p>\n</li>\n<li>\n<p><b>Recubrimiento Hidrofílico Distal:</b> Reduce drásticamente la fricción intravascular, lo que aumenta el rendimiento de navegación y permite alcanzar de forma fluida y atraumática las lesiones neurovasculares más distales.</p>\n</li>\n<li>\n<p><b>Marcadores Radiopacos de Alta Visibilidad:</b> Cuenta con marcadores distales que garantizan un control fluoroscópico impecable, asegurando al especialista un posicionamiento exacto antes y durante la liberación de los dispositivos terapéuticos.</p>\n</li>\n<li>\n<p><b>Amplia Compatibilidad Terapéutica:</b> Disponible en múltiples diámetros (desde VASCO+10 hasta VASCO+35), lo que permite la inserción segura de una gran variedad de dispositivos, incluyendo coils, stents intracraneales (como LEO+ o SILK) y sistemas de tromboembolectomía.</p>\n</li>\n</ul>\n", "image": "assets/980be0d331d16941.webp", "pdfs": [{"url": "https://academiayumyeong.com/alfacor/wp-content/uploads/2026/02/ET-Microcateter-Vasco-linea-98.pdf", "path": "assets/52fb42b0bf5af462.pdf", "name": "ET-Microcateter-Vasco-linea-98.pdf"}], "source": "https://academiayumyeong.com/alfacor/product/vasco/", "quickType": "Microcatéter neurovascular reforzado", "quickSpecs": [["Modelos", "VASCO+10 a VASCO+35"], ["Estructura", "Trenzado de paso progresivo"], ["Recubrimiento", "Hidrofílico distal"], ["Visibilidad", "Marcadores radiopacos"]]}, {"id": 409, "slug": "ballast", "name": "Ballast", "specialty": "neuro-intervencion", "categories": [{"slug": "introductor-largo", "name": "Introductor Largo"}], "category": "Introductor Largo", "brand": "Balt", "summary": "Sistema introductor largo de alto soporte diseñado para facilitar la navegación y entrega de dispositivos neurovasculares complejos. Su lumen interno ultra amplio de 0.088”, combinado con una arquitectura híbrida reforzada y una punta distal atraumática, proporciona estabilidad, navegabilidad y seguridad en anatomías desafiantes.", "content": "<p><strong>Beneficios Clínicos:</strong></p>\n<p> </p>\n<ul>\n<li><strong>Lumen Interno Ultra Amplio: </strong>Su diámetro interno de 0.088” facilita el paso simultáneo de múltiples dispositivos y optimiza la entrega de diversores de flujo, stents y otros sistemas terapéuticos complejos.</li>\n</ul>\n<p> </p>\n<ul>\n<li><strong>Navegación Suave en Vasos Tortuosos: </strong>El recubrimiento hidrofílico distal reduce la fricción durante el avance, mejorando la navegabilidad y disminuyendo el riesgo de vasoespasmo.</li>\n</ul>\n<p> </p>\n<ul>\n<li><strong>Soporte y Estabilidad Excepcionales: </strong>La combinación de trenzado y espiral en el segmento proximal proporciona un respaldo sólido durante procedimientos complejos, mejorando la fuerza de empuje y el control del sistema.</li>\n</ul>\n<p> </p>\n<ul>\n<li><strong>Punta Distal Atraumática: </strong>Su transición progresivamente flexible favorece una navegación segura y minimiza el trauma sobre la pared vascular durante el posicionamiento.</li>\n</ul>\n<p> </p>\n<ul>\n<li><strong>Versatilidad para Diferentes Procedimientos: </strong>Disponible en múltiples longitudes y con un perfil externo optimizado para aplicaciones neurovasculares, coronarias y periféricas.</li>\n</ul>\n", "image": "assets/9be8d0548928b8d6.webp", "pdfs": [{"url": "https://academiayumyeong.com/alfacor/wp-content/uploads/2026/02/ET-Introductor-Ballast-linea-114-copia.pdf", "path": "assets/921083f79fef7f66.pdf", "name": "ET-Introductor-Ballast-linea-114-copia.pdf"}], "source": "https://academiayumyeong.com/alfacor/product/ballast/", "quickType": "Introductor largo de soporte", "quickSpecs": [["Lumen interno", "0.088″"], ["Refuerzo", "Trenzado + espiral"], ["Recubrimiento", "Hidrofílico distal"], ["Punta", "Flexibilidad progresiva"]]}, {"id": 340, "slug": "leo-leo-baby-stent-intracraneal-autoexpandible", "name": "LEO+ / LEO+ Baby – Stent Intracraneal Autoexpandible", "specialty": "neuro-intervencion", "categories": [{"slug": "stent-neuro", "name": "Stent"}], "category": "Stent", "brand": "Balt", "summary": "Familia de stents intracraneales autoexpandibles de nitinol diseñada para la reconstrucción vascular y el tratamiento asistido con coils de aneurismas intracraneales complejos. Su tecnología de celdas deslizantes, alta visibilidad fluoroscópica y capacidad de recaptura proporcionan un despliegue seguro y preciso incluso en anatomías desafiantes.", "content": "<p><strong>Beneficios Clínicos:</strong></p>\n<p> </p>\n<ul>\n<li> <strong>LEO+: Soporte Óptimo para Embolización con Coils. </strong>Su diseño trenzado proporciona una alta fuerza radial que favorece la retención de coils, ayudando a mantener la estabilidad del tratamiento en aneurismas de cuello ancho y fusiformes.</li>\n</ul>\n<p> </p>\n<ul>\n<li> <strong>LEO+ Baby: Acceso a Vasos Distales. </strong>Diseñado para ser implantado mediante microcatéteres de 0.017″, permitiendo el tratamiento de vasos pequeños y anatomías distales complejas.</li>\n</ul>\n<p> </p>\n<ul>\n<li><strong>Visibilidad Fluoroscópica Total: </strong>Los hilos de platino radiopaco entretejidos a lo largo de todo el stent proporcionan una visualización completa durante la navegación y el despliegue.</li>\n</ul>\n<p> </p>\n<ul>\n<li> <strong>Recaptura y Reposicionamiento Seguro: </strong>Permite recuperar y reposicionar el stent hasta un 90% de su despliegue, brindando mayor control y seguridad durante el procedimiento.</li>\n</ul>\n<p> </p>\n<ul>\n<li><strong> Excelente Adaptación a la Pared Vascular: </strong>Su diseño con celdas deslizantes y extremos acampanados favorece una aposición uniforme, mejorando la conformabilidad en vasos tortuosos y reduciendo el riesgo de mal aposicionamiento.</li>\n</ul>\n<p>\n", "image": "assets/fbbc1000fd9c84e4.webp", "pdfs": [{"url": "https://academiayumyeong.com/alfacor/wp-content/uploads/2026/02/ET-Stent-Leo-linea-102.pdf", "path": "assets/31936baf4da2256a.pdf", "name": "ET-Stent-Leo-linea-102.pdf"}], "source": "https://academiayumyeong.com/alfacor/product/leo-leo-baby-stent-intracraneal-autoexpandible/", "quickType": "Stents intracraneales autoexpandibles", "quickSpecs": [["Diseño", "Trenzado, celdas deslizantes"], ["LEO+ Baby", "Microcatéter de 0.017″"], ["Visibilidad", "Hilos de platino radiopacos"], ["Extremos", "Acampanados"]]}, {"id": 1001, "slug": "kit-retirada-filtro-aln", "name": "Kit de retirada y reposicionamiento ALN", "specialty": "vascular-periferico", "categories": [{"slug": "filtros", "name": "Filtros"}], "category": "Filtros · Retirada", "brand": "ALN Implants Chirurgicaux", "summary": "Sistema de pinza para retirar o reposicionar filtros de vena cava ALN con o sin gancho.", "content": "", "image": "assets/aln-capture.jpg", "pdfs": [], "source": "https://www.aln2b.com/en/medical-devices/kits-extraction-aln-implants-chirurgicaux", "officialSource": "https://www.aln2b.com/en/medical-devices/kits-extraction-aln-implants-chirurgicaux", "quickType": "Extracción de filtro de vena cava", "useCase": "Retirada del filtro ALN cuando ya no se requiere filtración, o reposicionamiento según valoración clínica.", "quickSpecs": [["Compatibilidad", "Filtros ALN con y sin gancho"], ["Acceso", "Yugular"], ["Vaina introductora", "9 Fr"], ["Recto · FT.902010", "Cabeza del filtro alineada; vaina de 570 mm"], ["Precurvado · FT.902010/VS2", "Cabeza inclinada; vaina de 570 mm"], ["2 en 1 · RK-2010", "Angulación ajustable; vaina de 610 mm"], ["Incluye", "Catéter-pinza, dilatador, vaina, aguja y guía J de 0.035″"]], "imageAlt": "Pinza de captura del sistema de retirada ALN · imagen oficial", "imageSource": "https://www.aln2b.com/1hUm85/1/produits/kit-extraction/aln39.jpg"}];
